export const getSupportTickets = async (userId?: string): Promise<SupportTicket[]> => {
    let q;
    if (userId) {
        q = query(collection(db, "support_tickets"), where("userId", "==", userId));
    } else {
        q = query(collection(db, "support_tickets"));
    }
    const snap = await getDocs(q);
    const tickets = snap.docs.map(d => d.data() as SupportTicket);
    return tickets.sort((a,b) => b.updatedAt - a.updatedAt);
};

export const createSupportTicket = async (ticket: Omit<SupportTicket, 'id' | 'createdAt' | 'updatedAt' | 'messages' | 'status'>, initialMessage: string, attachmentUrl?: string, attachmentType?: 'image' | 'video') => {
