// --- DATA FETCHING (REAL FIRESTORE) ---

export const getUsers = async (): Promise<User[]> => {
  const querySnapshot = await getDocs(collection(db, "users"));
  const users: User[] = [];
  querySnapshot.forEach((doc) => {
    users.push(doc.data() as User);
  });
  return users;
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  try {
    const userDoc = await getDoc(doc(db, "users", userId));
    if (userDoc.exists()) {
      return userDoc.data() as User;
    }
  } catch (e) {
    console.warn("User fetch error", e);
  }
  return undefined;
};

export const updateUser = async (updatedUser: User) => {
  const userRef = doc(db, "users", updatedUser.id);
  await updateDoc(userRef, sanitizePayload(updatedUser)); // Use spread to update fields
};

// --- POSTS ---

export const getPosts = async (): Promise<Post[]> => {
  // Realtime or One-time fetch. For simplicity, one-time fetch here.
  const q = query(collection(db, "posts"), orderBy("timestamp", "desc"));
  const querySnapshot = await getDocs(q);
  const posts: Post[] = [];
  querySnapshot.forEach((doc) => {
    posts.push(doc.data() as Post);
  });
  return posts;
};

export const addPost = async (post: Post) => {
  await setDoc(doc(db, "posts", post.id), sanitizePayload(post));
};

export const updatePost = async (updatedPost: Post) => {
  await updateDoc(doc(db, "posts", updatedPost.id), sanitizePayload(updatedPost));
};

export const deletePost = async (postId: string) => {
  await deleteDoc(doc(db, "posts", postId));
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const postRef = doc(db, "posts", postId);
  const postSnap = await getDoc(postRef);
  if (postSnap.exists()) {
    const post = postSnap.data() as Post;
    let newLikes = post.likes || [];
    if (newLikes.includes(userId)) {
      newLikes = newLikes.filter(id => id !== userId);
    } else {
      newLikes.push(userId);
      // Optional: Notification Logic here
    }
    await updateDoc(postRef, { likes: newLikes });
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const postRef = doc(db, "posts", postId);
  const postSnap = await getDoc(postRef);
  if (postSnap.exists()) {
    const post = postSnap.data() as Post;
    const newComments = [...(post.comments || []), sanitizePayload(comment)];
    await updateDoc(postRef, { comments: newComments });
  }
};

// --- CART (KEPT LOCAL FOR PERFORMANCE/SIMPLICITY IN THIS CONTEXT) ---
// Note: In a full app, cart might be in Firestore too, but local is fine for "session" cart.

export const getCart = (): CartItem[] => {
  const cartJson = localStorage.getItem(CART_KEY);
  return cartJson ? JSON.parse(cartJson) : [];
};

export const saveCart = (cart: CartItem[]) => {
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existingItem = cart.find(item => item.productId === productId && item.selectedColor === selectedColor);
  if (existingItem) {
    existingItem.quantity += quantity;
  } else {
    cart.push({ productId, quantity, selectedColor });
  }
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

