export const getPosts = async (): Promise<Post[]> => {
  const q = query(collection(db, "posts"), orderBy("timestamp", "desc"));
  const querySnapshot = await getDocs(q);
  const posts: Post[] = [];
  querySnapshot.forEach((doc) => {
    posts.push(doc.data() as Post);
  });
  return posts;
};

export const addPost = async (post: Post) => {
  // Garantia extra de sanitização para evitar "Invalid nested entity"
  await setDoc(doc(db, "posts", post.id), sanitizePayload(post));
};

export const updatePost = async (updatedPost: Post) => {
  await updateDoc(doc(db, "posts", updatedPost.id), sanitizePayload(updatedPost));
};

export const deletePost = async (postId: string) => {
  await deleteDoc(doc(db, "posts", postId));
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const postRef = doc(db, "posts", postId);
  const postSnap = await getDoc(postRef);
  if (postSnap.exists()) {
    const post = postSnap.data() as Post;
    let newLikes = post.likes || [];
    if (newLikes.includes(userId)) {
      newLikes = newLikes.filter(id => id !== userId);
    } else {
      newLikes.push(userId);
    }
    await updateDoc(postRef, { likes: newLikes });
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const postRef = doc(db, "posts", postId);
  const postSnap = await getDoc(postRef);
  if (postSnap.exists()) {
    const post = postSnap.data() as Post;
    const newComments = [...(post.comments || []), sanitizePayload(comment)];
    await updateDoc(postRef, { comments: newComments });
  }
};

