                       <XMarkIcon className="h-5 w-5" />
                    </button>
                 </div>
              )}

              <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Descreva seu Reel..." 
               rows={2}
             />
           </div>
        )}

        {/* BARRA DE FERRAMENTAS INFERIOR */}
        <div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-white/5">
           <div className="flex gap-2">
              <button 
                type="button" 
                onClick={() => { switchToType(PostType.TEXT); setShowStyleTools(!showStyleTools); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.TEXT && showStyleTools ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Estilo de Texto"
              >
                 <FontIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => { switchToType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.IMAGE ? 'bg-green-100 dark:bg-green-900/30 text-green-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Adicionar Foto"
              >
                 <PhotoIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => switchToType(PostType.REEL)}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.REEL ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Criar Reel"
              >
                 <FilmIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => switchToType(PostType.LIVE)}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.LIVE ? 'bg-red-100 dark:bg-red-900/30 text-red-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Criar Live"
              >
                 <SignalIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-yellow-500 transition-all hidden sm:block"
              >
                 <FaceSmileIcon className="h-6 w-6" />
              </button>
           </div>

           <button 
             type="submit" 
             disabled={loading || (postType !== PostType.LIVE && !content && !imageFile && !reelFile) || (postType === PostType.LIVE && !liveTitle)} 
             className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all flex items-center gap-2 min-w-[140px] justify-center"
           >
             {loading ? <><div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div> {statusText}</> : <><PaperAirplaneIcon className="h-4 w-4 -rotate-45" /> Publicar</>}
           </button>
        </div>
      </form>

      {showRecordModal && (
        <RecordReelModal 
          onClose={() => setShowRecordModal(false)} 
          onSave={handleRecordedReel} 
        />
      )}
    </div>
  );
};

export default CreatePost;

import React, { useState, useRef } from 'react';
import { User } from '../types';
import { addStory, uploadFile } from '../services/storageService';
import { XMarkIcon, SparklesIcon, ArrowUpTrayIcon, CheckCircleIcon, PhotoIcon } from '@heroicons/react/24/solid';

interface CreateStoryModalProps {
  currentUser: User;
  onClose: () => void;
  onStoryCreated: () => void;
}

const BG_COLORS = [
  'bg-blue-600', 'bg-purple-600', 'bg-red-500', 'bg-green-500', 
  'bg-orange-500', 'bg-pink-600', 'bg-black', 'bg-indigo-700',
  'bg-gradient-to-br from-blue-400 to-purple-600',
  'bg-gradient-to-br from-yellow-400 to-red-500'
];

const FONTS = [
  { id: 'font-sans', label: 'Moderna' },
  { id: 'font-serif', label: 'Clássica' },
  { id: 'font-mono', label: 'Código' },
  { id: 'font-bebas', label: 'Impacto' }
];

const CreateStoryModal: React.FC<CreateStoryModalProps> = ({ currentUser, onClose, onStoryCreated }) => {
  const [mode, setMode] = useState<'image' | 'text'>('image');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [textContent, setTextContent] = useState('');
  const [bgColor, setBgColor] = useState(BG_COLORS[0]);
  const [textColor, setTextColor] = useState('text-white');
  const [fontFamily, setFontFamily] = useState('font-sans');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');

    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Por favor, selecione apenas arquivos de imagem.');
        return;
      }
      setSelectedFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (mode === 'image' && !selectedFile) return;
    if (mode === 'text' && !textContent.trim()) return;

    setLoading(true);
    setError('');

    try {
      let finalImageUrl = undefined;
      let finalText = undefined;

      if (mode === 'image' && selectedFile) {
         finalImageUrl = await uploadFile(selectedFile, 'stories');
      } else if (mode === 'text') {
         finalText = textContent;
      }

