// --- HELPER CRÍTICO: SANITIZAÇÃO DE DADOS ---
// Remove undefined (que o Firestore rejeita) e converte para Plain Object
// Isso resolve o erro "invalid nested entity"
const sanitizePayload = (data: any): any => {
  if (data === undefined) return null;
  return JSON.parse(JSON.stringify(data, (key, value) => {
      if (value === undefined) return null; // Firestore prefere null a undefined
      return value;
  }));
};

export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// --- UPLOAD APENAS VIA FIREBASE STORAGE (SEM FALLBACK BASE64) ---
// Removemos o fallback para evitar o erro "Value too long for property"
export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  if (!file) throw new Error("Arquivo inválido");
  if (!storage) throw new Error("Serviço de armazenamento indisponível.");

  try {
    const fileName = (file as File).name ? (file as File).name : `blob_${Date.now()}`;
    // Adiciona timestamp para evitar colisão de nomes
    const storageRef = ref(storage, `${folder}/${Date.now()}_${fileName}`);

    // Upload direto
    const snapshot = await uploadBytesResumable(storageRef, file);
    const downloadURL = await getDownloadURL(snapshot.ref);

    return downloadURL;
  } catch (error: any) {
    console.error("Erro Fatal no Upload:", error);
    // IMPORTANTE: Lançamos o erro para a UI tratar. Não retornamos Base64.
    throw new Error(`Falha no upload da mídia. Verifique sua conexão com a internet. Detalhes: ${error.message}`);
  }
};

