              >
                 <FaceSmileIcon className="h-6 w-6" />
              </button>
           </div>

           <button 
             type="submit" 
             disabled={loading || (postType !== PostType.LIVE && !content && !imageFile && !reelFile) || (postType === PostType.LIVE && !liveTitle)} 
             className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all flex items-center gap-2 min-w-[140px] justify-center"
           >
             {loading ? <><div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div> {statusText}</> : <><PaperAirplaneIcon className="h-4 w-4 -rotate-45" /> Publicar</>}
           </button>
        </div>
      </form>

      {showRecordModal && (
        <RecordReelModal 
          onClose={() => setShowRecordModal(false)} 
          onSave={handleRecordedReel} 
        />
      )}
    </div>
  );
};

export default CreatePost;

import React, { useState, useRef } from 'react';
import { User } from '../types';
import { addStory, uploadFile } from '../services/storageService';
import { XMarkIcon, SparklesIcon, ArrowUpTrayIcon, CheckCircleIcon, PhotoIcon } from '@heroicons/react/24/solid';

interface CreateStoryModalProps {
  currentUser: User;
  onClose: () => void;
  onStoryCreated: () => void;
}

const BG_COLORS = [
  'bg-blue-600', 'bg-purple-600', 'bg-red-500', 'bg-green-500', 
  'bg-orange-500', 'bg-pink-600', 'bg-black', 'bg-indigo-700',
  'bg-gradient-to-br from-blue-400 to-purple-600',
  'bg-gradient-to-br from-yellow-400 to-red-500'
];

const FONTS = [
  { id: 'font-sans', label: 'Moderna' },
  { id: 'font-serif', label: 'Clássica' },
  { id: 'font-mono', label: 'Código' },
  { id: 'font-bebas', label: 'Impacto' }
];

const CreateStoryModal: React.FC<CreateStoryModalProps> = ({ currentUser, onClose, onStoryCreated }) => {
  const [mode, setMode] = useState<'image' | 'text'>('image');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [textContent, setTextContent] = useState('');
  const [bgColor, setBgColor] = useState(BG_COLORS[0]);
  const [textColor, setTextColor] = useState('text-white');
  const [fontFamily, setFontFamily] = useState('font-sans');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');

    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Por favor, selecione apenas arquivos de imagem.');
        return;
      }
      setSelectedFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (mode === 'image' && !selectedFile) return;
    if (mode === 'text' && !textContent.trim()) return;

    setLoading(true);
    setError('');

    try {
      let finalImageUrl = undefined;
      let finalText = undefined;

      if (mode === 'image' && selectedFile) {
         finalImageUrl = await uploadFile(selectedFile, 'stories');
      } else if (mode === 'text') {
         finalText = textContent;
      }

      await addStory(currentUser.id, { 
        imageUrl: finalImageUrl,
        text: finalText, 
        backgroundColor: mode === 'text' ? bgColor : undefined, 
        textColor: mode === 'text' ? textColor : undefined,
        fontFamily: mode === 'text' ? fontFamily : undefined
      });

      onStoryCreated();
      onClose();
    } catch (err: any) {
      console.error("Erro no submit do Story:", err);
      setError(err.message || 'Erro ao publicar story. Verifique sua conexão.');
    } finally {
      setLoading(false);
    }
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="fixed inset-0 z-[1000] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
