// --- CONFIGURAÇÃO CLOUDINARY ---
// Preencha aqui com as credenciais que você mencionou
const CLOUDINARY_CLOUD_NAME = "dnh07moob"; // Ex: 'demo' ou seu cloud name
const CLOUDINARY_UPLOAD_PRESET = "ml_default"; // Ex: 'cyberphone_preset' (Deve ser Unsigned)

// Local Storage Keys
const CURRENT_USER_KEY = 'cyberphone_current_user_id';
const CART_KEY = 'cyberphone_cart';

// --- HELPER CRÍTICO: SANITIZAÇÃO DE DADOS ---
// Remove undefined, Funções e Objetos complexos (File, Blob) antes de enviar ao Firestore
const sanitizePayload = (data: any): any => {
  if (data === undefined) return null;
  // O truque JSON.parse(JSON.stringify) remove automaticamente undefined e métodos
  return JSON.parse(JSON.stringify(data, (key, value) => {
      if (value === undefined) return null;
      return value;
  }));
};

export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// --- UPLOAD VIA CLOUDINARY (REST API) ---
// Muito mais estável que SDKs para uploads diretos do browser
export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  if (!file) throw new Error("Arquivo inválido");

  const formData = new FormData();
  formData.append('file', file);
  formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET); 
  formData.append('folder', `cyberphone/${folder}`);

  try {
    // Timeout de 60 segundos para evitar loop infinito
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 60000);

    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/auto/upload`, {
      method: 'POST',
      body: formData,
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      const errData = await response.json();
      console.error("Erro Cloudinary:", errData);
      throw new Error(`Erro no upload: ${errData.error?.message || 'Falha desconhecida'}`);
    }

    const data = await response.json();
    return data.secure_url; // Retorna a URL segura HTTPS

  } catch (error: any) {
    console.error("Falha Fatal no Upload:", error);

    if (error.name === 'AbortError') {
      throw new Error("O upload demorou muito e foi cancelado. Verifique sua conexão.");
    }

    // Se falhar o Cloudinary, NÃO TENTAMOS BASE64 (Offline Mode removido como pedido)
    // Apenas lançamos o erro para a UI parar de processar.
    throw new Error("Falha no serviço de upload. Verifique as credenciais do Cloudinary.");
  }
};

// --- AUTH & USER MANAGEMENT ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  const userCredential = await signInWithEmailAndPassword(auth, email, password);
  const uid = userCredential.user.uid;

  const userDoc = await getDoc(doc(db, "users", uid));
  if (userDoc.exists()) {
    const userData = userDoc.data() as User;
    return { ...userData, id: uid };
  } else {
    throw new Error("Usuário autenticado, mas perfil não encontrado.");
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
  const uid = userCredential.user.uid;

  const newUser: User = {
    id: uid,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl,
    isAdmin: false
  };

  if (newUser.userType === UserType.CREATOR) {
    const storeId = generateUUID();
    newUser.storeId = storeId;

    await setDoc(doc(db, "stores", storeId), sanitizePayload({
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
      brandColor: '#2563eb'
    }));
  }

  await setDoc(doc(db, "users", uid), sanitizePayload(newUser));
  return newUser;
};

