export const toggleFollowUser = async (currentUserId: string, targetId: string) => {
    const currentUser = await findUserById(currentUserId);
    const targetUser = await findUserById(targetId);

    if(currentUser && targetUser) {
        let following = currentUser.followedUsers || [];
        let followers = targetUser.followers || [];

        if(following.includes(targetId)) {
            following = following.filter(id => id !== targetId);
            followers = followers.filter(id => id !== currentUserId);
        } else {
            following.push(targetId);
            followers.push(currentUserId);
        }

        await updateDoc(doc(db, "users", currentUserId), { followedUsers: following });
        await updateDoc(doc(db, "users", targetId), { followers: followers });
    }
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const saleRef = doc(db, "affiliate_sales", saleId);
    const saleSnap = await getDoc(saleRef);
    if(saleSnap.exists()) {
        const sale = saleSnap.data() as AffiliateSale;
        if(sale.isRated) return;

        const productRef = doc(db, "products", sale.productId);
        const productSnap = await getDoc(productRef);
        if(productSnap.exists()) {
            const product = productSnap.data() as Product;
            const newRating: ProductRating = {
                id: generateUUID(),
                saleId,
                userId: sale.buyerId,
                rating,
                comment,
                timestamp: Date.now()
            };
            const ratings = product.ratings || [];
            ratings.push(sanitizePayload(newRating));
            const avg = ratings.reduce((acc: number, r: ProductRating) => acc + r.rating, 0) / ratings.length;

            await updateDoc(productRef, { ratings: sanitizePayload(ratings), ratingCount: ratings.length, averageRating: avg });
            await updateDoc(saleRef, { isRated: true });
        }
    }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Story } from '../types';
import { XMarkIcon, ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/solid';

interface StoryViewerModalProps {
  stories: Story[];
  initialIndex: number;
  onClose: () => void;
}

const STORY_DURATION = 5000;

const StoryViewerModal: React.FC<StoryViewerModalProps> = ({ stories, initialIndex, onClose }) => {
  const [currentUserIdx, setCurrentUserIdx] = useState(initialIndex);
  const [currentItemIdx, setCurrentItemIdx] = useState(0);
  const [progress, setProgress] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const startTimeRef = useRef<number | null>(null);
  const pausedTimeRef = useRef<number>(0);

  const currentStory = stories[currentUserIdx];
  const currentItem = currentStory?.items?.[currentItemIdx];

  const handleNext = useCallback(() => {
    if (!currentStory || !currentStory.items) { onClose(); return; }

    // Próximo Item do mesmo usuário
    if (currentItemIdx < currentStory.items.length - 1) {
      setCurrentItemIdx(prev => prev + 1);
      setProgress(0);
      startTimeRef.current = Date.now();
      pausedTimeRef.current = 0;
    } 
    // Próximo Usuário
    else if (currentUserIdx < stories.length - 1) {
      setCurrentUserIdx(prev => prev + 1);
      setCurrentItemIdx(0);
      setProgress(0);
      startTimeRef.current = Date.now();
      pausedTimeRef.current = 0;
    } 
    // Fim de tudo
    else {
      onClose();
    }
  }, [currentItemIdx, currentUserIdx, currentStory, stories.length, onClose]);

  const handlePrev = useCallback(() => {
    // Item anterior do mesmo usuário
    if (currentItemIdx > 0) {
      setCurrentItemIdx(prev => prev - 1);
      setProgress(0);
      startTimeRef.current = Date.now();
      pausedTimeRef.current = 0;
    } 
    // Usuário anterior (último item)
    else if (currentUserIdx > 0) {
      const prevUserIdx = currentUserIdx - 1;
      const prevStory = stories[prevUserIdx];
      setCurrentUserIdx(prevUserIdx);
      setCurrentItemIdx(prevStory?.items?.length ? prevStory.items.length - 1 : 0);
      setProgress(0);
      startTimeRef.current = Date.now();
      pausedTimeRef.current = 0;
    }
  }, [currentItemIdx, currentUserIdx, stories]);

  // Timer Effect
  useEffect(() => {
    if (!currentStory || !currentItem) return;

    if (isPaused) {
        // Quando pausar, calcular quanto tempo passou e salvar
        if (startTimeRef.current) {
            pausedTimeRef.current += Date.now() - startTimeRef.current;
            startTimeRef.current = null;
        }
        return;
    }

    startTimeRef.current = Date.now();

    const interval = setInterval(() => {
        if (!startTimeRef.current) return;

        const now = Date.now();
        const elapsed = now - startTimeRef.current + pausedTimeRef.current;
        const newProgress = (elapsed / STORY_DURATION) * 100;

        if (newProgress >= 100) {
            handleNext();
        } else {
            setProgress(newProgress);
        }
    }, 50);

    return () => clearInterval(interval);
  }, [handleNext, currentStory, currentItem, isPaused]);

  if (!currentStory || !currentItem) return null;

  return (
    <div className="fixed inset-0 z-[2000] bg-black flex items-center justify-center animate-fade-in">
      {/* Wrapper */}
      <div className="relative w-full h-full md:w-[400px] md:h-[85vh] md:rounded-[2rem] overflow-hidden bg-gray-900 flex flex-col shadow-2xl border-0 md:border border-white/10">

        {/* Progress Bars (WhatsApp Style) */}
        <div className="absolute top-2 left-2 right-2 z-50 flex gap-1 h-1">
          {currentStory.items?.map((_, idx) => (
            <div key={idx} className="flex-1 bg-white/30 rounded-full overflow-hidden backdrop-blur-sm">
               <div 
                 className="h-full bg-white transition-all duration-100 ease-linear shadow-[0_0_8px_rgba(255,255,255,0.8)]"
                 style={{ 
                   width: idx < currentItemIdx ? '100%' : idx === currentItemIdx ? `${progress}%` : '0%' 
                 }}
               />
            </div>
          ))}
        </div>

        {/* Header (User Info & Close) */}
        <div className="absolute top-5 left-4 right-4 flex items-center justify-between z-50 pt-2">
           <div className="flex items-center gap-3">
              <div className="p-[2px] bg-gradient-to-tr from-yellow-400 to-purple-600 rounded-full">
                <img src={currentStory.userProfilePic} className="w-9 h-9 rounded-full border-2 border-black object-cover" />
              </div>
              <div className="flex flex-col drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
                 <span className="font-bold text-white text-sm tracking-wide">{currentStory.userName}</span>
                 <span className="text-[10px] text-white/80 font-medium">
                    {new Date(currentItem.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                 </span>
              </div>
           </div>

           <button 
             onClick={(e) => { e.stopPropagation(); onClose(); }} 
             className="p-2 bg-black/20 hover:bg-white/20 backdrop-blur-md rounded-full text-white transition-all active:scale-90 shadow-sm border border-white/10"
           >
              <XMarkIcon className="h-6 w-6 stroke-2" />
           </button>
        </div>

        {/* Dark Gradient Overlay for Header Readability */}
        <div className="absolute top-0 left-0 w-full h-28 bg-gradient-to-b from-black/70 via-black/30 to-transparent pointer-events-none z-20"></div>

        {/* Content */}
        <div 
            className="flex-1 flex items-center justify-center bg-black relative w-full h-full"
            onMouseDown={() => setIsPaused(true)}
            onMouseUp={() => setIsPaused(false)}
            onTouchStart={() => setIsPaused(true)}
            onTouchEnd={() => setIsPaused(false)}
        >
           {currentItem.imageUrl ? (
              <img src={currentItem.imageUrl} className="w-full h-full object-cover" alt="Story" />
           ) : (
              <div className={`w-full h-full flex flex-col items-center justify-center text-center p-8 transition-colors duration-500 ${currentItem.backgroundColor || 'bg-blue-600'}`}>
                 <p className={`font-black leading-tight break-words max-w-full drop-shadow-md whitespace-pre-wrap ${currentItem.textColor || 'text-white'} ${currentItem.fontFamily || 'font-sans'} ${currentItem.text && currentItem.text.length > 80 ? 'text-xl md:text-2xl' : 'text-3xl md:text-4xl'}`}>
                   {currentItem.text}
                 </p>
              </div>
           )}
        </div>

        {/* Navigation Touch Zones (Invisible) */}
        <div className="absolute inset-0 z-30 flex">
           <div className="w-1/3 h-full" onClick={handlePrev}></div>
           <div className="w-1/3 h-full" onClick={() => {/* Pause trigger handled by container */}}></div>
           <div className="w-1/3 h-full" onClick={handleNext}></div>
        </div>

        {/* Desktop Arrows (Outside Frame) */}
        <button 
          onClick={(e) => { e.stopPropagation(); handlePrev(); }} 
          className="hidden md:flex absolute -left-20 top-1/2 -translate-y-1/2 p-4 bg-white/10 hover:bg-white/20 rounded-full text-white z-[60] transition-all backdrop-blur-md"
        >
           <ChevronLeftIcon className="h-8 w-8" />
        </button>
        <button 
          onClick={(e) => { e.stopPropagation(); handleNext(); }} 
          className="hidden md:flex absolute -right-20 top-1/2 -translate-y-1/2 p-4 bg-white/10 hover:bg-white/20 rounded-full text-white z-[60] transition-all backdrop-blur-md"
        >
           <ChevronRightIcon className="h-8 w-8" />
        </button>
      </div>
    </div>
  );
};

