               >
                 Acessar Painel de Comando
               </button>
            </div>
         </div>
       )}

       {/* HEADER DO PERFIL */}
       <div className="bg-white dark:bg-[#1a1c23] rounded-[3rem] shadow-2xl overflow-hidden border border-gray-100 dark:border-white/5 mb-8 relative">

          {/* Banner */}
          <div className="h-40 md:h-64 bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-900 relative">
             <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

             {/* Foto de Perfil (Posicionada com Absolute em relação ao Banner) */}
             <div className="absolute -bottom-16 left-1/2 -translate-x-1/2 md:left-12 md:translate-x-0 z-20">
                <div className="relative group">
                   <img 
                     src={profile.profilePicture} 
