                   {profile.isPremium && (
                     <div className="absolute -top-2 -right-2 bg-yellow-400 p-2 rounded-xl shadow-lg border-4 border-white dark:border-[#1a1c23] animate-bounce">
                       <TrophyIcon className="h-5 w-5 text-yellow-900" />
                     </div>
