        {/* BOTTOM LAYER - Chat & Inputs */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">

