import React, { useState, useEffect, useMemo } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostSaves, 
  unpinPost, 
  pinPost,
  createReport,
  updatePostShares,
  deletePost,
  getOptimizedVideoUrl
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  CheckBadgeIcon,
  MapPinIcon as PinIconOutline,
  SignalIcon,
  ShareIcon,
  PlayIcon,
  UserGroupIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon,
  VideoCameraIcon
} from '@heroicons/react/24/solid';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';
import IndicateModal from './IndicateModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  // Optimistic UI states
  const [localLikes, setLocalLikes] = useState<string[]>(post.likes || []);
  const [isLiked, setIsLiked] = useState(post.likes?.includes(currentUser.id) || false);
  const [localSaves, setLocalSaves] = useState<string[]>(post.saves || []);
  const [isSaved, setIsSaved] = useState(post.saves?.includes(currentUser.id) || false);

  const isFollowing = currentUser.followedUsers?.includes(post.userId);

  // Gera um delay aleatório para a animação de flutuação, para que os cards não se movam em uníssono.
  const animationDelay = useMemo(() => `${Math.random() * 5}s`, []);

  useEffect(() => {
    setLocalLikes(post.likes || []);
    setIsLiked(post.likes?.includes(currentUser.id) || false);
    setLocalSaves(post.saves || []);
    setIsSaved(post.saves?.includes(currentUser.id) || false);
  }, [post.likes, post.saves, currentUser.id]);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();
  }, [post.userId]);

  if (!post || !currentUser || !post.id || !postAuthor) return null;

  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsLiked = isLiked;
    const prevLikes = [...localLikes];

    setIsLiked(!prevIsLiked);
    if (prevIsLiked) {
      setLocalLikes(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalLikes(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostLikes(post.id, currentUser.id);
    } catch (error) {
      setIsLiked(prevIsLiked);
      setLocalLikes(prevLikes);
      console.error("Falha ao curtir post", error);
    }
  };

  const handleSave = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsSaved = isSaved;
    const prevSaves = [...localSaves];

    setIsSaved(!prevIsSaved);
    if (prevIsSaved) {
      setLocalSaves(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalSaves(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostSaves(post.id, currentUser.id);
    } catch (error) {
      setIsSaved(prevIsSaved);
      setLocalSaves(prevSaves);
    }
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';
  const contentLength = post.content?.length || 0;

  // Lógica Adaptativa de Tamanho (Otimizada para Mobile)
  let containerMinHeight = 'auto';
  let fontSizeClass = 'text-sm md:text-lg text-gray-900 dark:text-white';
  let paddingClass = 'py-2';

  if (hasBg) {
    if (contentLength < 60) {
        // Frase Curta
        containerMinHeight = '180px md:min-h-[200px]'; 
        fontSizeClass = `${post.textColor || 'text-white'} text-2xl md:text-4xl leading-tight`;
        paddingClass = 'p-6 md:p-8';
    } else if (contentLength < 150) {
        // Frase Média
        containerMinHeight = '220px md:min-h-[300px]';
        fontSizeClass = `${post.textColor || 'text-white'} text-lg md:text-2xl leading-snug`;
        paddingClass = 'p-6 md:p-10';
    } else {
        // Texto Longo
        containerMinHeight = '280px md:min-h-[400px]';
        fontSizeClass = `${post.textColor || 'text-white'} text-base md:text-xl leading-relaxed`;
        paddingClass = 'p-8 md:p-12';
    }
  }

  // Verifica se é um Replay de Live (Gravada)
  const isRecordedLive = post.type === PostType.LIVE && post.liveStream?.status === 'ENDED' && post.liveStream.recordingUrl;

  return (
    <>
      <div 
        onClick={() => {
          if (post.type === PostType.LIVE && post.liveStream?.status !== 'ENDED') onNavigate('live', { postId: post.id });
          else if (post.type === PostType.REEL) onNavigate('reels-page', { startPostId: post.id });
          else if (!isRecordedLive) setShowDetailModal(true); // Don't open detail modal on video click if handled inside
        }}
        style={{ animationDelay }}
        className="bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 cursor-pointer group animate-float hover-pause hover:shadow-2xl hover:-translate-y-2 transition-all duration-300"
      >
        <div className="p-4 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-5 min-w-0">
            <div className="relative cursor-pointer shrink-0" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-brand rounded-lg md:rounded-xl p-0.5 md:p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-3 w-3 md:h-4 md:w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-col">
                <div className="flex items-center gap-1 md:gap-2">
                  <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-xl truncate tracking-tighter hover:text-brand transition-colors">
                      {postAuthor.firstName}
                  </h4>
                  {post.isPinned && <PinIconSolid className="h-3 w-3 md:h-4 md:w-4 text-brand shrink-0" />}
                  {isPostBoosted && <BoltIcon className="h-3 w-3 md:h-4 md:w-4 text-orange-500 animate-pulse shrink-0" />}
                </div>
                {post.groupId && (
                  <div className="flex items-center gap-1 text-[8px] md:text-[9px] font-black text-brand uppercase tracking-widest mt-0.5 truncate">
                     <UserGroupIcon className="h-3 w-3" /> <span className="truncate">{post.groupName}</span>
                  </div>
                )}
              </div>
              <p className="text-[8px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5 truncate">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-brand">⚡ Promo</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-2 md:p-3 rounded-xl md:rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-brand transition-all shrink-0"
          >
            <EllipsisHorizontalIcon className="h-6 w-6 md:h-7 md:w-7" />
          </button>
        </div>

        <div className={`px-4 md:px-8 ${hasBg ? 'pb-6 md:pb-8' : 'pb-4'}`}>

          {/* CASO: LIVE ATIVA */}
          {post.type === PostType.LIVE && !post.liveStream?.recordingUrl && post.liveStream ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute top-4 left-4 md:top-6 md:left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-3 py-1 md:px-4 md:py-1.5 rounded-full text-[9px] md:text-[10px] font-black flex items-center gap-1.5 shadow-2xl animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3 md:h-3.5 md:w-3.5" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-6 md:py-8 flex flex-col items-center text-center">
                   <h3 className="text-xl md:text-4xl font-black mb-6 md:mb-8 tracking-tighter uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button className="bg-brand text-white px-8 py-4 md:px-10 md:py-5 rounded-[2rem] md:rounded-[2.2rem] font-black text-[10px] md:text-sm uppercase tracking-[0.2em] shadow-xl flex items-center justify-center gap-3 md:gap-4">
                      <PlayIcon className="h-5 w-5 md:h-6 md:w-6" /> Entrar Agora
                   </button>
                </div>
             </div>
          ) : 

          /* CASO: LIVE GRAVADA (REPLAY) */
          isRecordedLive ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-black relative shadow-xl mt-2 aspect-video flex items-center justify-center group">
                <video 
                  src={getOptimizedVideoUrl(post.liveStream!.recordingUrl!)} 
                  className="w-full h-full object-cover" 
                  controls
                  playsInline
                  preload="metadata"
                />
                <div className="absolute top-4 left-4 bg-purple-600/90 backdrop-blur-md px-3 py-1.5 rounded-xl text-[9px] font-black uppercase text-white shadow-lg flex items-center gap-2 pointer-events-none">
                   <VideoCameraIcon className="h-3 w-3" /> Aula Gravada
                </div>
                <div className="absolute bottom-0 left-0 w-full p-4 md:p-6 bg-gradient-to-t from-black/80 to-transparent pointer-events-none">
                   <p className="text-white text-xs md:text-sm font-medium line-clamp-2">{post.liveStream?.title}</p>
                </div>
             </div>
          ) :

          /* CASO: REEL */
          post.type === PostType.REEL && post.reel ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-black relative shadow-xl mt-2 aspect-[9/16] max-h-[500px] md:max-h-[600px] flex items-center justify-center group">
                <video 
                  src={getOptimizedVideoUrl(post.reel.videoUrl)} 
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-500" 
                  muted 
                  loop 
                  playsInline
                  preload="metadata"
                  onMouseOver={(e) => e.currentTarget.play()}
                  onMouseOut={(e) => e.currentTarget.pause()}
                />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                   <div className="bg-white/20 backdrop-blur-md p-3 md:p-4 rounded-full border border-white/10 group-hover:scale-110 transition-transform">
                      <PlayIcon className="h-8 w-8 md:h-10 md:w-10 text-white fill-white" />
                   </div>
                </div>
                <div className="absolute bottom-0 left-0 w-full p-4 md:p-6 bg-gradient-to-t from-black/80 to-transparent pointer-events-none">
                   <p className="text-white text-xs md:text-sm font-medium line-clamp-2">{post.reel.description}</p>
                </div>
             </div>
          ) : (
            /* CASO: POST NORMAL (TEXTO/IMAGEM) */
            <>
              {post.content && (
                <div 
                  className={`rounded-[2rem] md:rounded-[3rem] transition-all duration-500 w-full flex items-center justify-center
                    ${hasBg ? `${post.backgroundColor} text-center shadow-inner mb-4` : 'text-left bg-transparent'} 
                    ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    // Use a classe para altura mínima, o style é override se necessário
                  }}
                >
                  <div className={`w-full ${hasBg ? containerMinHeight : ''} flex items-center justify-center ${hasBg ? paddingClass : 'p-0'}`}>
                    <p className={`font-black whitespace-pre-wrap break-words w-full ${fontSizeClass}`}>
                      {post.content}
                    </p>
                  </div>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl mt-2">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[500px] md:max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-4 md:px-12 py-4 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-2 md:gap-3 px-4 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${isLiked ? 'text-brand bg-brand/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {isLiked ? <HeartIconSolid className="h-5 w-5 md:h-8 md:w-8" /> : <HeartIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{localLikes.length}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 md:gap-3 px-4 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ChatIconOutline className="h-5 w-5 md:h-8 md:w-8" />
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button className="p-3 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ShareIcon className="h-5 w-5 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={handleSave} className={`p-3 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${isSaved ? 'text-brand bg-brand/10' : 'text-gray-300 hover:bg-gray-50'}`}>
            {isSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor} 
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)} 
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }} 
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }} 
          onPin={() => { if(post.isPinned) unpinPost(post.id, currentUser.id); else pinPost(post.id, currentUser.id); onPostUpdatedOrDeleted(); setShowActionsModal(false); }} 
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }} 
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }} 
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }} 
          onReport={() => { 
            if(window.confirm("Deseja realmente denunciar esta publicação?")) {
              createReport({ reporterId: currentUser.id, targetId: post.id, targetType: 'POST', reason: 'DENÚNCIA', details: 'Via PostCard' }); 
              alert("Denúncia enviada com sucesso. Nossa equipe irá analisar.");
              setShowActionsModal(false); 
            }
          }} 
        />
      )}

      {showDetailModal && <PostDetailModal post={post} currentUser={currentUser} onClose={() => setShowDetailModal(false)} onUpdate={onPostUpdatedOrDeleted} onNavigate={onNavigate} refreshUser={refreshUser} />}
      {showBoostModal && <BoostPostModal post={post} currentUser={currentUser} onClose={() => setShowBoostModal(false)} onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }} />}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)} 
          onConfirm={async () => { 
            await deletePost(post.id); 
            onPostUpdatedOrDeleted(); 
            setShowDeleteModal(false); 
          }} 
        />
      )}

      {showEditModal && <EditPostModal postId={post.id} currentUser={currentUser} onClose={() => setShowEditModal(false)} onSuccess={onPostUpdatedOrDeleted} />}
      {showIndicateModal && <IndicateModal post={post} currentUser={currentUser} onClose={() => setShowIndicateModal(false)} onPostUpdated={onPostUpdatedOrDeleted} />}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Comment, PostType } from '../types';
import { 
  getPosts, 
  findUserById, 
  processDonation, 
  deletePost, 
  updatePost,
  subscribeToLivePost,
  sendLiveMessage,
  manageLiveViewers,
  pulseLiveHeart,
  generateUUID,
  uploadFile
} from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  SignalIcon, 
  UsersIcon, 
  PowerIcon, 
  BanknotesIcon, 
  PaperAirplaneIcon, 
  SparklesIcon, 
  HeartIcon, 
  EllipsisHorizontalIcon, 
  HandRaisedIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [isHandRaised, setIsHandRaised] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // GRAVAÇÃO DA LIVE
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const stopRecordingResolver = useRef<((blob: Blob) => void) | null>(null); // Resolver para Promise de stop
  const [isSavingReplay, setIsSavingReplay] = useState(false);

  // Ref para verificar se já inicializou a câmera e evitar re-renders
  const isInitializedRef = useRef(false);

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription to Live Data
  useEffect(() => {
    if (!postId) return;

    // Entrar na Live (Incrementar Viewer)
    manageLiveViewers(postId, 'join');

    // Inscrever para atualizações
    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        // Se a live acabou, sair
        if (updatedPost.liveStream?.status === 'ENDED') {
            onNavigate('feed');
            return;
        }

        // Atualizar Chat
        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        // Atualizar Viewers
        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        // Detectar novos corações para animação
        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            // Spawn hearts based on difference (limit to avoid crash)
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    // Cleanup: Sair da Live (Decrementar Viewer)
    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount]);

  // Scroll to bottom of chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const startRecording = (stream: MediaStream) => {
    // SÓ GRAVA SE FOR LIVE GRATUITA
    // Verificação de segurança, mas a chamada principal já deve filtrar
    if (post?.liveStream?.isPaid) return;

    recordedChunksRef.current = [];
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm';

    try {
        const recorder = new MediaRecorder(stream, { mimeType });

        recorder.ondataavailable = (event) => {
            if (event.data && event.data.size > 0) {
                recordedChunksRef.current.push(event.data);
            }
        };

        recorder.onstop = () => {
            const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
            if (stopRecordingResolver.current) {
                stopRecordingResolver.current(blob);
                stopRecordingResolver.current = null;
            }
        };

        recorder.start(1000); // Chunk a cada 1s
        mediaRecorderRef.current = recorder;
        console.log("Gravação de Live iniciada.");
    } catch (e) {
        console.error("Erro ao iniciar gravação da live:", e);
    }
  };

  const handleEndLive = async () => {
    if (!post) return;
    const isPaid = post.liveStream?.isPaid;

    const msg = isPaid 
        ? "Encerrar transmissão? Por ser uma aula paga, ela NÃO será gravada e desaparecerá." 
        : "Encerrar transmissão? Ela será salva automaticamente na aba 'Aulas' do seu perfil.";

    if (!window.confirm(msg)) return;

    // Se for paga, deleta e sai
    if (isPaid) {
        if (mediaRecorderRef.current) mediaRecorderRef.current.stop();
        await deletePost(post.id);
        handleExit();
        return;
    }

    // Se for grátis, salva replay
    setIsSavingReplay(true);

    try {
        let finalBlob: Blob | null = null;

        // Promessa que resolve quando o gravador realmente parar e montar o blob
        const stopPromise = new Promise<Blob>((resolve) => {
            stopRecordingResolver.current = resolve;
            if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
                mediaRecorderRef.current.stop();
            } else {
                // Se já estava parado ou nunca iniciou
                resolve(new Blob(recordedChunksRef.current, { type: 'video/webm' }));
            }
        });

        finalBlob = await stopPromise;

        if (finalBlob && finalBlob.size > 0) {
            const videoUrl = await uploadFile(finalBlob, 'replays');

            if (videoUrl) {
                // Atualiza o post existente para status ENDED e adiciona URL
                const updatedPost: Post = {
                    ...post,
                    liveStream: {
                        ...post.liveStream!,
                        status: 'ENDED',
                        recordingUrl: videoUrl
                    },
                    content: `Aula Gravada: ${post.liveStream?.title}`,
                };
                await updatePost(updatedPost);
                alert("Aula salva com sucesso! Disponível no seu perfil.");
            }
        } else {
            console.warn("Blob vazio, live curta demais?");
            await deletePost(post.id);
        }
    } catch (e) {
        console.error("Erro ao salvar replay:", e);
        alert("Erro ao salvar replay. A live será encerrada sem salvar.");
        await deletePost(post.id);
    } finally {
        handleExit();
        refreshUser();
    }
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  // Inicialização da Câmera e Gravação
  useEffect(() => {
      // Executa apenas se for o criador, se o post estiver carregado e se ainda não foi inicializado
      if (creator && currentUser.id === creator.id && post && !isInitializedRef.current) {
          isInitializedRef.current = true; // Marca como inicializado para evitar re-execução

          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }

                  // Iniciar gravação automática se for live gratuita
                  if (!post.liveStream?.isPaid) {
                      startRecording(stream);
                  }
              } catch (e) {
                  console.error("Erro camera:", e);
                  alert("Erro ao acessar câmera. Verifique permissões.");
              }
          };
          initCam();
      }
  }, [creator, currentUser.id, post]); // Dependências mantidas, mas protegidas pelo ref isInitialized

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = async () => {
    if (!pendingAmount || !creator || !post) return;

    if ((currentUser.balance || 0) < pendingAmount) { 
        alert("Saldo insuficiente."); 
        return; 
    }

    setIsProcessingDonation(true);

    const success = await processDonation(currentUser.id, creator.id, pendingAmount, `Live: ${post.liveStream?.title || 'Aula'}`);

    if (success) {
        refreshUser();
        setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

        const sysMsg: Comment = {
            id: generateUUID(),
            userId: 'system',
            userName: 'Sistema',
            text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
            timestamp: Date.now()
        };
        sendLiveMessage(postId, sysMsg);
        pulseLiveHeart(postId);

        setTimeout(() => setDonationAlert(null), 5000);
        setIsProcessingDonation(false);
        setPendingAmount(null);
        setShowDonationModal(false);
    } else {
        alert("Erro ao processar doação.");
        setIsProcessingDonation(false);
    }
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); 

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); 
      pulseLiveHeart(postId); 
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  if (isSavingReplay) {
      return (
          <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center text-white">
              <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <h2 className="text-xl font-black uppercase tracking-widest">Salvando Aula...</h2>
              <p className="text-gray-400 text-xs mt-2">Otimizando vídeo para a galeria. Aguarde...</p>
          </div>
      );
  }

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          // Visão do Criador (Local Video Mirror)
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          // Visão do Espectador
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             {/* Simulação de Player */}
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER - Mobile Optimized */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           {/* Left: Profile Info */}
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           {/* Right: Controls & Viewers */}
           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button onClick={isProfessional ? handleEndLive : handleExit} className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90">
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* MIDDLE LAYER - Gift Alerts & Hearts */}
        <div className="flex-1 relative w-full pointer-events-none">
           {/* Donation/Gift Alert Centered Top */}
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {/* Hand Raised Indicator (if self) */}
           {isHandRaised && (
             <div className="absolute top-20 right-4 animate-bounce">
                <div className="bg-yellow-500 text-black p-2 rounded-full shadow-lg border-2 border-white">
                   <HandRaisedIcon className="h-6 w-6" />
                </div>
             </div>
           )}

           {/* Floating Hearts Container - Right Side */}
           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER - Chat & Inputs */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">

           {/* Chat List - Limit Height & Width on Mobile */}
           <div className="w-[85%] md:w-[400px] h-40 md:h-64 overflow-y-auto no-scrollbar mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade mb-2">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.userId === currentUser.id ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.userName}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           {/* Input Row */}
           <div className="flex items-center gap-2 md:gap-3 pb-safe mb-2 md:mb-0">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-lg rounded-full px-4 py-3 border border-white/10 focus-within:bg-white/20 transition-all shadow-lg min-w-0">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   onFocus={() => { /* logic to handle keyboard overlap if needed */ }}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full min-w-0"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white/80 hover:text-blue-400 transition-colors disabled:opacity-30 shrink-0">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <div className="flex items-center gap-2 shrink-0">
                 <button 
                   onClick={handleSendHeart}
                   className="p-3 bg-gradient-to-tr from-pink-500 to-red-600 text-white rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-transform"
                 >
                    <HeartIcon className="h-5 w-5" />
                 </button>

                 <div className="relative">
                    <button 
                      onClick={() => setShowControls(!showControls)} 
                      className="p-3 bg-gray-800 rounded-full border border-white/20 text-white hover:bg-gray-700 transition-all shadow-lg"
                    >
                        <EllipsisHorizontalIcon className="h-5 w-5" />
                    </button>

                    {/* DROPDOWN MENU */}
                    {showControls && (
                        <div className="absolute bottom-full right-0 mb-4 bg-black/90 border border-white/10 rounded-2xl p-2 flex flex-col gap-2 shadow-2xl backdrop-blur-xl animate-scale-in origin-bottom-right min-w-[60px] items-center z-50">
                            {isProfessional ? (
                                <>
                                    <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Microfone">
                                        {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                                    </button>
                                    <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Câmera">
                                        {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                                    </button>
                                    <div className="h-px w-full bg-white/10 my-1"></div>
                                    <button onClick={handleEndLive} className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all text-white" title="Encerrar">
                                        <PowerIcon className="h-5 w-5" />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button 
                                        onClick={() => { setShowDonationModal(true); setShowControls(false); }}
                                        className="p-3 bg-yellow-500 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-90 transition-transform"
                                        title="Apoiar"
                                    >
                                        <BanknotesIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                        onClick={toggleHandRaise}
                                        className={`p-3 rounded-full transition-all active:scale-90 ${isHandRaised ? 'bg-orange-500 text-white' : 'bg-white/10 text-white'}`}
                                        title="Levantar Mão"
                                    >
                                        {isHandRaised ? <HandRaisedIcon className="h-5 w-5" /> : <HandRaisedOutline className="h-5 w-5" />}
                                    </button>
                                </>
                            )}
                        </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      </div>

      {/* MODAL APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .mask-gradient-chat {
           mask-image: linear-gradient(to top, black 85%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 85%, transparent 100%);
        }
        .pb-safe {
           padding-bottom: max(env(safe-area-inset-bottom), 20px);
        }
        @keyframes slide-right-fade {
           from { opacity: 0; transform: translateX(-10px); }
           to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-right-fade { animation: slide-right-fade 0.2s ease-out forwards; }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Comment, PostType } from '../types';
import { 
  getPosts, 
  findUserById, 
  processDonation, 
  deletePost, 
  updatePost,
  subscribeToLivePost,
  sendLiveMessage,
  manageLiveViewers,
  pulseLiveHeart,
  generateUUID,
  uploadFile
} from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  SignalIcon, 
  UsersIcon, 
  PowerIcon, 
  BanknotesIcon, 
  PaperAirplaneIcon, 
  SparklesIcon, 
  HeartIcon, 
  EllipsisHorizontalIcon, 
  HandRaisedIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [isHandRaised, setIsHandRaised] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // GRAVAÇÃO DA LIVE
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const stopRecordingResolver = useRef<((blob: Blob) => void) | null>(null); // Resolver para Promise de stop
  const [isSavingReplay, setIsSavingReplay] = useState(false);

  // Ref para verificar se já inicializou a câmera e evitar re-renders
  const isInitializedRef = useRef(false);

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        // streamRef.current?.removeTrack(track); // Removido para evitar erros em alguns navegadores
      });
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      try {
        mediaRecorderRef.current.stop();
      } catch (e) {
        console.warn("Erro ao parar gravador no cleanup:", e);
      }
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription to Live Data
  useEffect(() => {
    if (!postId) return;

    // Entrar na Live (Incrementar Viewer)
    manageLiveViewers(postId, 'join');

    // Inscrever para atualizações
    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        // Se a live acabou, sair
        if (updatedPost.liveStream?.status === 'ENDED') {
            onNavigate('feed');
            return;
        }

        // Atualizar Chat
        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        // Atualizar Viewers
        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        // Detectar novos corações para animação
        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            // Spawn hearts based on difference (limit to avoid crash)
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    // Cleanup: Sair da Live (Decrementar Viewer)
    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount]);

  // Scroll to bottom of chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const startRecording = (stream: MediaStream) => {
    // SÓ GRAVA SE FOR LIVE GRATUITA
    if (post?.liveStream?.isPaid) return;

    recordedChunksRef.current = [];
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm';

    try {
        const recorder = new MediaRecorder(stream, { mimeType });

        recorder.ondataavailable = (event) => {
            if (event.data && event.data.size > 0) {
                recordedChunksRef.current.push(event.data);
            }
        };

        recorder.onstop = () => {
            const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
            if (stopRecordingResolver.current) {
                stopRecordingResolver.current(blob);
                stopRecordingResolver.current = null;
            }
        };

        recorder.start(1000); // Chunk a cada 1s
        mediaRecorderRef.current = recorder;
        console.log("Gravação de Live iniciada.");
    } catch (e) {
        console.error("Erro ao iniciar gravação da live:", e);
    }
  };

  const handleEndLive = async () => {
    if (!post) return;
    const isPaid = post.liveStream?.isPaid;

    const msg = isPaid 
        ? "Encerrar transmissão? Por ser uma aula paga, ela NÃO será gravada e desaparecerá." 
        : "Encerrar transmissão? Ela será salva automaticamente na aba 'Aulas' do seu perfil.";

    if (!window.confirm(msg)) return;

    // Feedback imediato
    setIsSavingReplay(true);

    try {
        // Se for paga, apenas deleta
        if (isPaid) {
            if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
                mediaRecorderRef.current.stop();
            }
            await deletePost(post.id);
            alert("Aula encerrada.");
        } else {
            // Se for grátis, tenta salvar
            let finalBlob: Blob | null = null;

            // Promessa com timeout de segurança para parar o gravador
            const stopPromise = new Promise<Blob>((resolve) => {
                // Se não estiver gravando, resolve vazio
                if (!mediaRecorderRef.current || mediaRecorderRef.current.state === 'inactive') {
                    resolve(new Blob(recordedChunksRef.current, { type: 'video/webm' }));
                    return;
                }

                stopRecordingResolver.current = resolve;
                try {
                    mediaRecorderRef.current.stop();
                } catch (err) {
                    console.warn("Erro ao parar recorder:", err);
                    resolve(new Blob(recordedChunksRef.current, { type: 'video/webm' }));
                }

                // Timeout de segurança: Se o evento onstop não disparar em 2s, resolve manualmente
                setTimeout(() => {
                    if (stopRecordingResolver.current) {
                        console.warn("Timeout ao parar gravação, salvando o que temos.");
                        resolve(new Blob(recordedChunksRef.current, { type: 'video/webm' }));
                        stopRecordingResolver.current = null;
                    }
                }, 2000);
            });

            finalBlob = await stopPromise;

            if (finalBlob && finalBlob.size > 0) {
                const videoUrl = await uploadFile(finalBlob, 'replays');

                if (videoUrl) {
                    const updatedPost: Post = {
                        ...post,
                        liveStream: {
                            ...post.liveStream!,
                            status: 'ENDED',
                            recordingUrl: videoUrl
                        },
                        content: `Aula Gravada: ${post.liveStream?.title}`,
                    };
                    await updatePost(updatedPost);
                    alert("Aula salva com sucesso! Disponível no seu perfil.");
                } else {
                    throw new Error("Falha no upload do vídeo.");
                }
            } else {
                // Se não gravou nada (ex: erro no inicio), deleta para não ficar live fantasma
                await deletePost(post.id);
                alert("Live encerrada (sem gravação disponível).");
            }
        }
    } catch (e) {
        console.error("Erro ao encerrar live:", e);
        // Em caso de erro grave, tenta limpar o post para não travar
        if(post && post.id) await deletePost(post.id);
        alert("Erro ao salvar. A live foi encerrada.");
    } finally {
        handleExit();
        refreshUser();
    }
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  // Inicialização da Câmera e Gravação
  useEffect(() => {
      // Executa apenas se for o criador, se o post estiver carregado e se ainda não foi inicializado
      if (creator && currentUser.id === creator.id && post && !isInitializedRef.current) {
          isInitializedRef.current = true; // Marca como inicializado para evitar re-execução

          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }

                  // Iniciar gravação automática se for live gratuita
                  if (!post.liveStream?.isPaid) {
                      startRecording(stream);
                  }
              } catch (e) {
                  console.error("Erro camera:", e);
                  alert("Erro ao acessar câmera. Verifique permissões.");
              }
          };
          initCam();
      }
  }, [creator, currentUser.id, post]); // Dependências mantidas, mas protegidas pelo ref isInitialized

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = async () => {
    if (!pendingAmount || !creator || !post) return;

    if ((currentUser.balance || 0) < pendingAmount) { 
        alert("Saldo insuficiente."); 
        return; 
    }

    setIsProcessingDonation(true);

    const success = await processDonation(currentUser.id, creator.id, pendingAmount, `Live: ${post.liveStream?.title || 'Aula'}`);

    if (success) {
        refreshUser();
        setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

        const sysMsg: Comment = {
            id: generateUUID(),
            userId: 'system',
            userName: 'Sistema',
            text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
            timestamp: Date.now()
        };
        sendLiveMessage(postId, sysMsg);
        pulseLiveHeart(postId);

        setTimeout(() => setDonationAlert(null), 5000);
        setIsProcessingDonation(false);
        setPendingAmount(null);
        setShowDonationModal(false);
    } else {
        alert("Erro ao processar doação.");
        setIsProcessingDonation(false);
    }
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); 

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); 
      pulseLiveHeart(postId); 
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  if (isSavingReplay) {
      return (
          <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center text-white p-4 text-center">
              <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-6"></div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Encerrando Transmissão...</h2>
              <p className="text-gray-400 text-sm">Salvando sua aula na nuvem. Isso pode levar alguns segundos.</p>
              <p className="text-gray-600 text-xs mt-4">Não feche a página.</p>
          </div>
      );
  }

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          // Visão do Criador (Local Video Mirror)
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          // Visão do Espectador
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             {/* Simulação de Player */}
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER - Mobile Optimized */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           {/* Left: Profile Info */}
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           {/* Right: Controls & Viewers */}
           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button 
                onClick={isProfessional ? handleEndLive : handleExit} 
                className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90"
              >
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
