// --- LIVE STREAMING & REALTIME ---

// IMPORTANTE: Como estamos usando Firestore básico para este protótipo,
// a função subscribeToLivePost usará um Polling agressivo para simular tempo real.
// Em produção, isso seria substituído por onSnapshot do Firestore.
export const subscribeToLivePost = (postId: string, callback: (post: Post | null) => void) => {
    // Busca inicial
    const checkPost = async () => {
        try {
            const postDoc = await getDoc(doc(db, "posts", postId));
            if (postDoc.exists()) {
                callback(postDoc.data() as Post);
            } else {
                callback(null);
            }
        } catch (e) {
            console.error("Erro no polling da live:", e);
        }
    };

    checkPost(); // Executa imediatamente

    // Polling a cada 1.5s
    const intervalId = setInterval(checkPost, 1500);

    // Função de cleanup
    return () => clearInterval(intervalId);
};

export const sendLiveMessage = async (postId: string, comment: Comment) => {
    const postRef = doc(db, "posts", postId);
    const postSnap = await getDoc(postRef);
    if (postSnap.exists()) {
        const post = postSnap.data() as Post;
        const currentChat = post.liveChat || [];
