  return snap.docs.map(d => d.data() as Story);
};

export const addStory = async (uId: string, item: any) => {
  const q = query(collection(db, "stories"), where("userId", "==", uId));
  const snap = await getDocs(q);

  const newItem = { 
      ...item, 
      id: generateUUID(), 
      timestamp: Date.now() 
  };

  if (!snap.empty) {
      const docRef = doc(db, "stories", snap.docs[0].id);
      const story = snap.docs[0].data() as Story;
      const currentItems = story.items || [];
      const updatedItems = [...currentItems, sanitizePayload(newItem)];
      await updateDoc(docRef, { items: updatedItems });
  } else {
      const user = await findUserById(uId);
      if (!user) return;
      const newStory: Story = {
          userId: uId,
          userName: user.firstName,
          userProfilePic: user.profilePicture || '',
          items: [sanitizePayload(newItem)]
      };
      await addDoc(collection(db, "stories"), sanitizePayload(newStory));
  }
};

