export const toggleJoinEvent = async (eId: string, uId: string) => {
    const ref = doc(db, "events", eId);
    const snap = await getDoc(ref);
    if(snap.exists()) {
        const evt = snap.data() as CyberEvent;
        let attendees = evt.attendees || [];
        if(attendees.includes(uId)) attendees = attendees.filter(id => id !== uId);
        else attendees.push(uId);
        await updateDoc(ref, { attendees });
    }
};

export const updatePostSaves = async (postId: string, userId: string) => { 
    const postRef = doc(db, "posts", postId);
    const postSnap = await getDoc(postRef);
    if (postSnap.exists()) {
        const post = postSnap.data() as Post;
        let saves = post.saves || [];
        if(saves.includes(userId)) saves = saves.filter(id => id !== userId);
        else saves.push(userId);
        await updateDoc(postRef, { saves });
    }
};
export const updatePostShares = async (postId: string, userId: string) => { 
    const postRef = doc(db, "posts", postId);
    const postSnap = await getDoc(postRef);
    if (postSnap.exists()) {
        const post = postSnap.data() as Post;
        let shares = post.shares || [];
        if(!shares.includes(userId)) shares.push(userId);
        await updateDoc(postRef, { shares });
    }
};
export const unpinPost = async (postId: string, userId: string) => { 
    await updateDoc(doc(db, "posts", postId), { isPinned: false });
};
export const pinPost = async (postId: string, userId: string) => { 
    const q = query(collection(db, "posts"), where("userId", "==", userId), where("isPinned", "==", true));
    const snap = await getDocs(q);
    snap.forEach(async d => {
        await updateDoc(doc(db, "posts", d.id), { isPinned: false });
    });
    await updateDoc(doc(db, "posts", postId), { isPinned: true });
};

export const deleteMessage = async (chatId: string, messageId: string) => { 
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;
        const newMessages = chat.messages.map(m => m.id === messageId ? { ...m, isDeleted: true, text: undefined, imageUrl: undefined } : m);
        await updateDoc(chatRef, { messages: sanitizePayload(newMessages) });
    }
};
