export const getAffiliateSales = async (): Promise<AffiliateSale[]> => getLocal(KEYS.SALES, []);
export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const sales = getLocal<AffiliateSale[]>(KEYS.SALES, []);
  const products = getLocal<Product[]>(KEYS.PRODUCTS, []);
  const stores = getLocal<Store[]>(KEYS.STORES, []);
  const users = getLocal<User[]>(KEYS.USERS, []);

  for (const item of cartItems) {
    const product = products.find(p => p.id === item.productId);
    if (!product) continue;
    const store = stores.find(s => s.id === product.storeId);
    if (!store) continue;
    const owner = users.find(u => u.id === store.professorId);
    if (!owner) continue;

    const total = product.price * item.quantity;
    const net = total * (1 - product.affiliateCommissionRate);
    owner.balance = (owner.balance || 0) + net;

    let commission = 0;
    if (affiliateUserId) {
        const aff = users.find(u => u.id === affiliateUserId);
        if (aff) {
            commission = total * product.affiliateCommissionRate;
            aff.balance = (aff.balance || 0) + commission;
            createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: aff.id, actorId: buyerId, timestamp: Date.now() });
        }
    }

    sales.push({
        id: generateUUID(),
        productId: item.productId,
        buyerId,
        affiliateUserId: affiliateUserId || '',
        storeId: product.storeId,
        commissionEarned: commission,
        saleAmount: total,
        timestamp: Date.now(),
        status: OrderStatus.WAITLIST,
        isRated: false,
        shippingAddress,
        digitalContentUrl: product.digitalContentUrl,
        isDropshipping: product.isDropshipping,
        supplierCost: product.originalPrice
    });
  }
  setLocal(KEYS.SALES, sales);
  setLocal(KEYS.USERS, users);
  clearCart();
  return true;
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const users = getLocal<User[]>(KEYS.USERS, []);
  const user = users.find(u => u.id === userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    setLocal(KEYS.USERS, users);
    return true;
  }
  return false;
};

