export const sendMessage = async (chatId: string, msg: any) => {
  const chats = getLocal<ChatConversation[]>(KEYS.CHATS, []);
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    chat.messages.push(msg);
    setLocal(KEYS.CHATS, chats);

    // Notify recipients
    chat.participants.forEach(pid => {
        if(pid !== msg.senderId) {
            createNotification({
                type: chat.type === 'GROUP' ? NotificationType.GROUP_POST : NotificationType.MESSAGE,
                recipientId: pid,
                actorId: msg.senderId,
                timestamp: Date.now(),
                groupName: chat.groupName
            });
        }
    });
  }
};

