export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });

  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Usuário não encontrado.");

  // Buscar perfil completo
  const { data: profile, error: profileError } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', data.user.id)
    .single();

  if (profileError || !profile) {
      // Se logou no Auth mas não tem perfil (caso raro de desincronia), retorna erro ou cria um básico
      throw new Error("Perfil de usuário não encontrado no banco de dados.");
  }

  // Mapear campos do banco (snake_case) para o tipo User (camelCase)
  return mapProfileToUser(profile);
};

export const registerUser = async (userData: any): Promise<User> => {
  // 1. Criar Auth User
  const { data, error } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
  });

  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Falha ao criar conta.");

  const userId = data.user.id;
  let storeId = undefined;

  // 2. Se for Creator, criar Loja
  if (userData.userType === UserType.CREATOR) {
    storeId = generateUUID();
    const newStore = {
        id: storeId,
        professor_id: userId,
        name: `Loja de ${userData.firstName}`,
        description: 'Bem-vindo à minha loja!',
        brand_color: '#2563eb',
        product_ids: []
    };
    await supabase.from('stores').insert(newStore);
  }

  // 3. Criar Perfil na tabela 'profiles'
  const newProfile = {
    id: userId,
    email: userData.email,
    first_name: userData.firstName,
    last_name: userData.lastName,
    user_type: userData.userType,
    phone: userData.phone,
    document_id: userData.documentId,
    birth_date: userData.birthDate || Date.now(),
    profile_picture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    balance: 0,
    credentials: userData.credentials,
    bio: userData.bio,
    verification_file_url: userData.verificationFileUrl,
    store_id: storeId,
    followers: [],
    followed_users: []
  };

  const { error: dbError } = await supabase.from('profiles').insert(sanitizePayload(newProfile));

  if (dbError) {
      console.error("Erro ao salvar perfil:", dbError);
      // Rollback auth (opcional, mas recomendado)
      throw new Error("Erro ao salvar dados do perfil.");
  }

  return mapProfileToUser(newProfile);
};

