export const sendMessage = async (chatId: string, msg: any) => {
    const { data } = await supabase.from('chats').select('messages, type, group_name, participants').eq('id', chatId).single();
    if (data) {
        const newMessages = [...(data.messages || []), msg];
        await supabase.from('chats').update({ messages: sanitizePayload(newMessages) }).eq('id', chatId);

        // Notifications
        data.participants.forEach((pid: string) => {
            if (pid !== msg.senderId) {
                createNotification({
                    type: data.type === 'GROUP' ? NotificationType.GROUP_POST : NotificationType.MESSAGE,
                    recipientId: pid,
                    actorId: msg.senderId,
                    timestamp: Date.now(),
                    groupName: data.group_name
                });
            }
        });
    }
};

