export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
    for (const item of cartItems) {
        const product = await findProductById(item.productId);
        if (!product) continue;

        const total = product.price * item.quantity;
        const net = total * (1 - product.affiliateCommissionRate);
        const store = await findStoreById(product.storeId);

        if (store) {
            await updateUserBalance(store.professorId, net);
        }

        let commission = 0;
        if (affiliateUserId) {
            commission = total * product.affiliateCommissionRate;
            await updateUserBalance(affiliateUserId, commission);
            createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, timestamp: Date.now() });
        }

        const sale: AffiliateSale = {
            id: generateUUID(),
            productId: item.productId,
            buyerId,
            affiliateUserId: affiliateUserId || '',
            storeId: product.storeId,
            commissionEarned: commission,
            saleAmount: total,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            isRated: false,
            shippingAddress,
            digitalContentUrl: product.digitalContentUrl,
            isDropshipping: product.isDropshipping,
            supplierCost: product.originalPrice
        };

        await supabase.from('affiliate_sales').insert(sanitizePayload(mapSaleToDb(sale)));
    }
    clearCart();
    return true;
};

export const updateUserBalance = async (userId: string, amount: number) => {
    // Melhor seria usar RPC 'increment_balance', mas aqui faremos read-update
    const { data } = await supabase.from('profiles').select('balance').eq('id', userId).single();
    if (data) {
        const newBalance = (data.balance || 0) + amount;
        await supabase.from('profiles').update({ balance: newBalance }).eq('id', userId);
        return true;
    }
    return false;
};

export const processDonation = async (fromId: string, toId: string, amount: number, message: string) => {
    if (await updateUserBalance(fromId, -amount)) {
        await updateUserBalance(toId, amount);
        createTransaction({ id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Doação para usuário`, timestamp: Date.now(), status: 'COMPLETED' });
        createTransaction({ id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Doação recebida`, timestamp: Date.now(), status: 'COMPLETED' });
        createNotification({ type: NotificationType.MESSAGE, recipientId: toId, actorId: fromId, timestamp: Date.now(), groupName: `Doou $${amount}` });
        return true;
    }
    return false;
};

