export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) cart = cart.filter(i => i.productId !== productId);
  else { const item = cart.find(i => i.productId === productId); if(item) item.quantity = quantity; }
  saveCart(cart);
};
export const removeFromCart = (productId: string) => saveCart(getCart().filter(i => i.productId !== productId));
export const clearCart = () => saveCart([]);

