// --- HELPER: SANITIZAÇÃO DE DADOS ---
// O Supabase/Postgres não aceita 'undefined', removemos ou convertemos para null
const sanitizePayload = (data: any): any => {
  if (data === undefined) return null;
  if (data === null) return null;
  if (Array.isArray(data)) return data.map(sanitizePayload);
  if (typeof data === 'object') {
    const newObj: any = {};
    for (const key in data) {
      if (data[key] !== undefined) {
        newObj[key] = sanitizePayload(data[key]);
      }
    }
    return newObj;
  }
  return data;
};

export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// --- STORAGE (UPLOAD) ---
export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  try {
    // Check if it's a File to access name, otherwise default for Blob
    const name = (file as any).name || 'file';
    const fileExt = name.split('.').pop() || 'jpg';
    const fileName = `${folder}/${generateUUID()}.${fileExt}`;

    const { error: uploadError } = await supabase.storage
      .from(BUCKET_NAME)
      .upload(fileName, file);

    if (uploadError) throw uploadError;

    const { data } = supabase.storage
      .from(BUCKET_NAME)
      .getPublicUrl(fileName);

    return data.publicUrl;
  } catch (error) {
    console.error("Erro no upload:", error);
    // Fallback apenas para não quebrar a UX se o storage falhar
    return URL.createObjectURL(file);
  }
};

