export const startPrivateChat = async (userId1: string, userId2: string) => {
    // Verifica chat existente
    const { data } = await supabase.from('chats').select('*').eq('type', 'PRIVATE').contains('participants', [userId1, userId2]);

    // Filtro JS para garantir exatidão (contains é OR em alguns casos ou superset)
    const existing = data?.find((c: any) => c.participants.length === 2 && c.participants.includes(userId1) && c.participants.includes(userId2));

    if (existing) return existing.id;

    const id = generateUUID();
    await supabase.from('chats').insert({
        id,
        type: ChatType.PRIVATE,
        participants: [userId1, userId2],
        messages: []
    });
    return id;
};

