export const toggleFollowUser = async (currentUserId: string, targetId: string) => {
    const { data: curr } = await supabase.from('profiles').select('followed_users').eq('id', currentUserId).single();
    const { data: targ } = await supabase.from('profiles').select('followers').eq('id', targetId).single();

    if(curr && targ) {
        let following = curr.followed_users || [];
        let followers = targ.followers || [];

        if(following.includes(targetId)) {
            following = following.filter((id: string) => id !== targetId);
            followers = followers.filter((id: string) => id !== currentUserId);
        } else {
            following.push(targetId);
            followers.push(currentUserId);
            createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetId, actorId: currentUserId, timestamp: Date.now() });
        }

        await supabase.from('profiles').update({ followed_users: following }).eq('id', currentUserId);
        await supabase.from('profiles').update({ followers: followers }).eq('id', targetId);
    }
};

