};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const { data: sale } = await supabase.from('affiliate_sales').select('*').eq('id', saleId).single();
    if(sale && !sale.is_rated) {
        await supabase.from('affiliate_sales').update({ is_rated: true }).eq('id', saleId);

        const { data: prod } = await supabase.from('products').select('*').eq('id', sale.product_id).single();
        if(prod) {
            const newRating = { id: generateUUID(), saleId, userId: sale.buyer_id, rating, comment, timestamp: Date.now() };
            const ratings = [...(prod.ratings || []), newRating];
            const avg = ratings.reduce((a: number, b: any) => a + b.rating, 0) / ratings.length;

            await supabase.from('products').update({ 
                ratings: sanitizePayload(ratings), 
                rating_count: ratings.length, 
                average_rating: avg 
            }).eq('id', sale.product_id);
        }
    }
