export const saveReports = (r: any) => {};

// Support Tickets
export const getSupportTickets = async (userId?: string): Promise<SupportTicket[]> => {
    // Implementação mockada no Supabase seria criar tabela 'tickets', aqui retornamos vazio por enquanto
    // ou simulamos localmente para manter a interface funcionando se a tabela não existir no schema
    // O schema não tem tickets, então retornamos vazio ou localstorage se necessário.
