    const json = localStorage.getItem('cyber_tickets');
    const tickets = json ? JSON.parse(json) : [];
    return userId ? tickets.filter((t: any) => t.userId === userId) : tickets;
};

export const createSupportTicket = async (ticket: any, msg: string, url?: string, type?: any) => {
    const tickets = await getSupportTickets();
    const newTicket = {
        ...ticket,
        id: generateUUID(),
        status: 'OPEN',
        createdAt: Date.now(),
        updatedAt: Date.now(),
        messages: [{ id: generateUUID(), senderId: ticket.userId, text: msg, attachmentUrl: url, attachmentType: type, timestamp: Date.now() }]
    };
    localStorage.setItem('cyber_tickets', JSON.stringify([...tickets, newTicket]));
};

export const addSupportMessage = async (tId: string, msg: any) => {
    const tickets = await getSupportTickets();
    const ticket = tickets.find(t => t.id === tId);
    if(ticket) {
        ticket.messages.push({ ...msg, id: generateUUID(), timestamp: Date.now() });
        ticket.updatedAt = Date.now();
        localStorage.setItem('cyber_tickets', JSON.stringify(tickets));
    }
