// LIVE STREAM FUNCTIONS
export const subscribeToLivePost = (postId: string, callback: (post: Post | null) => void) => {
    const channel = supabase.channel(`public:posts:id=eq.${postId}`)
        .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'posts', filter: `id=eq.${postId}` }, (payload) => {
            callback(mapDbPostToPost(payload.new));
        })
        .subscribe();

    return () => {
        supabase.removeChannel(channel);
    };
};

export const sendLiveMessage = async (postId: string, comment: Comment) => {
    const { data } = await supabase.from('posts').select('live_chat').eq('id', postId).single();
    if (data) {
        const currentChat = data.live_chat || [];
        await supabase.from('posts').update({ live_chat: sanitizePayload([...currentChat, comment]) }).eq('id', postId);
    }
};

export const manageLiveViewers = async (postId: string, action: 'join' | 'leave') => {
    const { data } = await supabase.from('posts').select('live_viewer_count').eq('id', postId).single();
    if (data) {
        let count = data.live_viewer_count || 0;
        if (action === 'join') count++;
        else count = Math.max(0, count - 1);
        await supabase.from('posts').update({ live_viewer_count: count }).eq('id', postId);
    }
};

export const pulseLiveHeart = async (postId: string) => {
    const { data } = await supabase.from('posts').select('live_heart_count').eq('id', postId).single();
    if (data) {
        await supabase.from('posts').update({ live_heart_count: (data.live_heart_count || 0) + 1 }).eq('id', postId);
    }
};

