import { User, Post, ChatConversation, AdCampaign, UserType, Store, Product, AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, Notification, NotificationType, CartItem, ProductRating, OrderStatus, CyberEvent, Story, Transaction, ContentReport, SystemLog, GlobalSettings, TransactionType, ChatType, GroupTheme, SupportTicket, SupportMessage } from '../types';
import { DEFAULT_USERS, DEFAULT_AUDIO_TRACKS, DEFAULT_PROFILE_PIC } from '../data/constants';
import { db, auth } from './firebaseClient';
import { 
  collection, getDocs, getDoc, setDoc, doc, updateDoc, 
  query, where, orderBy, addDoc, deleteDoc, onSnapshot
} from "firebase/firestore";
import { 
  createUserWithEmailAndPassword, signInWithEmailAndPassword, updatePassword
} from "firebase/auth";

// --- CLOUDINARY CONFIG ---
const CLOUDINARY_CLOUD_NAME = "dblnktl9m";
const CLOUDINARY_API_KEY = "757866868821299";
const CLOUDINARY_API_SECRET = "nh8VOmM8FYdQ_12BrvksYQrlfwA"; 

// --- LOCAL KEYS ---
const CART_KEY = 'cyberphone_cart';
const THEME_KEY = 'cyber_app_theme';
const CURRENT_USER_KEY = 'cyberphone_current_user_id';

// --- HELPER: SANITIZAÇÃO DE DADOS ---
// Firestore não aceita 'undefined', removemos ou convertemos para null
const sanitizePayload = (data: any): any => {
  if (data === undefined) return null;
  if (data === null) return null;
  if (Array.isArray(data)) return data.map(sanitizePayload);
  if (typeof data === 'object') {
    const newObj: any = {};
    for (const key in data) {
      if (data[key] !== undefined) {
        newObj[key] = sanitizePayload(data[key]);
      }
    }
    return newObj;
  }
  return data;
};

export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// --- UPLOAD VIA CLOUDINARY (SIGNED API) ---
// Mantemos Cloudinary para performance de mídia, já que o Firebase Storage requer regras complexas de CORS
const generateSignature = async (params: Record<string, string>, secret: string) => {
    const sortedKeys = Object.keys(params).sort();
    const stringToSign = sortedKeys.map(key => `${key}=${params[key]}`).join('&') + secret;
    const msgBuffer = new TextEncoder().encode(stringToSign);
    const hashBuffer = await crypto.subtle.digest('SHA-1', msgBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  if (!file) throw new Error("Arquivo inválido");

  try {
    const timestamp = Math.round((new Date()).getTime() / 1000).toString();
    const folderPath = `cyberphone/${folder}`;

    const paramsToSign = {
        folder: folderPath,
        timestamp: timestamp
    };

    const signature = await generateSignature(paramsToSign, CLOUDINARY_API_SECRET);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('api_key', CLOUDINARY_API_KEY);
    formData.append('timestamp', timestamp);
    formData.append('folder', folderPath);
    formData.append('signature', signature);

    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/auto/upload`, {
      method: 'POST',
      body: formData
    });

    if (!response.ok) throw new Error("Upload falhou");
    const data = await response.json();
    return data.secure_url;
  } catch (error: any) {
    console.error("Falha no Upload:", error);
    return URL.createObjectURL(file); // Fallback local
  }
};

export const getOptimizedVideoUrl = (url: string) => {
  if (!url) return '';
  if (!url.includes('cloudinary.com')) return url;
  if (url.includes('f_auto') || url.includes('q_auto')) return url;
  const transformation = 'f_auto:video,q_auto,w_720,c_limit,vc_auto';
  return url.replace('/upload/', `/upload/${transformation}/`);
};

// --- AUTH & USER MANAGEMENT ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  const userCredential = await signInWithEmailAndPassword(auth, email, password);
  const uid = userCredential.user.uid;
  const userDoc = await getDoc(doc(db, "users", uid));
  if (userDoc.exists()) {
    const userData = userDoc.data() as User;
    return { ...userData, id: uid };
  } else {
    // Se logou mas não tem doc (erro de sincronia), cria um básico
    const basicUser: User = {
        id: uid,
        email: email,
        firstName: 'Usuário',
        lastName: '',
        userType: UserType.STANDARD,
        phone: '',
        documentId: '',
        birthDate: Date.now(),
        followers: [],
        followedUsers: []
    };
    await setDoc(doc(db, "users", uid), sanitizePayload(basicUser));
    return basicUser;
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
  const uid = userCredential.user.uid;

  const newUser: User = {
    id: uid,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl,
    isAdmin: false
  };

  if (newUser.userType === UserType.CREATOR) {
    const storeId = generateUUID();
    newUser.storeId = storeId;
    await setDoc(doc(db, "stores", storeId), sanitizePayload({
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
      brandColor: '#2563eb'
    }));
  }

  await setDoc(doc(db, "users", uid), sanitizePayload(newUser));
  return newUser;
};

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(CURRENT_USER_KEY, userId);
  else localStorage.removeItem(CURRENT_USER_KEY);
};

export const getCurrentUserId = (): string | null => {
  return localStorage.getItem(CURRENT_USER_KEY);
};

export const getUsers = async (): Promise<User[]> => {
  const querySnapshot = await getDocs(collection(db, "users"));
  const users: User[] = [];
  querySnapshot.forEach((doc) => {
    users.push(doc.data() as User);
  });
  return users;
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  try {
    const userDoc = await getDoc(doc(db, "users", userId));
    if (userDoc.exists()) {
      return userDoc.data() as User;
    }
  } catch (e) {}
  return undefined;
};

