  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const isInitializedRef = useRef(false);

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
      });
      streamRef.current = null;
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription
  useEffect(() => {
    if (!postId) return;

    manageLiveViewers(postId, 'join');

    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        if (updatedPost.liveStream?.status === 'ENDED') {
            if (currentUser.id !== updatedPost.userId) {
                alert("A transmissão foi encerrada pelo professor.");
                onNavigate('feed');
            }
            return;
        }

        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount, currentUser.id, onNavigate]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const handleEndLive = async () => {
    if (!post) return;

    if (!window.confirm("Deseja encerrar e salvar esta aula na sua biblioteca?")) return;

    setIsEnding(true); // Mostra loader

    try {
        stopStreams();

        // Em um app real, aqui faríamos o upload da gravação.
        // Para este MVP, usamos um vídeo de exemplo para simular o "Replay".
        const mockRecordingUrl = "https://res.cloudinary.com/dblnktl9m/video/upload/v1740939023/cyberphone/reels/ba776274-0f2c-497d-b08e-32432924403c.webm"; 

        const updatedPost: Post = {
            ...post,
            liveStream: {
                ...post.liveStream!,
                status: 'ENDED',
                recordingUrl: mockRecordingUrl
            }
        };
        await updatePost(updatedPost);
        await refreshUser();

        // Pequeno delay para UX
        setTimeout(() => {
            onNavigate('profile', { userId: currentUser.id });
        }, 1500);

    } catch (e) {
        console.error("Erro ao encerrar live:", e);
        setIsEnding(false);
        handleExit();
    }
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];

        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);

        setIsCamOn(true);
        if (videoElementRef.current) {
            videoElementRef.current.srcObject = streamRef.current;
        }
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  useEffect(() => {
      if (creator && currentUser.id === creator.id && post && !isInitializedRef.current) {
          isInitializedRef.current = true;

          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }
              } catch (e) {
                  console.error("Erro camera:", e);
                  alert("Erro ao acessar câmera. Verifique permissões.");
              }
          };
          initCam();
      }
  }, [creator, currentUser.id, post]); 

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = async () => {
    if (!pendingAmount || !creator || !post) return;

    if ((currentUser.balance || 0) < pendingAmount) { 
        alert("Saldo insuficiente."); 
        return; 
    }

    setIsProcessingDonation(true);

    const success = await processDonation(currentUser.id, creator.id, pendingAmount, `Live: ${post.liveStream?.title || 'Aula'}`);

    if (success) {
        refreshUser();
        setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

        const sysMsg: Comment = {
            id: generateUUID(),
            userId: 'system',
            userName: 'Sistema',
            text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
            timestamp: Date.now()
        };
        sendLiveMessage(postId, sysMsg);
        pulseLiveHeart(postId);

        setTimeout(() => setDonationAlert(null), 5000);
        setIsProcessingDonation(false);
        setPendingAmount(null);
        setShowDonationModal(false);
    } else {
        alert("Erro ao processar doação.");
        setIsProcessingDonation(false);
    }
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); 

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); 
      pulseLiveHeart(postId); 
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    setChatMessages(prev => [...prev, msg]);
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button 
                onClick={isProfessional ? handleEndLive : handleExit} 
                className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90"
              >
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* Loading Overlay when Ending */}
        {isEnding && (
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center pointer-events-auto">
                <ArrowPathIcon className="h-12 w-12 text-white animate-spin mb-4" />
                <h3 className="text-xl font-black uppercase tracking-widest text-white">Salvando Aula...</h3>
                <p className="text-xs text-gray-400 font-bold mt-2">Aguarde o processamento</p>
            </div>
        )}

        {/* MIDDLE LAYER */}
        <div className="flex-1 relative w-full pointer-events-none">
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {isHandRaised && (
             <div className="absolute top-20 right-4 animate-bounce">
                <div className="bg-yellow-500 text-black p-2 rounded-full shadow-lg border-2 border-white">
                   <HandRaisedIcon className="h-6 w-6" />
                </div>
             </div>
           )}

           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">
           <div className="w-[85%] md:w-[400px] h-40 md:h-64 overflow-y-auto no-scrollbar mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade mb-2">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.userId === currentUser.id ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.userName}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           <div className="flex items-center gap-2 md:gap-3 pb-safe mb-2 md:mb-0">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-lg rounded-full px-4 py-3 border border-white/10 focus-within:bg-white/20 transition-all shadow-lg min-w-0">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full min-w-0"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white/80 hover:text-blue-400 transition-colors disabled:opacity-30 shrink-0">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <div className="flex items-center gap-2 shrink-0">
                 <button 
                   onClick={handleSendHeart}
                   className="p-3 bg-gradient-to-tr from-pink-500 to-red-600 text-white rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-transform"
                 >
                    <HeartIcon className="h-5 w-5" />
                 </button>

                 <div className="relative">
                    <button 
                      onClick={() => setShowControls(!showControls)} 
                      className="p-3 bg-gray-800 rounded-full border border-white/20 text-white hover:bg-gray-700 transition-all shadow-lg"
                    >
                        <EllipsisHorizontalIcon className="h-5 w-5" />
                    </button>

                    {showControls && (
                        <div className="absolute bottom-full right-0 mb-4 bg-black/90 border border-white/10 rounded-2xl p-2 flex flex-col gap-2 shadow-2xl backdrop-blur-xl animate-scale-in origin-bottom-right min-w-[60px] items-center z-50">
                            {isProfessional ? (
                                <>
                                    <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Microfone">
                                        {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                                    </button>
                                    <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Câmera">
                                        {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                                    </button>
                                    <div className="h-px w-full bg-white/10 my-1"></div>
                                    <button 
                                      onClick={handleEndLive} 
                                      className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all text-white" 
                                      title="Encerrar"
                                    >
                                        <PowerIcon className="h-5 w-5" />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button 
                                        onClick={() => { setShowDonationModal(true); setShowControls(false); }}
                                        className="p-3 bg-yellow-500 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-90 transition-transform"
                                        title="Apoiar"
                                    >
                                        <BanknotesIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                        onClick={toggleHandRaise}
                                        className={`p-3 rounded-full transition-all active:scale-90 ${isHandRaised ? 'bg-orange-500 text-white' : 'bg-white/10 text-white'}`}
                                        title="Levantar Mão"
                                    >
                                        {isHandRaised ? <HandRaisedIcon className="h-5 w-5" /> : <HandRaisedOutline className="h-5 w-5" />}
                                    </button>
                                </>
                            )}
                        </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      </div>

      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .mask-gradient-chat {
           mask-image: linear-gradient(to top, black 85%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 85%, transparent 100%);
        }
        .pb-safe {
           padding-bottom: max(env(safe-area-inset-bottom), 20px);
        }
        @keyframes slide-right-fade {
           from { opacity: 0; transform: translateX(-10px); }
           to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-right-fade { animation: slide-right-fade 0.2s ease-out forwards; }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Comment, PostType } from '../types';
import { 
  getPosts, 
  findUserById, 
  processDonation, 
  deletePost, 
  updatePost,
  subscribeToLivePost,
  sendLiveMessage,
  manageLiveViewers,
  pulseLiveHeart,
  generateUUID,
  uploadFile
} from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  SignalIcon, 
  UsersIcon, 
  PowerIcon, 
  BanknotesIcon, 
  PaperAirplaneIcon, 
  SparklesIcon, 
  HeartIcon, 
  EllipsisHorizontalIcon, 
  HandRaisedIcon,
  ArrowPathIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [isHandRaised, setIsHandRaised] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [isEnding, setIsEnding] = useState(false); // Estado de encerramento
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Recording Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);

  const isInitializedRef = useRef(false);

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
      });
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
        mediaRecorderRef.current.stop();
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription
  useEffect(() => {
    if (!postId) return;

    manageLiveViewers(postId, 'join');

    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        if (updatedPost.liveStream?.status === 'ENDED') {
            if (currentUser.id !== updatedPost.userId) {
                alert("A transmissão foi encerrada pelo professor.");
                onNavigate('feed');
            }
            return;
        }

        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount, currentUser.id, onNavigate]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const startRecording = (stream: MediaStream) => {
    try {
        const options = { mimeType: 'video/webm' };
        const recorder = new MediaRecorder(stream, options);

        recordedChunksRef.current = [];
        recorder.ondataavailable = (event) => {
            if (event.data.size > 0) {
                recordedChunksRef.current.push(event.data);
            }
        };

        recorder.start(1000); // 1s chunks
        mediaRecorderRef.current = recorder;
        setIsRecording(true);
        console.log("Gravação iniciada");
    } catch (e) {
        console.warn("MediaRecorder falhou ou não suportado:", e);
    }
  };

  const stopRecordingAndGetBlob = (): Promise<Blob> => {
      return new Promise((resolve) => {
          const recorder = mediaRecorderRef.current;
          if (!recorder) {
              resolve(new Blob([], { type: 'video/webm' }));
              return;
          }

          const finish = () => {
              const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
              resolve(blob);
          };

          if (recorder.state === 'recording') {
              recorder.onstop = finish;
              recorder.stop();
          } else {
              finish();
          }
      });
  };

  const handleEndLive = async () => {
    if (!post) return;

    if (!window.confirm("Deseja encerrar e salvar esta aula na sua biblioteca?")) return;

    setIsEnding(true); // Mostra loader

    try {
        let recordingUrl = "https://res.cloudinary.com/dblnktl9m/video/upload/v1740939023/cyberphone/reels/ba776274-0f2c-497d-b08e-32432924403c.webm"; // Fallback default

        // Tentar parar gravação e fazer upload
        if (mediaRecorderRef.current) {
            const blob = await stopRecordingAndGetBlob();
            if (blob.size > 0) {
                // Upload real
                try {
                    recordingUrl = await uploadFile(blob, 'recordings');
                } catch (upErr) {
                    console.error("Erro no upload da gravação, usando fallback.", upErr);
                }
            }
        }

        stopStreams();

        const updatedPost: Post = {
            ...post,
            liveStream: {
                ...post.liveStream!,
                status: 'ENDED',
                recordingUrl: recordingUrl
            }
        };
        await updatePost(updatedPost);
        await refreshUser();

        // Pequeno delay para UX
        setTimeout(() => {
            onNavigate('profile', { userId: currentUser.id });
        }, 1500);

    } catch (e) {
        console.error("Erro ao encerrar live:", e);
        setIsEnding(false);
        handleExit();
    }
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];

        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);

        setIsCamOn(true);
        if (videoElementRef.current) {
            videoElementRef.current.srcObject = streamRef.current;
        }
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  useEffect(() => {
      if (creator && currentUser.id === creator.id && post && !isInitializedRef.current) {
          isInitializedRef.current = true;

          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }
                  // Start recording automatically for host
                  startRecording(stream);
              } catch (e) {
                  console.error("Erro camera:", e);
                  alert("Erro ao acessar câmera. Verifique permissões.");
              }
          };
          initCam();
      }
  }, [creator, currentUser.id, post]); 

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = async () => {
    if (!pendingAmount || !creator || !post) return;

    if ((currentUser.balance || 0) < pendingAmount) { 
        alert("Saldo insuficiente."); 
        return; 
    }

    setIsProcessingDonation(true);

    const success = await processDonation(currentUser.id, creator.id, pendingAmount, `Live: ${post.liveStream?.title || 'Aula'}`);

    if (success) {
        refreshUser();
        setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

        const sysMsg: Comment = {
            id: generateUUID(),
            userId: 'system',
            userName: 'Sistema',
            text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
            timestamp: Date.now()
        };
        sendLiveMessage(postId, sysMsg);
        pulseLiveHeart(postId);

        setTimeout(() => setDonationAlert(null), 5000);
        setIsProcessingDonation(false);
        setPendingAmount(null);
        setShowDonationModal(false);
    } else {
        alert("Erro ao processar doação.");
        setIsProcessingDonation(false);
    }
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); 

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); 
      pulseLiveHeart(postId); 
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    setChatMessages(prev => [...prev, msg]);
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 {isRecording && isProfessional && (
                    <div className="bg-black/50 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider text-red-400 flex items-center gap-1">
                        <div className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse"></div> REC
                    </div>
                 )}
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10 mt-1">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button 
                onClick={isProfessional ? handleEndLive : handleExit} 
                className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90"
              >
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* Loading Overlay when Ending */}
        {isEnding && (
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center pointer-events-auto">
                <ArrowPathIcon className="h-12 w-12 text-white animate-spin mb-4" />
                <h3 className="text-xl font-black uppercase tracking-widest text-white">Salvando Aula...</h3>
                <p className="text-xs text-gray-400 font-bold mt-2">Aguarde o upload da gravação</p>
            </div>
        )}

        {/* MIDDLE LAYER */}
        <div className="flex-1 relative w-full pointer-events-none">
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {isHandRaised && (
             <div className="absolute top-20 right-4 animate-bounce">
                <div className="bg-yellow-500 text-black p-2 rounded-full shadow-lg border-2 border-white">
                   <HandRaisedIcon className="h-6 w-6" />
                </div>
             </div>
           )}

           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">
           <div className="w-[85%] md:w-[400px] h-40 md:h-64 overflow-y-auto no-scrollbar mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade mb-2">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.userId === currentUser.id ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.userName}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           <div className="flex items-center gap-2 md:gap-3 pb-safe mb-2 md:mb-0">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-lg rounded-full px-4 py-3 border border-white/10 focus-within:bg-white/20 transition-all shadow-lg min-w-0">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full min-w-0"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white/80 hover:text-blue-400 transition-colors disabled:opacity-30 shrink-0">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <div className="flex items-center gap-2 shrink-0">
                 <button 
                   onClick={handleSendHeart}
                   className="p-3 bg-gradient-to-tr from-pink-500 to-red-600 text-white rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-transform"
                 >
                    <HeartIcon className="h-5 w-5" />
                 </button>

                 <div className="relative">
                    <button 
                      onClick={() => setShowControls(!showControls)} 
                      className="p-3 bg-gray-800 rounded-full border border-white/20 text-white hover:bg-gray-700 transition-all shadow-lg"
                    >
                        <EllipsisHorizontalIcon className="h-5 w-5" />
                    </button>

                    {showControls && (
                        <div className="absolute bottom-full right-0 mb-4 bg-black/90 border border-white/10 rounded-2xl p-2 flex flex-col gap-2 shadow-2xl backdrop-blur-xl animate-scale-in origin-bottom-right min-w-[60px] items-center z-50">
                            {isProfessional ? (
                                <>
                                    <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Microfone">
                                        {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                                    </button>
                                    <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Câmera">
                                        {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                                    </button>
                                    <div className="h-px w-full bg-white/10 my-1"></div>
                                    <button 
                                      onClick={handleEndLive} 
                                      className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all text-white" 
                                      title="Encerrar"
                                    >
                                        <PowerIcon className="h-5 w-5" />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button 
                                        onClick={() => { setShowDonationModal(true); setShowControls(false); }}
                                        className="p-3 bg-yellow-500 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-90 transition-transform"
                                        title="Apoiar"
                                    >
                                        <BanknotesIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                        onClick={toggleHandRaise}
                                        className={`p-3 rounded-full transition-all active:scale-90 ${isHandRaised ? 'bg-orange-500 text-white' : 'bg-white/10 text-white'}`}
                                        title="Levantar Mão"
                                    >
                                        {isHandRaised ? <HandRaisedIcon className="h-5 w-5" /> : <HandRaisedOutline className="h-5 w-5" />}
                                    </button>
                                </>
                            )}
                        </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      </div>

      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .mask-gradient-chat {
           mask-image: linear-gradient(to top, black 85%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 85%, transparent 100%);
        }
        .pb-safe {
           padding-bottom: max(env(safe-area-inset-bottom), 20px);
        }
        @keyframes slide-right-fade {
           from { opacity: 0; transform: translateX(-10px); }
           to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-right-fade { animation: slide-right-fade 0.2s ease-out forwards; }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React from 'react';
import { XMarkIcon, ExclamationTriangleIcon, TrashIcon, CheckCircleIcon, QuestionMarkCircleIcon } from '@heroicons/react/24/solid';

export type ConfirmationType = 'danger' | 'info' | 'success' | 'warning';

interface ConfirmationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  type?: ConfirmationType;
  loading?: boolean;
}

const ConfirmationModal: React.FC<ConfirmationModalProps> = ({ 
  isOpen, 
  onClose, 
  onConfirm, 
  title, 
  message, 
  confirmText = 'Confirmar', 
  cancelText = 'Cancelar',
  type = 'danger',
  loading = false
}) => {
  if (!isOpen) return null;

  const getTheme = () => {
    switch (type) {
      case 'danger':
        return {
          bgIcon: 'bg-red-50 dark:bg-red-900/20',
          textIcon: 'text-red-600',
          btnPrimary: 'bg-red-600 hover:bg-red-700 shadow-red-200',
          icon: TrashIcon
        };
      case 'success':
        return {
          bgIcon: 'bg-green-50 dark:bg-green-900/20',
          textIcon: 'text-green-600',
          btnPrimary: 'bg-green-600 hover:bg-green-700 shadow-green-200',
          icon: CheckCircleIcon
        };
      case 'warning':
        return {
          bgIcon: 'bg-orange-50 dark:bg-orange-900/20',
          textIcon: 'text-orange-500',
          btnPrimary: 'bg-orange-500 hover:bg-orange-600 shadow-orange-200',
          icon: ExclamationTriangleIcon
        };
      default: // info
        return {
          bgIcon: 'bg-blue-50 dark:bg-blue-900/20',
          textIcon: 'text-blue-600',
          btnPrimary: 'bg-blue-600 hover:bg-blue-700 shadow-blue-200',
          icon: QuestionMarkCircleIcon
        };
    }
  };

  const theme = getTheme();
  const Icon = theme.icon;

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 animate-fade-in" style={{ zIndex: 9999 }}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-md transition-opacity" onClick={onClose}></div>

      <div className="bg-white dark:bg-[#1a1c23] w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl relative border border-gray-100 dark:border-white/5 overflow-hidden animate-scale-in transform transition-all">
        {/* Decorative Top Line */}
        <div className={`absolute top-0 left-0 w-full h-1.5 ${type === 'danger' ? 'bg-red-500' : type === 'success' ? 'bg-green-500' : type === 'warning' ? 'bg-orange-500' : 'bg-blue-600'}`}></div>

        <div className="flex flex-col items-center text-center">
          <div className={`w-20 h-20 ${theme.bgIcon} rounded-full flex items-center justify-center mb-6 animate-bounce-short shadow-inner`}>
            <Icon className={`h-10 w-10 ${theme.textIcon}`} />
          </div>

          <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tighter mb-3 leading-tight">
            {title}
          </h3>

          <p className="text-sm text-gray-500 dark:text-gray-400 font-medium leading-relaxed mb-8 px-2">
            {message}
          </p>

          <div className="flex flex-col w-full gap-3">
            <button 
              onClick={() => { onConfirm(); }}
              disabled={loading}
              className={`w-full py-4 ${theme.btnPrimary} text-white rounded-2xl font-black text-xs uppercase shadow-xl dark:shadow-none transition-all active:scale-95 flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed`}
            >
              {loading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div>
                  Processando...
                </>
              ) : (
                confirmText
              )}
            </button>

            <button 
              onClick={onClose}
              disabled={loading}
              className="w-full py-4 bg-gray-50 dark:bg-white/5 text-gray-500 dark:text-gray-400 rounded-2xl font-black text-xs uppercase hover:bg-gray-100 dark:hover:bg-white/10 transition-all active:scale-95"
            >
              {cancelText}
            </button>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes scale-in {
          0% { opacity: 0; transform: scale(0.95) translateY(10px); }
          100% { opacity: 1; transform: scale(1) translateY(0); }
        }
        .animate-scale-in { animation: scale-in 0.2s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes bounce-short {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        .animate-bounce-short { animation: bounce-short 2s infinite; }
      `}</style>
    </div>
  );
};

export default ConfirmationModal;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation, ChatType, GroupTheme } from '../types';
import {
  getChats,
  findUserById,
  sendMessage,
  deleteMessage,
  editMessage,
  generateUUID,
  getUsers,
  updateGroupTheme,
  leaveGroup,
  deleteChat,
  startPrivateChat
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  EllipsisVerticalIcon,
  PaintBrushIcon,
  ChevronDownIcon,
  PencilIcon,
  TrashIcon,
  ArrowUturnLeftIcon,
  XMarkIcon,
  DocumentDuplicateIcon,
  ArrowRightOnRectangleIcon,
  InformationCircleIcon
} from '@heroicons/react/24/solid';
import CallModal from './CallModal';
import ConfirmationModal, { ConfirmationType } from './ConfirmationModal';

interface ChatPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
}

// Configuração expandida de Temas
const THEME_CONFIG: Record<GroupTheme, { primary: string, secondary: string, bg: string, bubble: string, text: string }> = {
  blue: { primary: 'bg-blue-600', secondary: 'bg-blue-500', bg: 'bg-[#73a3c9]', bubble: 'bg-[#effdde]', text: 'text-blue-600' },
  green: { primary: 'bg-emerald-600', secondary: 'bg-emerald-500', bg: 'bg-[#7ebc89]', bubble: 'bg-[#e7fde8]', text: 'text-emerald-600' },
  black: { primary: 'bg-zinc-900', secondary: 'bg-zinc-800', bg: 'bg-[#1a1a1a]', bubble: 'bg-[#2b2b2b]', text: 'text-white' }, 
  orange: { primary: 'bg-orange-600', secondary: 'bg-orange-500', bg: 'bg-[#edb881]', bubble: 'bg-[#fff5e6]', text: 'text-orange-600' },
  purple: { primary: 'bg-purple-600', secondary: 'bg-purple-500', bg: 'bg-[#9d84c4]', bubble: 'bg-[#f3e5f5]', text: 'text-purple-600' },
  red: { primary: 'bg-red-600', secondary: 'bg-red-500', bg: 'bg-[#e57373]', bubble: 'bg-[#ffebee]', text: 'text-red-600' },
  teal: { primary: 'bg-teal-600', secondary: 'bg-teal-500', bg: 'bg-[#4db6ac]', bubble: 'bg-[#e0f2f1]', text: 'text-teal-600' },
  pink: { primary: 'bg-pink-600', secondary: 'bg-pink-500', bg: 'bg-[#f06292]', bubble: 'bg-[#fce4ec]', text: 'text-pink-600' },
  indigo: { primary: 'bg-indigo-600', secondary: 'bg-indigo-500', bg: 'bg-[#7986cb]', bubble: 'bg-[#e8eaf6]', text: 'text-indigo-600' },
  cyan: { primary: 'bg-cyan-600', secondary: 'bg-cyan-500', bg: 'bg-[#4dd0e1]', bubble: 'bg-[#e0f7fa]', text: 'text-cyan-600' }
};

const ChatPage: React.FC<ChatPageProps> = ({ currentUser, onNavigate }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [showThemeMenu, setShowThemeMenu] = useState(false);
  const [showGroupMenu, setShowGroupMenu] = useState(false);
  const [filterTab, setFilterTab] = useState<'ALL' | 'PRIVATE' | 'GROUP'>('ALL');

  // Confirmation Modal State
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
    type?: ConfirmationType;
    confirmText?: string;
  }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

  const [activeCall, setActiveCall] = useState<{partner?: User, group?: ChatConversation, type: 'voice' | 'video'} | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [followedUsersData, setFollowedUsersData] = useState<User[]>([]);

  // States for Actions
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [selectedMessageForAction, setSelectedMessageForAction] = useState<Message | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const loadUsers = async () => {
      const users = await getUsers();
      setAllUsers(users);
      if (currentUser.followedUsers) {
        setFollowedUsersData(users.filter(u => currentUser.followedUsers.includes(u.id)));
      }
    };
    loadUsers();
    const interval = setInterval(loadUsers, 10000);
    return () => clearInterval(interval);
  }, [currentUser.followedUsers]);

  const loadData = useCallback(async () => {
    const userChats = await getChats(currentUser.id);
    setConversations(userChats);
    if (selectedChat) {
      const updated = userChats.find(c => c.id === selectedChat.id);
      if (updated) setSelectedChat(updated);
      else setSelectedChat(null);
    }
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [selectedChat?.messages?.length, selectedChat?.id]);

  const getChatDisplayInfo = (chat: ChatConversation) => {
    if (chat.type === ChatType.GROUP) {
      return {
        name: chat.groupName || 'Grupo',
        image: chat.groupImage || DEFAULT_PROFILE_PIC,
        isOnline: false,
        lastSeen: 0
      };
    }
    const partnerId = chat.participants.find(p => p !== currentUser.id);
    const partner = allUsers.find(u => u.id === partnerId);
    return {
      name: partner ? `${partner.firstName} ${partner.lastName}` : 'Usuário Desconhecido',
      image: partner?.profilePicture || DEFAULT_PROFILE_PIC,
      isOnline: !!partner?.isOnline,
      lastSeen: partner?.lastSeen || 0
    };
  };

  const handleStartChatWithUser = async (targetUserId: string) => {
    try {
      const chatId = await startPrivateChat(currentUser.id, targetUserId);
      await loadData();
      const allChats = await getChats(currentUser.id);
      const chat = allChats.find(c => c.id === chatId);
      if (chat) {
        setSelectedChat(chat);
        setSearchTerm('');
      }
    } catch (e) {
      alert("Erro ao iniciar conversa.");
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    if (editingMessageId) {
        await editMessage(selectedChat.id, editingMessageId, newMessage.trim());
        setEditingMessageId(null);
    } else {
        const replyContext = replyingTo ? {
            id: replyingTo.id,
            text: replyingTo.text || 'Imagem',
            senderName: replyingTo.senderId === currentUser.id ? 'Você' : 'Usuário'
        } : undefined;

        const msg: Message = {
          id: generateUUID(),
          senderId: currentUser.id,
          timestamp: Date.now(),
          text: newMessage.trim() || undefined,
          imageUrl: attachedImage || undefined,
          groupId: selectedChat.type === ChatType.GROUP ? selectedChat.id : undefined,
          replyTo: replyContext
        };

        await sendMessage(selectedChat.id, msg);
        setReplyingTo(null);
    }

    setNewMessage('');
    setAttachedImage(null);
    loadData();
    if (inputRef.current) inputRef.current.style.height = 'auto';
  };

  const handleAction = (action: 'reply' | 'edit' | 'delete' | 'copy') => {
    if (!selectedMessageForAction || !selectedChat) return;
    const msg = selectedMessageForAction;

    switch (action) {
        case 'reply':
            setReplyingTo(msg);
            setEditingMessageId(null);
            inputRef.current?.focus();
            break;
        case 'edit':
            setNewMessage(msg.text || '');
            setEditingMessageId(msg.id);
            setReplyingTo(null);
            inputRef.current?.focus();
            break;
        case 'delete':
            setConfirmConfig({
              isOpen: true,
              title: 'Apagar Mensagem',
              message: 'Tem certeza que deseja apagar esta mensagem para todos? Esta ação não pode ser desfeita.',
              confirmText: 'Apagar',
              type: 'danger',
              onConfirm: async () => {
                await deleteMessage(selectedChat.id, msg.id);
                loadData();
                setConfirmConfig(prev => ({ ...prev, isOpen: false }));
              }
            });
            break;
        case 'copy':
            if (msg.text) navigator.clipboard.writeText(msg.text);
            break;
    }
    setSelectedMessageForAction(null);
  };

  const cancelAction = () => {
    setReplyingTo(null);
    setEditingMessageId(null);
    setNewMessage('');
    if (inputRef.current) inputRef.current.style.height = 'auto';
  };

  const handleChangeTheme = async (theme: GroupTheme) => {
    if (!selectedChat || selectedChat.adminId !== currentUser.id) return;
    await updateGroupTheme(selectedChat.id, theme);
    setShowThemeMenu(false);
    loadData();
  };

  const confirmLeaveGroup = () => {
    if (!selectedChat) return;
    setConfirmConfig({
      isOpen: true,
      title: 'Sair do Grupo',
      message: 'Você tem certeza que deseja sair desta comunidade? Você não receberá mais mensagens.',
      confirmText: 'Sair Agora',
      type: 'warning',
      onConfirm: async () => {
        await leaveGroup(selectedChat.id, currentUser.id);
        setSelectedChat(null);
        loadData();
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        setShowGroupMenu(false);
      }
    });
  };

  const confirmDeleteChat = () => {
    if (!selectedChat) return;
    const isGroup = selectedChat.type === ChatType.GROUP;
    setConfirmConfig({
      isOpen: true,
      title: isGroup ? 'Excluir Grupo' : 'Excluir Conversa',
      message: isGroup 
        ? 'ATENÇÃO: O grupo será dissolvido e todas as mensagens serão apagadas permanentemente para todos os membros.'
        : 'Tem certeza que deseja apagar esta conversa? O histórico será perdido permanentemente.',
      confirmText: 'Excluir Tudo',
      type: 'danger',
      onConfirm: async () => {
        await deleteChat(selectedChat.id);
        setSelectedChat(null);
        loadData();
        setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        setShowGroupMenu(false);
      }
    });
  };

  const startCall = async (type: 'voice' | 'video') => {
    if (!selectedChat) return;
    if (selectedChat.type === ChatType.PRIVATE) {
        const partnerId = selectedChat.participants.find(p => p !== currentUser.id);
        const partner = await findUserById(partnerId!);
        if (partner) setActiveCall({ partner, type });
    } else {
        setActiveCall({ group: selectedChat, type });
    }
  };

  const filteredConversations = conversations.filter(c => {
    if (filterTab !== 'ALL' && c.type !== filterTab) return false;
    if (searchTerm) {
        const term = searchTerm.toLowerCase();
        const { name } = getChatDisplayInfo(c);
        return name.toLowerCase().includes(term);
    }
    return true;
  });

  const filteredFollowers = searchTerm ? followedUsersData.filter(u => {
      const name = `${u.firstName} ${u.lastName}`.toLowerCase();
      const hasChat = filteredConversations.some(c => 
        c.type === ChatType.PRIVATE && c.participants.includes(u.id)
      );
      return name.includes(searchTerm.toLowerCase()) && !hasChat;
  }) : [];

  const chatTheme = selectedChat?.theme || 'blue';
  const themeStyles = THEME_CONFIG[chatTheme];
  const activeChatInfo = selectedChat ? getChatDisplayInfo(selectedChat) : null;

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex bg-[#f0f2f5] dark:bg-[#0a0c10] overflow-hidden animate-fade-in">

      {/* SIDEBAR */}
      <div className={`
        flex-col bg-white dark:bg-[#12161f] border-r dark:border-white/5 z-40 transition-all
        ${selectedChat ? 'hidden md:flex md:w-80 lg:w-[360px]' : 'flex w-full md:w-80 lg:w-[360px]'}
      `}>
        <div className="p-4 space-y-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <h2 className="text-xl font-black dark:text-white uppercase tracking-tighter">Mensagens</h2>
              </div>
              <button 
                onClick={() => onNavigate('create-group')}
                className="p-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 transition-all shadow-lg active:scale-90"
              >
                <PlusIcon className="h-5 w-5 stroke-[3]" />
              </button>
           </div>

           <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input 
                placeholder="Buscar conversa ou amigo..." 
                className="w-full pl-11 pr-4 py-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white focus:ring-1 focus:ring-blue-500 transition-all"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
           </div>

           <div className="flex gap-2 pb-1 overflow-x-auto no-scrollbar">
              {['ALL', 'PRIVATE', 'GROUP'].map(tab => (
                 <button key={tab} onClick={() => setFilterTab(tab as any)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${filterTab === tab ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}>
                    {tab === 'ALL' ? 'Todos' : tab === 'PRIVATE' ? 'Privados' : 'Grupos'}
                 </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-1">
          {searchTerm && filteredFollowers.length > 0 && (
             <div className="mb-4 animate-fade-in">
                <p className="px-4 py-2 text-[9px] font-black text-gray-400 uppercase tracking-widest">Iniciar Nova Conversa</p>
                {filteredFollowers.map(user => (
                   <button
                     key={user.id}
                     onClick={() => handleStartChatWithUser(user.id)}
                     className="w-full flex items-center p-3 rounded-2xl transition-all hover:bg-blue-50 dark:hover:bg-blue-900/10"
                   >
                      <div className="relative">
                        <img src={user.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-full object-cover border-2 border-white dark:border-white/10" />
                        {user.isOnline && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-darkbg"></div>}
                      </div>
                      <div className="ml-3 text-left">
                         <p className="font-black text-sm dark:text-white">{user.firstName} {user.lastName}</p>
                         <p className="text-[9px] text-gray-400 font-bold uppercase">Toque para conversar</p>
                      </div>
                   </button>
                ))}
             </div>
          )}

          {filteredConversations.length === 0 && filteredFollowers.length === 0 ? (
             <div className="p-8 text-center text-gray-400 text-xs font-bold uppercase tracking-widest">
                Nenhuma conversa encontrada.
             </div>
          ) : (
             filteredConversations.map(chat => {
                const isGroup = chat.type === ChatType.GROUP;
                const lastMsg = chat.messages[chat.messages.length - 1];
                const isActive = selectedChat?.id === chat.id;
                const { name, image, isOnline } = getChatDisplayInfo(chat);
                const itemChatTheme = chat.theme || 'blue';
                const itemThemeStyles = THEME_CONFIG[itemChatTheme];
                const messageCount = chat.messages.length;

                return (
                  <button
                    key={chat.id}
                    onClick={() => setSelectedChat(chat)}
                    className={`w-full flex items-center p-3 rounded-2xl transition-all mb-0.5 ${isActive ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
                  >
                    <div className="relative shrink-0">
                      <img src={image} className="w-12 h-12 rounded-full object-cover border border-black/5 shadow-sm bg-white" />
                      {isGroup ? (
                        <div className="absolute -bottom-0.5 -right-0.5 bg-blue-600 p-0.5 rounded-full border border-white"><UserGroupIcon className="h-2.5 w-2.5 text-white"/></div>
                      ) : (
                        isOnline && <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white dark:border-darkbg shadow-sm"></div>
                      )}
                    </div>
                    <div className="ml-3 text-left overflow-hidden flex-1">
                      <div className="flex justify-between items-center mb-0.5">
                          <p className={`font-black text-sm truncate uppercase tracking-tighter ${isActive ? 'text-white' : 'dark:text-white'}`}>{name}</p>
                          <div className="flex flex-col items-end">
                             {lastMsg && <span className={`text-[8px] font-bold ${isActive ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(lastMsg.timestamp).getHours()}:{new Date(lastMsg.timestamp).getMinutes().toString().padStart(2, '0')}</span>}
                          </div>
                      </div>
                      <div className="flex justify-between items-center">
                          <p className={`text-[11px] truncate leading-tight ${isActive ? 'text-blue-100' : 'text-gray-400 font-medium'} max-w-[80%]`}>
                              {lastMsg ? (lastMsg.isDeleted ? '🚫 Mensagem apagada' : lastMsg.text || '📷 Imagem') : 'Nenhuma mensagem'}
                          </p>
                          {messageCount > 0 && (
                             <span className={`text-[8px] font-black text-white px-2 py-0.5 rounded-full ml-2 shadow-sm ${isActive ? 'bg-white/20' : itemThemeStyles.primary}`}>
                                {messageCount > 99 ? '99+' : messageCount}
                             </span>
                          )}
                      </div>
                    </div>
                  </button>
                );
             })
          )}
        </div>
      </div>

      {/* CHAT AREA */}
      <div className={`flex-col h-full relative w-full ${selectedChat ? 'flex' : 'hidden md:flex flex-1'}`}>
        {selectedChat && activeChatInfo ? (
          <>
            <div className={`h-16 flex items-center justify-between px-4 text-white z-30 transition-colors duration-500 ${themeStyles.primary} shadow-lg shrink-0`}>
               <div className="flex items-center gap-3">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-white/90 hover:bg-white/10 rounded-full"><ArrowLeftIcon className="h-5 w-5 stroke-[3]"/></button>
                  <div className="flex items-center gap-3 cursor-pointer" onClick={() => setShowGroupMenu(!showGroupMenu)}>
                     <div className="relative">
                        <img src={activeChatInfo.image} className="w-10 h-10 rounded-full object-cover border-2 border-white/20 bg-white" />
                        {activeChatInfo.isOnline && !showGroupMenu && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-400 rounded-full border-2 border-blue-600"></div>}
                     </div>
                     <div className="leading-tight">
                        <h3 className="text-sm font-black uppercase tracking-tight">{activeChatInfo.name}</h3>
                        <p className="text-[9px] text-white/80 font-bold uppercase">
                            {selectedChat.type === ChatType.GROUP 
                                ? `${selectedChat.participants.length} membros` 
                                : activeChatInfo.isOnline ? 'Online agora' : `Visto: ${new Date(activeChatInfo.lastSeen).toLocaleTimeString()}`}
                        </p>
                     </div>
                  </div>
               </div>

               <div className="flex items-center gap-1">
                  <button onClick={() => startCall('voice')} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PhoneIcon className="h-5 w-5"/></button>
                  <button onClick={() => startCall('video')} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><VideoCameraIcon className="h-5 w-5"/></button>

                  {selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id && (
                    <div className="relative">
                       <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PaintBrushIcon className="h-5 w-5"/></button>
                       {showThemeMenu && (
                          <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in overflow-hidden max-h-60 overflow-y-auto custom-scrollbar">
                             <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest p-2 border-b dark:border-white/5">Alterar Tema</p>
                             {(Object.keys(THEME_CONFIG) as GroupTheme[]).map(t => (
                               <button 
                                key={t} 
                                onClick={() => handleChangeTheme(t)}
                                className="w-full flex items-center gap-3 p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                               >
                                  <div className={`w-4 h-4 rounded-full ${THEME_CONFIG[t].primary}`} />
                                  <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{t}</span>
                               </button>
                             ))}
                          </div>
                       )}
                    </div>
                  )}

                  <div className="relative">
                    <button onClick={() => setShowGroupMenu(!showGroupMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all"><EllipsisVerticalIcon className="h-5 w-5"/></button>
                    {showGroupMenu && (
                        <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in">
                            <button className="w-full text-left px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-2 text-xs dark:text-white rounded-xl transition-all" onClick={() => { alert(`Chat: ${selectedChat.groupName || 'Privado'}`); setShowGroupMenu(false); }}>
                                <InformationCircleIcon className="h-4 w-4 text-blue-500" /> Detalhes
                            </button>

                            {selectedChat.type === ChatType.GROUP && (
                                <button onClick={confirmLeaveGroup} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-500 rounded-xl transition-all">
                                    <ArrowRightOnRectangleIcon className="h-4 w-4" /> Sair do Grupo
                                </button>
                            )}

                            {selectedChat.type === ChatType.PRIVATE && (
                                <button onClick={confirmDeleteChat} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-500 rounded-xl transition-all border-t border-gray-100 dark:border-white/5 mt-1">
                                    <TrashIcon className="h-4 w-4" /> Excluir Conversa
                                </button>
                            )}

                            {selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id && (
                                <button onClick={confirmDeleteChat} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-600 font-bold rounded-xl transition-all border-t border-gray-100 dark:border-white/5 mt-1">
                                    <TrashIcon className="h-4 w-4" /> Excluir Grupo
                                </button>
                            )}
                        </div>
                    )}
                  </div>
               </div>
            </div>

            <div className={`flex-1 overflow-y-auto p-2 md:p-6 custom-scrollbar relative transition-colors duration-500 ${themeStyles.bg}`}>
               <div className="absolute inset-0 opacity-[0.08] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

               <div className="max-w-4xl mx-auto flex flex-col gap-2 relative z-10 pb-4">
                  {selectedChat.messages.map((msg, i) => {
                    const isMine = msg.senderId === currentUser.id;
                    const prevMsg = selectedChat.messages[i-1];
                    const showName = selectedChat.type === ChatType.GROUP && !isMine && (!prevMsg || prevMsg.senderId !== msg.senderId);

                    const senderBubbleStyle = isMine 
                        ? `${themeStyles.bubble} rounded-tr-none ${chatTheme === 'black' ? 'text-white' : 'text-[#1f2937]'}` 
                        : 'bg-white dark:bg-[#12161f] rounded-tl-none dark:text-white';

                    return (
                      <div key={msg.id} className={`flex w-full ${isMine ? 'justify-end' : 'justify-start'}`}>
                         <div 
                           onClick={() => !msg.isDeleted && setSelectedMessageForAction(msg)}
                           className={`
                             relative max-w-[85%] md:max-w-[65%] p-2 rounded-2xl shadow-sm cursor-pointer active:scale-[0.98] transition-transform
                             ${senderBubbleStyle}
                           `}
                         >
                            {msg.replyTo && !msg.isDeleted && (
                               <div className="mb-1 pl-2 border-l-2 border-blue-500 bg-black/5 dark:bg-white/5 rounded-r-md p-1 opacity-80">
                                  <p className="text-[9px] font-bold text-blue-600 dark:text-blue-400">{msg.replyTo.senderName}</p>
                                  <p className="text-[10px] truncate max-w-[150px]">{msg.replyTo.text}</p>
                               </div>
                            )}

                            {showName && <p className={`text-[10px] font-black uppercase mb-1 px-1 ${themeStyles.text}`}>Membro #{msg.senderId.slice(-4)}</p>}

                            {msg.isDeleted ? (
                                <div className="italic text-gray-500 text-xs px-2 py-1 flex items-center gap-1">
                                   <XMarkIcon className="h-3 w-3" /> <span className="opacity-70">Mensagem apagada</span>
                                </div>
                            ) : (
                                <>
                                    {msg.imageUrl && <img src={msg.imageUrl} className="w-full h-auto rounded-xl mb-1.5" alt="Anexo" />}
                                    <div className="px-1 flex flex-col items-end gap-x-2">
                                       <p className="text-sm font-medium leading-relaxed whitespace-pre-wrap break-words min-w-0 w-full text-left">
                                          {msg.text} 
                                          {msg.isEdited && <span className="text-[9px] opacity-60 ml-1 italic">(editado)</span>}
                                       </p>
                                       <div className="flex items-center gap-1 mt-1 opacity-60">
                                          <span className="text-[9px] font-bold">
                                             {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                          </span>
                                          {isMine && <CheckBadgeIcon className={`h-3 w-3 ${chatTheme === 'black' ? 'text-white' : themeStyles.text}`} />}
                                       </div>
                                    </div>
                                </>
                            )}
                         </div>
                      </div>
                    );
                  })}
                  <div ref={messagesEndRef} />
               </div>
            </div>

            <div className="p-2 md:p-4 bg-white dark:bg-[#12161f] border-t dark:border-white/5 relative z-40 shrink-0">
               {(replyingTo || editingMessageId) && (
                  <div className="absolute bottom-full left-0 w-full bg-gray-50 dark:bg-[#1a1c23] border-t border-black/5 dark:border-white/5 p-3 flex justify-between items-center animate-slide-up shadow-lg z-50">
                     <div className="flex items-center gap-3 px-2 border-l-4 border-blue-500 overflow-hidden">
                        <div className="text-blue-500 shrink-0">
                           {replyingTo ? <ArrowUturnLeftIcon className="h-5 w-5" /> : <PencilIcon className="h-5 w-5" />}
                        </div>
                        <div className="min-w-0">
                           <p className="text-[10px] font-black uppercase text-blue-600 dark:text-blue-400">
                              {replyingTo ? 'Respondendo' : 'Editando'}
                           </p>
                           <p className="text-xs text-gray-600 dark:text-gray-300 truncate">
                              {replyingTo ? replyingTo.text : ''}
                           </p>
                        </div>
                     </div>
                     <button onClick={cancelAction} className="p-2 hover:bg-gray-200 dark:hover:bg-white/10 rounded-full text-gray-500"><XMarkIcon className="h-5 w-5" /></button>
                  </div>
               )}

               <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-end gap-2">
                  <div className="flex-1 flex items-end gap-2 bg-gray-100 dark:bg-white/5 p-2 rounded-[1.5rem] border border-transparent focus-within:border-blue-500/30 focus-within:bg-white dark:focus-within:bg-[#1a1c23] transition-all">
                     <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-400 hover:text-blue-500 transition-all shrink-0"><PhotoIcon className="h-6 w-6"/></button>
                     <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) {
                           const r = new FileReader();
                           r.onloadend = () => setAttachedImage(r.result as string);
                           r.readAsDataURL(file);
                        }
                     }} />
                     <textarea 
                       ref={inputRef}
                       value={newMessage} 
                       onChange={e => setNewMessage(e.target.value)}
                       placeholder="Mensagem" 
                       rows={1}
                       className="flex-1 bg-transparent border-none outline-none text-sm font-medium dark:text-white py-3 px-1 max-h-32 resize-none no-scrollbar"
                       onInput={(e) => {
                         const target = e.target as HTMLTextAreaElement;
                         target.style.height = 'auto';
                         target.style.height = `${target.scrollHeight}px`;
                       }}
                       onKeyDown={(e) => {
                         if (e.key === 'Enter' && !e.shiftKey) {
                           e.preventDefault();
                           handleSend(e);
                         }
                       }}
                     />
                  </div>
                  <button 
                    type="submit" 
                    disabled={!newMessage.trim() && !attachedImage} 
                    className={`p-3.5 rounded-full shadow-lg transition-all active:scale-90 disabled:opacity-50 text-white mb-1 ${themeStyles.primary}`}
                  >
                     {editingMessageId ? <CheckBadgeIcon className="h-6 w-6" /> : <PaperAirplaneIcon className="h-6 w-6 -rotate-45 ml-0.5" />}
                  </button>
               </form>
            </div>

            {selectedMessageForAction && (
              <div className="fixed inset-0 z-[9999] flex items-end md:items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in" onClick={() => setSelectedMessageForAction(null)}>
                 <div 
                   className="bg-white dark:bg-[#1a1c23] w-full md:w-[320px] rounded-t-[2rem] md:rounded-[2rem] p-6 shadow-2xl animate-slide-up border-t md:border border-white/10"
                   onClick={e => e.stopPropagation()}
                 >
                    <div className="w-12 h-1.5 bg-gray-200 dark:bg-white/10 rounded-full mx-auto mb-6 md:hidden"></div>

                    <div className="flex flex-col gap-2">
                       <button onClick={() => { handleAction('reply'); setSelectedMessageForAction(null); }} className="flex items-center gap-4 p-4 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all">
                          <ArrowUturnLeftIcon className="h-5 w-5 text-blue-500" />
                          <span className="font-black text-sm dark:text-white">Responder</span>
                       </button>

                       <button onClick={() => { handleAction('copy'); setSelectedMessageForAction(null); }} className="flex items-center gap-4 p-4 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all">
                          <DocumentDuplicateIcon className="h-5 w-5 text-gray-500" />
                          <span className="font-black text-sm dark:text-white">Copiar</span>
                       </button>

                       {selectedMessageForAction.senderId === currentUser.id && (
                          <button onClick={() => { handleAction('edit'); setSelectedMessageForAction(null); }} className="flex items-center gap-4 p-4 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all">
                             <PencilIcon className="h-5 w-5 text-gray-500" />
                             <span className="font-black text-sm dark:text-white">Editar</span>
                          </button>
                       )}

                       {(selectedMessageForAction.senderId === currentUser.id || (selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id)) && (
                          <button onClick={() => { handleAction('delete'); setSelectedMessageForAction(null); }} className="flex items-center gap-4 p-4 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-2xl transition-all text-red-500">
                             <TrashIcon className="h-5 w-5" />
                             <span className="font-black text-sm">Apagar</span>
                          </button>
                       )}
                    </div>
                 </div>
              </div>
            )}

          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-10 bg-white dark:bg-[#0a0c10]">
             <div className="w-32 h-32 bg-gray-50 dark:bg-white/5 rounded-full flex items-center justify-center mb-6 animate-pulse">
                <ChatBubbleLeftRightIcon className="h-16 w-16 text-gray-200 dark:text-gray-700" />
             </div>
             <h3 className="text-xl font-black uppercase tracking-tighter dark:text-white">Selecione uma conversa</h3>
             <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-2 max-w-xs mb-8">Envie mensagens privadas ou crie comunidades.</p>
             <button 
               onClick={() => onNavigate('create-group')}
               className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-3"
             >
               <PlusIcon className="h-5 w-5 stroke-[3]" /> Nova Comunidade
             </button>
          </div>
        )}
      </div>

      {activeCall && <CallModal partner={activeCall.partner} group={activeCall.group} type={activeCall.type} onClose={() => setActiveCall(null)} />}

      <ConfirmationModal
        isOpen={confirmConfig.isOpen}
        onClose={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}
        onConfirm={confirmConfig.onConfirm}
        title={confirmConfig.title}
        message={confirmConfig.message}
        confirmText={confirmConfig.confirmText}
        type={confirmConfig.type}
      />

      <style>{`
        @keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } }
        .animate-slide-up { animation: slide-up 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default ChatPage;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Comment, PostType } from '../types';
import { 
  getPosts, 
  findUserById, 
  processDonation, 
  deletePost, 
  updatePost,
  subscribeToLivePost,
  sendLiveMessage,
  manageLiveViewers,
  pulseLiveHeart,
  generateUUID,
  uploadFile
} from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  SignalIcon, 
  UsersIcon, 
  PowerIcon, 
  BanknotesIcon, 
  PaperAirplaneIcon, 
  SparklesIcon, 
  HeartIcon, 
  EllipsisHorizontalIcon, 
  HandRaisedIcon,
  ArrowPathIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import ConfirmationModal from './ConfirmationModal';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [isHandRaised, setIsHandRaised] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [isEnding, setIsEnding] = useState(false); // Estado de encerramento
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [showEndConfirm, setShowEndConfirm] = useState(false);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Recording Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);

  const isInitializedRef = useRef(false);

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
      });
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
        mediaRecorderRef.current.stop();
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription
  useEffect(() => {
    if (!postId) return;

    manageLiveViewers(postId, 'join');

    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        if (updatedPost.liveStream?.status === 'ENDED') {
            if (currentUser.id !== updatedPost.userId) {
                alert("A transmissão foi encerrada pelo professor.");
                onNavigate('feed');
            }
            return;
        }

        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount, currentUser.id, onNavigate]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const startRecording = (stream: MediaStream) => {
    try {
        const options = { mimeType: 'video/webm' };
        const recorder = new MediaRecorder(stream, options);

        recordedChunksRef.current = [];
        recorder.ondataavailable = (event) => {
            if (event.data.size > 0) {
                recordedChunksRef.current.push(event.data);
            }
        };

        recorder.start(1000); // 1s chunks
        mediaRecorderRef.current = recorder;
        setIsRecording(true);
        console.log("Gravação iniciada");
    } catch (e) {
        console.warn("MediaRecorder falhou ou não suportado:", e);
    }
  };

  const stopRecordingAndGetBlob = (): Promise<Blob> => {
      return new Promise((resolve) => {
          const recorder = mediaRecorderRef.current;
          if (!recorder) {
              resolve(new Blob([], { type: 'video/webm' }));
              return;
          }

          const finish = () => {
              const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
              resolve(blob);
          };

          if (recorder.state === 'recording') {
              recorder.onstop = finish;
              recorder.stop();
          } else {
              finish();
          }
      });
  };

  const handleEndLive = async () => {
    setShowEndConfirm(false);
    if (!post) return;
    setIsEnding(true); // Mostra loader

    try {
        let recordingUrl = "https://res.cloudinary.com/dblnktl9m/video/upload/v1740939023/cyberphone/reels/ba776274-0f2c-497d-b08e-32432924403c.webm"; // Fallback default

        // Tentar parar gravação e fazer upload
        if (mediaRecorderRef.current) {
            const blob = await stopRecordingAndGetBlob();
            if (blob.size > 0) {
                // Upload real
                try {
                    recordingUrl = await uploadFile(blob, 'recordings');
                } catch (upErr) {
                    console.error("Erro no upload da gravação, usando fallback.", upErr);
                }
            }
        }

        stopStreams();

        const updatedPost: Post = {
            ...post,
            liveStream: {
                ...post.liveStream!,
                status: 'ENDED',
                recordingUrl: recordingUrl
            }
        };
        await updatePost(updatedPost);
        await refreshUser();

        // Pequeno delay para UX
        setTimeout(() => {
            onNavigate('profile', { userId: currentUser.id });
        }, 1500);

    } catch (e) {
        console.error("Erro ao encerrar live:", e);
        setIsEnding(false);
        handleExit();
    }
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];

        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);

        setIsCamOn(true);
        if (videoElementRef.current) {
            videoElementRef.current.srcObject = streamRef.current;
        }
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  useEffect(() => {
      if (creator && currentUser.id === creator.id && post && !isInitializedRef.current) {
          isInitializedRef.current = true;

          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }
                  // Start recording automatically for host
                  startRecording(stream);
              } catch (e) {
                  console.error("Erro camera:", e);
                  alert("Erro ao acessar câmera. Verifique permissões.");
              }
          };
          initCam();
      }
  }, [creator, currentUser.id, post]); 

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = async () => {
    if (!pendingAmount || !creator || !post) return;

    if ((currentUser.balance || 0) < pendingAmount) { 
        alert("Saldo insuficiente."); 
        return; 
    }

    setIsProcessingDonation(true);

    const success = await processDonation(currentUser.id, creator.id, pendingAmount, `Live: ${post.liveStream?.title || 'Aula'}`);

    if (success) {
        refreshUser();
        setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

        const sysMsg: Comment = {
            id: generateUUID(),
            userId: 'system',
            userName: 'Sistema',
            text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
            timestamp: Date.now()
        };
        sendLiveMessage(postId, sysMsg);
        pulseLiveHeart(postId);

        setTimeout(() => setDonationAlert(null), 5000);
        setIsProcessingDonation(false);
        setPendingAmount(null);
        setShowDonationModal(false);
    } else {
        alert("Erro ao processar doação.");
        setIsProcessingDonation(false);
    }
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); 

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); 
      pulseLiveHeart(postId); 
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    setChatMessages(prev => [...prev, msg]);
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 {isRecording && isProfessional && (
                    <div className="bg-black/50 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider text-red-400 flex items-center gap-1">
                        <div className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse"></div> REC
                    </div>
                 )}
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10 mt-1">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button 
                onClick={isProfessional ? () => setShowEndConfirm(true) : handleExit} 
                className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90"
              >
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* Loading Overlay when Ending */}
        {isEnding && (
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center pointer-events-auto">
                <ArrowPathIcon className="h-12 w-12 text-white animate-spin mb-4" />
                <h3 className="text-xl font-black uppercase tracking-widest text-white">Salvando Aula...</h3>
                <p className="text-xs text-gray-400 font-bold mt-2">Aguarde o upload da gravação</p>
            </div>
        )}

        {/* MIDDLE LAYER */}
        <div className="flex-1 relative w-full pointer-events-none">
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {isHandRaised && (
             <div className="absolute top-20 right-4 animate-bounce">
                <div className="bg-yellow-500 text-black p-2 rounded-full shadow-lg border-2 border-white">
                   <HandRaisedIcon className="h-6 w-6" />
                </div>
             </div>
           )}

           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">
           <div className="w-[85%] md:w-[400px] h-40 md:h-64 overflow-y-auto no-scrollbar mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade mb-2">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.userId === currentUser.id ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.userName}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           <div className="flex items-center gap-2 md:gap-3 pb-safe mb-2 md:mb-0">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-lg rounded-full px-4 py-3 border border-white/10 focus-within:bg-white/20 transition-all shadow-lg min-w-0">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full min-w-0"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white/80 hover:text-blue-400 transition-colors disabled:opacity-30 shrink-0">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <div className="flex items-center gap-2 shrink-0">
                 <button 
                   onClick={handleSendHeart}
                   className="p-3 bg-gradient-to-tr from-pink-500 to-red-600 text-white rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-transform"
                 >
                    <HeartIcon className="h-5 w-5" />
                 </button>

                 <div className="relative">
                    <button 
                      onClick={() => setShowControls(!showControls)} 
                      className="p-3 bg-gray-800 rounded-full border border-white/20 text-white hover:bg-gray-700 transition-all shadow-lg"
                    >
                        <EllipsisHorizontalIcon className="h-5 w-5" />
                    </button>

                    {showControls && (
                        <div className="absolute bottom-full right-0 mb-4 bg-black/90 border border-white/10 rounded-2xl p-2 flex flex-col gap-2 shadow-2xl backdrop-blur-xl animate-scale-in origin-bottom-right min-w-[60px] items-center z-50">
                            {isProfessional ? (
                                <>
                                    <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Microfone">
                                        {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                                    </button>
                                    <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Câmera">
                                        {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                                    </button>
                                    <div className="h-px w-full bg-white/10 my-1"></div>
                                    <button 
                                      onClick={() => setShowEndConfirm(true)} 
                                      className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all text-white" 
                                      title="Encerrar"
                                    >
                                        <PowerIcon className="h-5 w-5" />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button 
                                        onClick={() => { setShowDonationModal(true); setShowControls(false); }}
                                        className="p-3 bg-yellow-500 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-90 transition-transform"
                                        title="Apoiar"
                                    >
                                        <BanknotesIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                        onClick={toggleHandRaise}
                                        className={`p-3 rounded-full transition-all active:scale-90 ${isHandRaised ? 'bg-orange-500 text-white' : 'bg-white/10 text-white'}`}
                                        title="Levantar Mão"
                                    >
                                        {isHandRaised ? <HandRaisedIcon className="h-5 w-5" /> : <HandRaisedOutline className="h-5 w-5" />}
                                    </button>
                                </>
                            )}
                        </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      </div>

      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <ConfirmationModal 
        isOpen={showEndConfirm}
        onClose={() => setShowEndConfirm(false)}
        onConfirm={handleEndLive}
        title="Encerrar Transmissão"
        message="Deseja encerrar e salvar esta aula na sua biblioteca para que os alunos possam assistir depois?"
        confirmText="Encerrar e Salvar"
        type="warning"
      />

      <style>{`
        .mask-gradient-chat {
           mask-image: linear-gradient(to top, black 85%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 85%, transparent 100%);
        }
        .pb-safe {
           padding-bottom: max(env(safe-area-inset-bottom), 20px);
        }
        @keyframes slide-right-fade {
           from { opacity: 0; transform: translateX(-10px); }
           to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-right-fade { animation: slide-right-fade 0.2s ease-out forwards; }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, UserType, Store, Product, ProductType, OrderStatus, AffiliateSale } from '../types';
import { 
  getStores, 
  getProducts, 
  createProduct,
  updateStore,
  getAffiliateSales,
  updateSaleStatus,
  uploadFile,
  adminDeleteProduct,
  generateUUID,
  fulfillDropshippingOrder,
  updateSaleTracking,
  createStore,
  updateUser,
  processUserUpgrade
} from '../services/storageService';
import { sourceDropshippingProducts } from '../services/geminiService';
import { CREATOR_UPGRADE_COST_USD } from '../data/constants';
import { 
  PlusIcon, 
  ArchiveBoxIcon,
  TrashIcon,
  CheckBadgeIcon,
  BoltIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
  PaintBrushIcon,
  ClipboardDocumentListIcon,
  CurrencyDollarIcon,
  TruckIcon,
  GlobeAmericasIcon,
  CalculatorIcon,
  ArrowPathIcon,
  TagIcon,
  PhotoIcon,
  DocumentArrowUpIcon,
  ShieldCheckIcon,
  LockClosedIcon,
  BanknotesIcon
} from '@heroicons/react/24/solid';
import WalletModal from './WalletModal';
import ConfirmationModal from './ConfirmationModal';

interface StoreManagerPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate: (page: any, params?: any) => void;
}

type ManagerTab = 'inventory' | 'orders' | 'sourcing' | 'branding';

const BRAND_COLORS = [
  { name: 'Azul CyBer', hex: '#2563eb' },
  { name: 'Roxo Royal', hex: '#7c3aed' },
  { name: 'Verde Mint', hex: '#10b981' },
  { name: 'Preto Carbono', hex: '#0f172a' },
  { name: 'Laranja Solar', hex: '#f59e0b' },
  { name: 'Rosa Shock', hex: '#db2777' }
];

const CATEGORIES_SOURCING = [
    'Tech & Gadgets', 'Moda Masculina', 'Moda Feminina', 'Casa Inteligente', 'Fitness', 'Beleza'
];

const StoreManagerPage: React.FC<StoreManagerPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [userStore, setUserStore] = useState<Store | null>(null);
  const [storeProducts, setStoreProducts] = useState<Product[]>([]);
  const [storeSales, setStoreSales] = useState<AffiliateSale[]>([]);
  const [activeTab, setActiveTab] = useState<ManagerTab>('inventory');
  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [loading, setLoading] = useState(true);

  // Upgrade States
  const [docFile, setDocFile] = useState<File | null>(null);
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [isUpgrading, setIsUpgrading] = useState(false);
  const [showWalletModal, setShowWalletModal] = useState(false);
  const docInputRef = useRef<HTMLInputElement>(null);

  const [brandName, setBrandName] = useState('');
  const [brandDesc, setBrandDesc] = useState('');
  const [brandColor, setBrandColor] = useState(BRAND_COLORS[0].hex);

  // Product Form
  const [pName, setPName] = useState('');
  const [pDesc, setPDesc] = useState('');
  const [pPrice, setPPrice] = useState('');
  const [pType, setPType] = useState<ProductType>(ProductType.DIGITAL_COURSE);
  const [pImg, setPImg] = useState('');
  const [pDigitalUrl, setPDigitalUrl] = useState('');
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sourcing & Import Logic
  const [searchQuery, setSearchQuery] = useState('');
  const [sourcingResults, setSourcingResults] = useState<any[]>([]);
  const [isSourcing, setIsSourcing] = useState(false);
  const [importModal, setImportModal] = useState<any | null>(null); // Produto sendo importado
  const [importPrice, setImportPrice] = useState<string>(''); // Preço final definido pelo usuário

  const [trackingModal, setTrackingModal] = useState<{saleId: string} | null>(null);
  const [trackingCode, setTrackingCode] = useState('');
  const [supplierOrderId, setSupplierOrderId] = useState('');

  // Confirmation Modal
  const [deleteProductTarget, setDeleteProductTarget] = useState<string | null>(null);

  const loadData = async () => {
    setLoading(true);
    const stores = await getStores();
    const myStore = stores.find(s => s.professorId === currentUser.id);
    if (myStore) {
      setUserStore(myStore);
      setBrandName(myStore.name);
      setBrandDesc(myStore.description);
      setBrandColor(myStore.brandColor || BRAND_COLORS[0].hex);
      const allProds = await getProducts();
      setStoreProducts(allProds.filter(p => p.storeId === myStore.id));
      const allSales = await getAffiliateSales();
      setStoreSales(allSales.filter(s => s.storeId === myStore.id).sort((a, b) => b.timestamp - a.timestamp));
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, [currentUser.id]);

  // Trigger sourcing on mount for generic categories
  useEffect(() => {
      if (activeTab === 'sourcing' && sourcingResults.length === 0) {
          handleSource("Tendências de Tecnologia");
      }
  }, [activeTab]);

  const handleSaveBranding = async () => {
    if (!userStore) return;
    const updated = { ...userStore, name: brandName, description: brandDesc, brandColor };
    await updateStore(updated);
    setUserStore(updated);
    alert('Identidade visual da loja atualizada!');
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
        const url = await uploadFile(file, 'products');
        setPImg(url);
    } catch (err) {
        alert('Erro ao enviar imagem do produto.');
    } finally {
        setUploading(false);
    }
  };

  const handleCreateProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userStore || uploading) return;

    const newProduct: Product = {
      id: generateUUID(),
      storeId: userStore.id,
      name: pName,
      description: pDesc,
      price: parseFloat(pPrice),
      imageUrls: [pImg || 'https://picsum.photos/400/400?random=prod'],
      affiliateCommissionRate: 0.15,
      type: pType,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      digitalContentUrl: pType !== ProductType.PHYSICAL ? pDigitalUrl : undefined
    };

    await createProduct(newProduct);
    setIsAddingProduct(false);
    setPImg(''); setPName(''); setPDesc(''); setPPrice('');
    loadData();
    alert('Produto criado com sucesso!');
  };

  const confirmDeleteProduct = async () => {
    if (deleteProductTarget) {
      await adminDeleteProduct(deleteProductTarget);
      loadData();
      setDeleteProductTarget(null);
    }
  };

  const handleFulfillOrder = async (sale: AffiliateSale) => {
    if (!sale.supplierCost) {
      alert("Custo do fornecedor não definido.");
      return;
    }

    if ((currentUser.balance || 0) < sale.supplierCost) {
      alert(`Saldo insuficiente para pagar o fornecedor ($${sale.supplierCost}). Recarregue sua carteira.`);
      return;
    }

    if (confirm(`Confirmar pagamento de $${sale.supplierCost} ao fornecedor para iniciar o despacho?`)) {
       const success = await fulfillDropshippingOrder(sale.id, currentUser.id, sale.supplierCost);
       if (success) {
         refreshUser(); 
         loadData();
         alert("Pedido enviado para processamento no fornecedor!");
       } else {
         alert("Erro ao processar pagamento.");
       }
    }
  };

  const handleAddTracking = async () => {
    if (!trackingModal || !trackingCode) return;
    await updateSaleStatus(trackingModal.saleId, OrderStatus.SHIPPING);
    await updateSaleTracking(trackingModal.saleId, trackingCode, supplierOrderId);
    setTrackingModal(null);
    setTrackingCode('');
    setSupplierOrderId('');
    loadData();
    alert("Código de rastreio atualizado!");
  }

  const handleSource = async (queryOverride?: string) => {
    const q = queryOverride || searchQuery;
    if (!q) return;
    setIsSourcing(true);
    const results = await sourceDropshippingProducts(q);
    setSourcingResults(results);
    setIsSourcing(false);
  };

  const openImportModal = (product: any) => {
      setImportModal(product);
      setImportPrice((product.originalPrice * 2).toFixed(2)); // Sugestão 2x markup
  };

  const confirmImport = async () => {
    if (!userStore || !importModal) return;

    const finalPrice = parseFloat(importPrice);
    if (isNaN(finalPrice) || finalPrice <= importModal.originalPrice) {
        alert("O preço de venda deve ser maior que o custo.");
        return;
    }

    const newProduct: Product = {
      id: generateUUID(),
      storeId: userStore.id,
      name: importModal.name,
      description: importModal.description,
      price: finalPrice,
      imageUrls: [importModal.imageUrl],
      affiliateCommissionRate: 0.1, // 10% padrão para afiliados
      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: importModal.externalProviderId,
      originalPrice: importModal.originalPrice
    };

    await createProduct(newProduct);
    setImportModal(null);
    loadData();
    alert('Item importado para sua vitrine com sucesso!');
  };

  // Lógica rigorosa de Upgrade
  const handleUpgradeProcess = async () => {
    if (!docFile) {
        alert("Obrigatório: Envie o documento de identificação profissional (PDF).");
        return;
    }
    if (!credentials.trim()) {
        alert("Obrigatório: Preencha sua especialidade.");
        return;
    }

    if ((currentUser.balance || 0) < CREATOR_UPGRADE_COST_USD) {
        if(confirm("Saldo insuficiente para a taxa de ativação. Deseja recarregar agora?")) {
            setShowWalletModal(true);
        }
        return;
    }

    if (!confirm(`Confirmar pagamento de $${CREATOR_UPGRADE_COST_USD} para ativar sua conta profissional?`)) return;

    setIsUpgrading(true);
    try {
        await processUserUpgrade(currentUser.id, currentUser, docFile, credentials);
        refreshUser();
        alert("Parabéns! Sua conta Profissional foi ativada com sucesso.");
        // Pequeno delay para propagação
        setTimeout(() => loadData(), 1500);
    } catch (e: any) {
        alert("Erro no upgrade: " + e.message);
    } finally {
        setIsUpgrading(false);
    }
  };

  const handleDocChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        if (file.type !== 'application/pdf') {
            alert("Apenas arquivos PDF são aceitos.");
            return;
        }
        setDocFile(file);
    }
  };

  if (currentUser.userType === UserType.STANDARD) {
    return (
      <div className="container mx-auto px-4 pt-24 pb-32 max-w-4xl animate-fade-in">
         <div className="bg-white dark:bg-darkcard rounded-[3rem] p-10 md:p-16 shadow-2xl border dark:border-white/5 relative overflow-hidden">

            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>

            <div className="text-center mb-12">
                <div className="bg-blue-50 dark:bg-blue-900/10 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-xl">
                    <CheckBadgeIcon className="h-12 w-12 text-blue-600" />
                </div>
                <h2 className="text-3xl md:text-5xl font-black mb-4 tracking-tighter dark:text-white uppercase">Torne-se um Profissional</h2>
                <p className="text-gray-500 text-sm md:text-base font-medium max-w-xl mx-auto leading-relaxed">
                    Desbloqueie ferramentas de venda, crie sua loja oficial, transmita lives pagas e ganhe destaque no feed.
                </p>
            </div>

