export const updatePostLikes = async (postId: string, userId: string) => {
  const postRef = doc(db, "posts", postId);
  const postSnap = await getDoc(postRef);
  if (postSnap.exists()) {
    const post = postSnap.data() as Post;
    let newLikes = post.likes || [];
    if (newLikes.includes(userId)) {
      newLikes = newLikes.filter(id => id !== userId);
    } else {
      newLikes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId, timestamp: Date.now() });
    }
    await updateDoc(postRef, { likes: newLikes });
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
    const postRef = doc(db, "posts", postId);
    const postSnap = await getDoc(postRef);
    if (postSnap.exists()) {
        const post = postSnap.data() as Post;
        let saves = post.saves || [];
        if(saves.includes(userId)) saves = saves.filter(id => id !== userId);
        else saves.push(userId);
        await updateDoc(postRef, { saves });
    }
};

export const updatePostShares = async (postId: string, userId: string) => { 
    const postRef = doc(db, "posts", postId);
    const postSnap = await getDoc(postRef);
    if (postSnap.exists()) {
        const post = postSnap.data() as Post;
