export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  const snap = await getDocs(collection(db, "chats"));
  const allChats = snap.docs.map(d => d.data() as ChatConversation);
  if (userId) {
    return allChats.filter(c => c.participants.includes(userId));
  }
  return allChats;
};

export const sendMessage = async (chatId: string, msg: any) => {
  const chatRef = doc(db, "chats", chatId);
  const chatSnap = await getDoc(chatRef);
  if (chatSnap.exists()) {
    const chat = chatSnap.data() as ChatConversation;
    // Força a mensagem a ser não lida inicialmente
    const newMsg = { ...msg, isRead: false }; 
    const newMessages = [...chat.messages, sanitizePayload(newMsg)];
    await updateDoc(chatRef, { messages: newMessages });

    // Notify
    chat.participants.forEach(pid => {
        if(pid !== msg.senderId) {
            createNotification({
                type: chat.type === 'GROUP' ? NotificationType.GROUP_POST : NotificationType.MESSAGE,
                recipientId: pid,
                actorId: msg.senderId,
                timestamp: Date.now(),
                groupName: chat.groupName
            });
        }
    });
  }
};

export const markChatMessagesAsRead = async (chatId: string, userId: string) => {
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);

    if (chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;
        let hasChanges = false;

        const updatedMessages = chat.messages.map(m => {
            // Marca como lida se o destinatário é quem está lendo e ainda não foi lida
            if (m.senderId !== userId && !m.isRead) {
                hasChanges = true;
                return { ...m, isRead: true };
            }
            return m;
        });

        if (hasChanges) {
            await updateDoc(chatRef, { messages: sanitizePayload(updatedMessages) });
        }
    }
};

