export const processDonation = async (fromId: string, toId: string, amount: number, message: string): Promise<boolean> => {
    const success = await updateUserBalance(fromId, -amount);
    if (success) {
        await updateUserBalance(toId, amount);
        await createNotification({ 
            type: NotificationType.MESSAGE, 
            recipientId: toId, 
            actorId: fromId, 
            timestamp: Date.now(),
            groupName: `Doação: $${amount}` 
        });
        await createTransaction({ id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Doação para ${toId}`, timestamp: Date.now(), status: 'COMPLETED' });
        await createTransaction({ id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Doação de ${fromId}`, timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
    return false;
};

export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  for (const item of cartItems) {
    const product = await findProductById(item.productId);
    if (!product) continue;
    const store = await findStoreById(product.storeId);
    if (!store) continue;

    const productOwner = await findUserById(store.professorId);
    if (!productOwner) continue;

    const itemTotal = product.price * item.quantity;
    const netRevenue = itemTotal * (1 - product.affiliateCommissionRate);

    await updateUserBalance(productOwner.id, netRevenue);

    let commissionEarned = 0;
    if (affiliateUserId) {
      const affiliate = await findUserById(affiliateUserId);
      if (affiliate) {
        commissionEarned = itemTotal * product.affiliateCommissionRate;
        await updateUserBalance(affiliate.id, commissionEarned);
        await createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliate.id, actorId: buyerId, timestamp: Date.now() });
      }
    }

    const newSale: AffiliateSale = {
      id: `sale-${Date.now()}-${item.productId}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned,
      saleAmount: itemTotal,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      isRated: false,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl,
      isDropshipping: product.isDropshipping,
      supplierCost: product.originalPrice
    };

    await setDoc(doc(db, "affiliate_sales", newSale.id), sanitizePayload(newSale));
  }

  clearCart();
  return true;
};

