export const handleWalletTransaction = async (u: string, a: number, t: 'deposit' | 'withdraw') => {
    if (t === 'withdraw') {
        if (await updateUserBalance(u, -a)) {
            await createTransaction({ id: generateUUID(), userId: u, type: TransactionType.WITHDRAWAL, amount: a, description: 'Saque', timestamp: Date.now(), status: 'PENDING' });
            return true;
        }
        return false;
    } else {
        await updateUserBalance(u, a);
        await createTransaction({ id: generateUUID(), userId: u, type: TransactionType.DEPOSIT, amount: a, description: 'Depósito', timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
};
