export default ChatPage;

export const deleteMessage = async (chatId: string, messageId: string, hardDelete: boolean = false) => { 
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;

        let newMessages;
        if (hardDelete) {
            // Remoção física da mensagem do array
            newMessages = chat.messages.filter(m => m.id !== messageId);
        } else {
            // Soft delete (marca como apagada)
            newMessages = chat.messages.map(m => m.id === messageId ? { 
                ...m, 
                isDeleted: true, 
                text: undefined, 
                imageUrl: undefined,
                fileUrl: undefined,
                fileType: undefined,
                fileName: undefined
            } : m);
        }

        await updateDoc(chatRef, { messages: sanitizePayload(newMessages) });
    }
};

