export const processDonation = async (fromId: string, toId: string, amount: number, message: string): Promise<boolean> => {
    if(updateUserBalance(fromId, -amount)) {
        updateUserBalance(toId, amount);
        createTransaction({ id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Donation to user ${toId}`, timestamp: Date.now(), status: 'COMPLETED' });
        createTransaction({ id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Donation from user ${fromId}`, timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
    return false;
};

export const handleWalletTransaction = async (userId: string, amount: number, type: 'deposit' | 'withdraw'): Promise<boolean> => {
    if (type === 'withdraw') {
        if (updateUserBalance(userId, -amount)) {
            createTransaction({ id: generateUUID(), userId, type: TransactionType.WITHDRAWAL, amount, description: 'Withdrawal', timestamp: Date.now(), status: 'PENDING' });
            return true;
        }
        return false;
    } else {
        updateUserBalance(userId, amount);
        createTransaction({ id: generateUUID(), userId, type: TransactionType.DEPOSIT, amount, description: 'Deposit', timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
};

