           </div>

           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Dados Pessoais</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Nome</label>
                    <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Sobrenome</label>
                    <input type="text" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Data de Nascimento</label>
                    <div className="relative">
                       <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                       <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Cargo ou Especialidade</label>
                      <input type="text" value={credentials} onChange={e => setCredentials(e.target.value)} placeholder="Ex: Professor" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                   </div>
                 )}

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Biografia</label>
                    <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Conte um pouco sobre você..." className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] dark:text-white outline-none border-2 border-transparent focus:border-brand font-medium h-32 resize-none" />
                 </div>
              </div>
           </div>

           <div className={`bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border transition-all ${currentUser.isAdmin ? 'border-green-500/20 shadow-green-500/10' : 'border-gray-200 dark:border-white/10 opacity-90'}`}>
              <div className="flex items-center justify-between mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                    {currentUser.isAdmin ? (
                        <><LockOpenIcon className="h-3 w-3 text-green-500" /> Acesso Administrativo (Desbloqueado)</>
                    ) : (
                        <><LockClosedIcon className="h-3 w-3" /> Dados Sensíveis (Protegidos)</>
                    )}
                 </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={email} 
                        onChange={e => setEmail(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>
              </div>
           </div>

           <button 
             type="submit" 
             disabled={isSaving || isUploading} 
             className="w-full py-6 bg-brand hover:bg-brandHover text-white rounded-[2.2rem] font-black uppercase text-sm tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
           >
             {isSaving ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
             ) : (
               <><CheckIcon className="h-6 w-6 stroke-[3]" /> Salvar Alterações</>
             )}
           </button>
        </form>
      </div>
    );
  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil & Senha', desc: 'Nome, bio, foto e segurança', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Cores e Modo Dark', icon: PaintBrushIcon, onClick: () => setView('appearance') }
      ]
    },
    {
      title: 'Sistema & Segurança',
      items: [
        { label: 'Diagnóstico & API', desc: 'Verificar conexões e chaves', icon: ServerIcon, onClick: () => setView('system') },
        { label: 'CyBer Card Pro', desc: 'Conta virtual (Beta)', icon: CreditCardIcon, onClick: () => setView('payments') },
        { label: 'Ajuda e Suporte', desc: 'Abrir tickets e resolver problemas', icon: LifebuoyIcon, onClick: () => onNavigate('support') },
        { label: 'Sair da Conta', desc: 'Desconectar dispositivo', icon: ArrowRightOnRectangleIcon, onClick: onLogout }
      ]
    }
  ];

  return (
    <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-4xl animate-fade-in">
      <div className="flex items-center gap-6 mb-10">
        <button onClick={() => onNavigate('profile')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
        <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tighter">Ajustes</h2>
      </div>

      <div className="space-y-10">
        {sections.map(section => (
          <div key={section.title}>
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">{section.title}</h3>
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-white/10 overflow-hidden">
              {section.items.map((item, idx) => (
                <div 
                  key={item.label} 
                  onClick={item.onClick}
                  className={`p-6 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-white/5 transition-colors cursor-pointer ${idx !== section.items.length - 1 ? 'border-b border-gray-50 dark:border-white/10' : ''}`}
                >
                  <div className="flex items-center gap-5">
                    <div className="p-3 rounded-2xl bg-brand/10 text-brand">
                      <item.icon className="h-6 w-6" />
                    </div>
                    <div>
                      <p className="font-black text-sm dark:text-white">{item.label}</p>
                      <p className="text-xs text-gray-400 font-bold">{item.desc}</p>
                    </div>
                  </div>
                  <ChevronDownIcon className="h-5 w-5 text-gray-300 -rotate-90" />
                </div>
              ))}
            </div>
          </div>
        ))}

        {/* ÁREA DE PERIGO PERSISTENTE */}
        <div className="mt-10 px-4 bg-red-50 dark:bg-red-900/10 p-8 rounded-[3rem] border border-red-100 dark:border-red-900/20">
           <div className="flex items-center gap-3 mb-4">
              <ExclamationTriangleIcon className="h-6 w-6 text-red-600" />
              <h3 className="text-sm font-black text-red-700 dark:text-red-400 uppercase tracking-widest">Área de Perigo</h3>
           </div>
           <p className="text-xs text-red-600/80 dark:text-red-400/80 font-medium mb-6 leading-relaxed">
              A exclusão da conta é permanente. Todos os seus dados, postagens, loja e saldo serão removidos dos nossos servidores.
           </p>

           <div className="flex flex-col gap-6">
               <button 
                 onClick={() => setShowDeleteConfirm(true)} 
                 disabled={isSaving}
                 className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-red-200 dark:shadow-none active:scale-95 transition-all flex items-center justify-center gap-2"
               >
                  {isSaving ? (
                      <>Processando Exclusão...</>
                  ) : (
                      <><TrashIcon className="h-4 w-4" /> Excluir Minha Conta</>
                  )}
               </button>

               <div 
                 onClick={handleVersionClick}
                 className="text-center opacity-30 hover:opacity-100 transition-opacity cursor-pointer select-none"
               >
                  <p className="text-[9px] font-black uppercase tracking-[0.3em] text-gray-400">
                     CyBerPhone Pro v1.3.3 (Stable)
                     {currentUser.isAdmin && <span className="text-red-500 ml-2">ROOT ACCESS</span>}
                  </p>
               </div>
           </div>
        </div>
      </div>

      <ConfirmationModal
        isOpen={showDeleteConfirm}
        onClose={() => setShowDeleteConfirm(false)}
        onConfirm={handleConfirmDelete}
        title="Excluir Conta?"
        message="Esta ação é irreversível. Todos os seus dados, saldo e conteúdo serão apagados permanentemente."
        confirmText="Sim, Apagar Tudo"
        type="danger"
        loading={isSaving}
      />
    </div>
  );
};

export default SettingsPage;

import React, { useState, useRef, useEffect } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, saveCurrentUser } from '../services/storageService';
import { isFirebaseConfigured } from '../services/firebaseClient';
import { 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  ExclamationTriangleIcon,
  LifebuoyIcon,
  CpuChipIcon,
  SignalIcon,
  ServerIcon
} from '@heroicons/react/24/outline';
import ConfirmationModal from './ConfirmationModal';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance' | 'system'>('main');

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Hidden Admin Access
  const [devClicks, setDevClicks] = useState(0);
  const ADMIN_EMAIL = 'admin@cyber.com';

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // System Diagnostics
  const hasGeminiKey = !!process.env.API_KEY;
  const hasFirebaseKey = isFirebaseConfigured;

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      // Persistência Imediata
      await updateUser(updatedUser);
      await refreshUser(); // Atualiza o estado global no App.tsx

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleConfirmDelete = async () => {
    try {
        setIsSaving(true); // Bloqueia UI
        await deleteUser(currentUser.id);
        // Limpa sessão local explicitamente
        saveCurrentUser(null);
        setShowDeleteConfirm(false);
        onDeleteAccount(); // Chama o logout/reset do pai
    } catch (error) {
        console.error("Erro ao deletar conta:", error);
        alert("Não foi possível excluir a conta no momento. Tente novamente.");
        setIsSaving(false);
        setShowDeleteConfirm(false);
    }
  };

  const handleVersionClick = async () => {
    const newCount = devClicks + 1;
    setDevClicks(newCount);

    if (newCount === 7) {
        if (currentUser.email.toLowerCase() === ADMIN_EMAIL) {
            const newStatus = !currentUser.isAdmin;
            await updateUser({ ...currentUser, isAdmin: newStatus });
            refreshUser();
            alert(`SISTEMA ROOT: Privilégios de Superusuário ${newStatus ? 'ATIVADOS' : 'DESATIVADOS'}.`);
        } else {
            alert(`⛔ ACESSO NEGADO\n\nConta não autorizada para Root.`);
        }
        setDevClicks(0);
    }
  };

  if (view === 'appearance') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">Estilo</h2>
          </div>

          <div className="space-y-10">
            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Tema de Cores</p>
                <div className="grid grid-cols-2 gap-4">
                    {THEMES.map(theme => (
                        <button 
                          key={theme.id}
                          onClick={() => onThemeChange(theme.id)}
                          className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${appTheme === theme.id ? 'border-brand bg-brand/5 shadow-xl' : 'border-gray-50 dark:border-white/5 hover:border-gray-200'}`}
                        >
                           <div className={`w-14 h-14 rounded-2xl ${theme.color} shadow-lg flex items-center justify-center`}>
                              {appTheme === theme.id && <CheckIcon className="h-7 w-7 text-white" />}
                           </div>
                           <span className={`text-xs font-black uppercase ${appTheme === theme.id ? 'text-brand' : 'text-gray-400'}`}>{theme.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 flex items-center justify-between">
                <div>
                    <p className="font-black text-sm dark:text-white uppercase tracking-tighter">Modo Escuro</p>
                    <p className="text-xs text-gray-400 font-bold">Inverter cores do sistema</p>
                </div>
                <button onClick={toggleTheme} className={`w-14 h-7 rounded-full transition-all relative ${darkMode ? 'bg-brand' : 'bg-gray-200'}`}>
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${darkMode ? 'right-1' : 'left-1'}`}></div>
                </button>
            </div>
          </div>
        </div>
    );
  }

  if (view === 'system') {
      return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
            <div className="flex items-center gap-6 mb-10">
                <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
                <h2 className="text-4xl font-black dark:text-white tracking-tighter">Sistema</h2>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-white/10 space-y-6">
                <h3 className="text-lg font-black dark:text-white uppercase tracking-tighter flex items-center gap-2">
                    <ServerIcon className="h-6 w-6 text-brand" /> Status das Conexões
                </h3>

                <div className="space-y-4">
                    <div className={`p-4 rounded-2xl border-2 flex items-center justify-between ${hasFirebaseKey ? 'border-green-500/20 bg-green-50 dark:bg-green-900/10' : 'border-red-500/20 bg-red-50 dark:bg-red-900/10'}`}>
                        <div className="flex items-center gap-3">
                            <SignalIcon className={`h-6 w-6 ${hasFirebaseKey ? 'text-green-600' : 'text-red-500'}`} />
                            <div>
                                <p className="font-black text-sm dark:text-white uppercase">Banco de Dados (Firebase)</p>
                                <p className="text-xs text-gray-500 font-medium">{hasFirebaseKey ? 'Conectado e Seguro' : 'Chave API não encontrada'}</p>
                            </div>
                        </div>
                        <div className={`w-3 h-3 rounded-full ${hasFirebaseKey ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></div>
                    </div>

                    <div className={`p-4 rounded-2xl border-2 flex items-center justify-between ${hasGeminiKey ? 'border-blue-500/20 bg-blue-50 dark:bg-blue-900/10' : 'border-orange-500/20 bg-orange-50 dark:bg-orange-900/10'}`}>
                        <div className="flex items-center gap-3">
                            <CpuChipIcon className={`h-6 w-6 ${hasGeminiKey ? 'text-blue-600' : 'text-orange-500'}`} />
                            <div>
                                <p className="font-black text-sm dark:text-white uppercase">Inteligência Artificial (Gemini)</p>
                                <p className="text-xs text-gray-500 font-medium">{hasGeminiKey ? 'Operacional' : 'Modo Offline (Sem Chave)'}</p>
                            </div>
                        </div>
                        <div className={`w-3 h-3 rounded-full ${hasGeminiKey ? 'bg-blue-500 animate-pulse' : 'bg-orange-500'}`}></div>
                    </div>
                </div>

                <div className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-xs text-gray-500 font-mono border border-dashed border-gray-200 dark:border-white/10">
                    <p>APP_VERSION: 1.3.3-stable</p>
                    <p>ENV: {(import.meta as any).env.MODE || 'production'}</p>
                    <p>BUILD_TIME: {new Date().toLocaleDateString()}</p>
                </div>
            </div>
        </div>
      );
  }

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-3xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-4xl font-black dark:text-white tracking-tighter">Dados de Inscrição</h2>
        </div>

        {saveSuccess && (
          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-500/30 rounded-2xl flex items-center gap-3 animate-fade-in">
             <CheckIcon className="h-5 w-5 text-green-600" />
             <p className="text-xs font-black text-green-700 dark:text-green-400 uppercase tracking-widest">Perfil atualizado!</p>
          </div>
        )}

        <form onSubmit={handleSaveProfile} className="space-y-8">
           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Identidade Visual</p>
              <div className="flex flex-col items-center gap-6">
                 <div 
                   onClick={() => fileInputRef.current?.click()} 
                   className="relative group cursor-pointer"
                 >
                    <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-white dark:border-darkcard shadow-2xl transition-transform group-hover:scale-105 relative">
                       <img src={profilePicture || 'https://via.placeholder.com/150'} className="w-full h-full object-cover" alt="Profile" />
                       {isUploading && (
                         <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                           <div className="w-8 h-8 border-4 border-white border-t-transparent animate-spin rounded-full"></div>
                         </div>
                       )}
                       <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                          <CameraIcon className="h-10 w-10 text-white" />
                       </div>
                    </div>
                    <div className="absolute -bottom-2 -right-2 bg-brand text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                       <PaintBrushIcon className="h-4 w-4" />
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileChange} 
                    />
                 </div>
                 <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Clique na foto para alterar</p>
              </div>
           </div>

           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Dados Pessoais</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Nome</label>
                    <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Sobrenome</label>
                    <input type="text" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Data de Nascimento</label>
                    <div className="relative">
                       <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                       <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Cargo ou Especialidade</label>
                      <input type="text" value={credentials} onChange={e => setCredentials(e.target.value)} placeholder="Ex: Professor" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                   </div>
                 )}

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Biografia</label>
                    <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Conte um pouco sobre você..." className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] dark:text-white outline-none border-2 border-transparent focus:border-brand font-medium h-32 resize-none" />
                 </div>
              </div>
           </div>

           <div className={`bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border transition-all ${currentUser.isAdmin ? 'border-green-500/20 shadow-green-500/10' : 'border-gray-200 dark:border-white/10 opacity-90'}`}>
              <div className="flex items-center justify-between mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                    {currentUser.isAdmin ? (
                        <><LockOpenIcon className="h-3 w-3 text-green-500" /> Acesso Administrativo (Desbloqueado)</>
                    ) : (
                        <><LockClosedIcon className="h-3 w-3" /> Dados Sensíveis (Protegidos)</>
                    )}
                 </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={email} 
                        onChange={e => setEmail(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>
              </div>
           </div>

           <button 
             type="submit" 
             disabled={isSaving || isUploading} 
             className="w-full py-6 bg-brand hover:bg-brandHover text-white rounded-[2.2rem] font-black uppercase text-sm tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
           >
             {isSaving ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
             ) : (
               <><CheckIcon className="h-6 w-6 stroke-[3]" /> Salvar Alterações</>
             )}
           </button>
        </form>
      </div>
    );
  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil & Senha', desc: 'Nome, bio, foto e segurança', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Cores e Modo Dark', icon: PaintBrushIcon, onClick: () => setView('appearance') }
      ]
    },
    {
      title: 'Sistema & Segurança',
      items: [
        { label: 'Diagnóstico & API', desc: 'Verificar conexões e chaves', icon: ServerIcon, onClick: () => setView('system') },
        { label: 'CyBer Card Pro', desc: 'Conta virtual (Beta)', icon: CreditCardIcon, onClick: () => setView('payments') },
        { label: 'Ajuda e Suporte', desc: 'Abrir tickets e resolver problemas', icon: LifebuoyIcon, onClick: () => onNavigate('support') },
        { label: 'Sair da Conta', desc: 'Desconectar dispositivo', icon: ArrowRightOnRectangleIcon, onClick: onLogout }
      ]
    }
  ];

  return (
    <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-4xl animate-fade-in">
      <div className="flex items-center gap-6 mb-10">
        <button onClick={() => onNavigate('profile')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
        <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tighter">Ajustes</h2>
      </div>

      <div className="space-y-10">
        {sections.map(section => (
          <div key={section.title}>
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">{section.title}</h3>
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-white/10 overflow-hidden">
              {section.items.map((item, idx) => (
                <div 
                  key={item.label} 
                  onClick={item.onClick}
                  className={`p-6 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-white/5 transition-colors cursor-pointer ${idx !== section.items.length - 1 ? 'border-b border-gray-50 dark:border-white/10' : ''}`}
                >
                  <div className="flex items-center gap-5">
                    <div className="p-3 rounded-2xl bg-brand/10 text-brand">
                      <item.icon className="h-6 w-6" />
                    </div>
                    <div>
                      <p className="font-black text-sm dark:text-white">{item.label}</p>
                      <p className="text-xs text-gray-400 font-bold">{item.desc}</p>
                    </div>
                  </div>
                  <ChevronDownIcon className="h-5 w-5 text-gray-300 -rotate-90" />
                </div>
              ))}
            </div>
          </div>
        ))}

        {/* ÁREA DE PERIGO PERSISTENTE */}
        <div className="mt-10 px-4 bg-red-50 dark:bg-red-900/10 p-8 rounded-[3rem] border border-red-100 dark:border-red-900/20">
           <div className="flex items-center gap-3 mb-4">
              <ExclamationTriangleIcon className="h-6 w-6 text-red-600" />
              <h3 className="text-sm font-black text-red-700 dark:text-red-400 uppercase tracking-widest">Área de Perigo</h3>
           </div>
           <p className="text-xs text-red-600/80 dark:text-red-400/80 font-medium mb-6 leading-relaxed">
              A exclusão da conta é permanente. Todos os seus dados, postagens, loja e saldo serão removidos dos nossos servidores.
           </p>

           <div className="flex flex-col gap-6">
               <button 
                 onClick={() => setShowDeleteConfirm(true)} 
                 disabled={isSaving}
                 className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-red-200 dark:shadow-none active:scale-95 transition-all flex items-center justify-center gap-2"
               >
                  {isSaving ? (
                      <>Processando Exclusão...</>
                  ) : (
                      <><TrashIcon className="h-4 w-4" /> Excluir Minha Conta</>
                  )}
               </button>

               <div 
                 onClick={handleVersionClick}
                 className="text-center opacity-30 hover:opacity-100 transition-opacity cursor-pointer select-none"
               >
                  <p className="text-[9px] font-black uppercase tracking-[0.3em] text-gray-400">
                     CyBerPhone Pro v1.3.3 (Stable)
                     {currentUser.isAdmin && <span className="text-red-500 ml-2">ROOT ACCESS</span>}
                  </p>
               </div>
           </div>
        </div>
      </div>

      <ConfirmationModal
        isOpen={showDeleteConfirm}
        onClose={() => setShowDeleteConfirm(false)}
        onConfirm={handleConfirmDelete}
        title="Excluir Conta?"
        message="Esta ação é irreversível. Todos os seus dados, saldo e conteúdo serão apagados permanentemente."
        confirmText="Sim, Apagar Tudo"
        type="danger"
        loading={isSaving}
      />
    </div>
  );
};

export default SettingsPage;

import { initializeApp, getApps, getApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";

// Configuração lendo estritamente das variáveis de ambiente (injetadas pelo Vite)
// Isso impede que a chave fique exposta no código fonte público
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

// Verifica se a chave de API está presente para evitar erros de inicialização
export const isFirebaseConfigured = !!(process.env.FIREBASE_API_KEY && process.env.FIREBASE_API_KEY.length > 0);

// Padrão Singleton para evitar inicializar múltiplas vezes no hot-reload
let app;
if (isFirebaseConfigured) {
  try {
    app = !getApps().length ? initializeApp(firebaseConfig) : getApp();
  } catch (error) {
    console.error("Erro ao inicializar Firebase:", error);
  }
}

// Exporta os serviços apenas se o app foi inicializado, caso contrário exporta undefined/mock
export const auth = app ? getAuth(app) : null as any;
export const db = app ? getFirestore(app) : null as any;
export const storage = app ? getStorage(app) : null as any;

import React, { useState, useRef, useEffect } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, saveCurrentUser } from '../services/storageService';
import { isFirebaseConfigured } from '../services/firebaseClient';
import { 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  ExclamationTriangleIcon,
  LifebuoyIcon,
  CpuChipIcon,
  SignalIcon,
  ServerIcon
} from '@heroicons/react/24/outline';
import ConfirmationModal from './ConfirmationModal';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance' | 'system'>('main');

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Hidden Admin Access
  const [devClicks, setDevClicks] = useState(0);
  const ADMIN_EMAIL = 'admin@cyber.com';

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // System Diagnostics
  const hasGeminiKey = !!process.env.API_KEY;
  const hasFirebaseKey = isFirebaseConfigured;

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      // Persistência Imediata
      await updateUser(updatedUser);
      await refreshUser(); // Atualiza o estado global no App.tsx

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleConfirmDelete = async () => {
    try {
        setIsSaving(true); // Bloqueia UI
        await deleteUser(currentUser.id);
        // Limpa sessão local explicitamente
        saveCurrentUser(null);
        setShowDeleteConfirm(false);
        onDeleteAccount(); // Chama o logout/reset do pai
    } catch (error) {
        console.error("Erro ao deletar conta:", error);
        alert("Não foi possível excluir a conta no momento. Tente novamente.");
        setIsSaving(false);
        setShowDeleteConfirm(false);
    }
  };

  const handleVersionClick = async () => {
    const newCount = devClicks + 1;
    setDevClicks(newCount);

    if (newCount === 7) {
        if (currentUser.email.toLowerCase() === ADMIN_EMAIL) {
            const newStatus = !currentUser.isAdmin;
            await updateUser({ ...currentUser, isAdmin: newStatus });
            refreshUser();
            alert(`SISTEMA ROOT: Privilégios de Superusuário ${newStatus ? 'ATIVADOS' : 'DESATIVADOS'}.`);
        } else {
            alert(`⛔ ACESSO NEGADO\n\nConta não autorizada para Root.`);
        }
        setDevClicks(0);
    }
  };

  if (view === 'appearance') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">Estilo</h2>
          </div>

          <div className="space-y-10">
            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Tema de Cores</p>
                <div className="grid grid-cols-2 gap-4">
                    {THEMES.map(theme => (
                        <button 
                          key={theme.id}
                          onClick={() => onThemeChange(theme.id)}
                          className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${appTheme === theme.id ? 'border-brand bg-brand/5 shadow-xl' : 'border-gray-50 dark:border-white/5 hover:border-gray-200'}`}
                        >
                           <div className={`w-14 h-14 rounded-2xl ${theme.color} shadow-lg flex items-center justify-center`}>
                              {appTheme === theme.id && <CheckIcon className="h-7 w-7 text-white" />}
                           </div>
                           <span className={`text-xs font-black uppercase ${appTheme === theme.id ? 'text-brand' : 'text-gray-400'}`}>{theme.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 flex items-center justify-between">
                <div>
                    <p className="font-black text-sm dark:text-white uppercase tracking-tighter">Modo Escuro</p>
                    <p className="text-xs text-gray-400 font-bold">Inverter cores do sistema</p>
                </div>
                <button onClick={toggleTheme} className={`w-14 h-7 rounded-full transition-all relative ${darkMode ? 'bg-brand' : 'bg-gray-200'}`}>
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${darkMode ? 'right-1' : 'left-1'}`}></div>
                </button>
            </div>
          </div>
        </div>
    );
  }

  if (view === 'system') {
      return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
            <div className="flex items-center gap-6 mb-10">
                <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
                <h2 className="text-4xl font-black dark:text-white tracking-tighter">Sistema</h2>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-white/10 space-y-6">
                <h3 className="text-lg font-black dark:text-white uppercase tracking-tighter flex items-center gap-2">
                    <ServerIcon className="h-6 w-6 text-brand" /> Status das Conexões
                </h3>

                <div className="space-y-4">
                    <div className={`p-4 rounded-2xl border-2 flex items-center justify-between ${hasFirebaseKey ? 'border-green-500/20 bg-green-50 dark:bg-green-900/10' : 'border-red-500/20 bg-red-50 dark:bg-red-900/10'}`}>
                        <div className="flex items-center gap-3">
                            <SignalIcon className={`h-6 w-6 ${hasFirebaseKey ? 'text-green-600' : 'text-red-500'}`} />
                            <div>
                                <p className="font-black text-sm dark:text-white uppercase">Banco de Dados (Firebase)</p>
                                <p className="text-xs text-gray-500 font-medium">{hasFirebaseKey ? 'Conectado e Seguro' : 'Chave API não encontrada'}</p>
                            </div>
                        </div>
                        <div className={`w-3 h-3 rounded-full ${hasFirebaseKey ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></div>
                    </div>

                    <div className={`p-4 rounded-2xl border-2 flex items-center justify-between ${hasGeminiKey ? 'border-blue-500/20 bg-blue-50 dark:bg-blue-900/10' : 'border-orange-500/20 bg-orange-50 dark:bg-orange-900/10'}`}>
                        <div className="flex items-center gap-3">
                            <CpuChipIcon className={`h-6 w-6 ${hasGeminiKey ? 'text-blue-600' : 'text-orange-500'}`} />
                            <div>
                                <p className="font-black text-sm dark:text-white uppercase">Inteligência Artificial (Gemini)</p>
                                <p className="text-xs text-gray-500 font-medium">{hasGeminiKey ? 'Operacional' : 'Modo Offline (Sem Chave)'}</p>
                            </div>
                        </div>
                        <div className={`w-3 h-3 rounded-full ${hasGeminiKey ? 'bg-blue-500 animate-pulse' : 'bg-orange-500'}`}></div>
                    </div>
                </div>

                <div className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-xs text-gray-500 font-mono border border-dashed border-gray-200 dark:border-white/10">
                    <p>APP_VERSION: 1.3.3-stable</p>
                    <p>ENV: {import.meta.env.MODE || 'production'}</p>
                    <p>BUILD_TIME: {new Date().toLocaleDateString()}</p>
                </div>
            </div>
        </div>
      );
  }

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-3xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-4xl font-black dark:text-white tracking-tighter">Dados de Inscrição</h2>
        </div>

        {saveSuccess && (
          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-500/30 rounded-2xl flex items-center gap-3 animate-fade-in">
             <CheckIcon className="h-5 w-5 text-green-600" />
             <p className="text-xs font-black text-green-700 dark:text-green-400 uppercase tracking-widest">Perfil atualizado!</p>
          </div>
        )}

        <form onSubmit={handleSaveProfile} className="space-y-8">
           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Identidade Visual</p>
              <div className="flex flex-col items-center gap-6">
                 <div 
                   onClick={() => fileInputRef.current?.click()} 
                   className="relative group cursor-pointer"
                 >
                    <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-white dark:border-darkcard shadow-2xl transition-transform group-hover:scale-105 relative">
                       <img src={profilePicture || 'https://via.placeholder.com/150'} className="w-full h-full object-cover" alt="Profile" />
                       {isUploading && (
                         <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                           <div className="w-8 h-8 border-4 border-white border-t-transparent animate-spin rounded-full"></div>
                         </div>
                       )}
                       <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                          <CameraIcon className="h-10 w-10 text-white" />
                       </div>
                    </div>
                    <div className="absolute -bottom-2 -right-2 bg-brand text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                       <PaintBrushIcon className="h-4 w-4" />
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileChange} 
                    />
                 </div>
                 <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Clique na foto para alterar</p>
              </div>
           </div>

           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Dados Pessoais</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Nome</label>
                    <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Sobrenome</label>
                    <input type="text" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Data de Nascimento</label>
                    <div className="relative">
                       <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                       <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Cargo ou Especialidade</label>
                      <input type="text" value={credentials} onChange={e => setCredentials(e.target.value)} placeholder="Ex: Professor" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                   </div>
                 )}

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Biografia</label>
                    <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Conte um pouco sobre você..." className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] dark:text-white outline-none border-2 border-transparent focus:border-brand font-medium h-32 resize-none" />
                 </div>
              </div>
           </div>

           <div className={`bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border transition-all ${currentUser.isAdmin ? 'border-green-500/20 shadow-green-500/10' : 'border-gray-200 dark:border-white/10 opacity-90'}`}>
              <div className="flex items-center justify-between mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                    {currentUser.isAdmin ? (
                        <><LockOpenIcon className="h-3 w-3 text-green-500" /> Acesso Administrativo (Desbloqueado)</>
                    ) : (
                        <><LockClosedIcon className="h-3 w-3" /> Dados Sensíveis (Protegidos)</>
                    )}
                 </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={email} 
                        onChange={e => setEmail(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>
              </div>
           </div>

           <button 
             type="submit" 
             disabled={isSaving || isUploading} 
             className="w-full py-6 bg-brand hover:bg-brandHover text-white rounded-[2.2rem] font-black uppercase text-sm tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
           >
             {isSaving ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
             ) : (
               <><CheckIcon className="h-6 w-6 stroke-[3]" /> Salvar Alterações</>
             )}
           </button>
        </form>
      </div>
    );
  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil & Senha', desc: 'Nome, bio, foto e segurança', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Cores e Modo Dark', icon: PaintBrushIcon, onClick: () => setView('appearance') }
      ]
    },
    {
      title: 'Sistema & Segurança',
      items: [
        { label: 'Diagnóstico & API', desc: 'Verificar conexões e chaves', icon: ServerIcon, onClick: () => setView('system') },
        { label: 'CyBer Card Pro', desc: 'Conta virtual (Beta)', icon: CreditCardIcon, onClick: () => setView('payments') },
        { label: 'Ajuda e Suporte', desc: 'Abrir tickets e resolver problemas', icon: LifebuoyIcon, onClick: () => onNavigate('support') },
        { label: 'Sair da Conta', desc: 'Desconectar dispositivo', icon: ArrowRightOnRectangleIcon, onClick: onLogout }
      ]
    }
  ];

  return (
    <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-4xl animate-fade-in">
      <div className="flex items-center gap-6 mb-10">
        <button onClick={() => onNavigate('profile')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
        <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tighter">Ajustes</h2>
      </div>

      <div className="space-y-10">
        {sections.map(section => (
          <div key={section.title}>
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">{section.title}</h3>
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-white/10 overflow-hidden">
              {section.items.map((item, idx) => (
                <div 
                  key={item.label} 
                  onClick={item.onClick}
                  className={`p-6 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-white/5 transition-colors cursor-pointer ${idx !== section.items.length - 1 ? 'border-b border-gray-50 dark:border-white/10' : ''}`}
                >
                  <div className="flex items-center gap-5">
                    <div className="p-3 rounded-2xl bg-brand/10 text-brand">
                      <item.icon className="h-6 w-6" />
                    </div>
                    <div>
                      <p className="font-black text-sm dark:text-white">{item.label}</p>
                      <p className="text-xs text-gray-400 font-bold">{item.desc}</p>
                    </div>
                  </div>
                  <ChevronDownIcon className="h-5 w-5 text-gray-300 -rotate-90" />
                </div>
              ))}
            </div>
          </div>
        ))}

        {/* ÁREA DE PERIGO PERSISTENTE */}
        <div className="mt-10 px-4 bg-red-50 dark:bg-red-900/10 p-8 rounded-[3rem] border border-red-100 dark:border-red-900/20">
           <div className="flex items-center gap-3 mb-4">
              <ExclamationTriangleIcon className="h-6 w-6 text-red-600" />
              <h3 className="text-sm font-black text-red-700 dark:text-red-400 uppercase tracking-widest">Área de Perigo</h3>
           </div>
           <p className="text-xs text-red-600/80 dark:text-red-400/80 font-medium mb-6 leading-relaxed">
              A exclusão da conta é permanente. Todos os seus dados, postagens, loja e saldo serão removidos dos nossos servidores.
           </p>

           <div className="flex flex-col gap-6">
               <button 
                 onClick={() => setShowDeleteConfirm(true)} 
                 disabled={isSaving}
                 className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-red-200 dark:shadow-none active:scale-95 transition-all flex items-center justify-center gap-2"
               >
                  {isSaving ? (
                      <>Processando Exclusão...</>
                  ) : (
                      <><TrashIcon className="h-4 w-4" /> Excluir Minha Conta</>
                  )}
               </button>

               <div 
                 onClick={handleVersionClick}
                 className="text-center opacity-30 hover:opacity-100 transition-opacity cursor-pointer select-none"
               >
                  <p className="text-[9px] font-black uppercase tracking-[0.3em] text-gray-400">
                     CyBerPhone Pro v1.3.3 (Stable)
                     {currentUser.isAdmin && <span className="text-red-500 ml-2">ROOT ACCESS</span>}
                  </p>
               </div>
           </div>
        </div>
      </div>

      <ConfirmationModal
        isOpen={showDeleteConfirm}
        onClose={() => setShowDeleteConfirm(false)}
        onConfirm={handleConfirmDelete}
        title="Excluir Conta?"
        message="Esta ação é irreversível. Todos os seus dados, saldo e conteúdo serão apagados permanentemente."
        confirmText="Sim, Apagar Tudo"
        type="danger"
        loading={isSaving}
      />
    </div>
  );
};

export default SettingsPage;

import React, { useState, useRef, useEffect } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, saveCurrentUser } from '../services/storageService';
import { isFirebaseConfigured } from '../services/firebaseClient';
import { 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  ExclamationTriangleIcon,
  LifebuoyIcon,
  CpuChipIcon,
  SignalIcon,
  ServerIcon
} from '@heroicons/react/24/outline';
import ConfirmationModal from './ConfirmationModal';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance' | 'system'>('main');

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Hidden Admin Access
  const [devClicks, setDevClicks] = useState(0);
  const ADMIN_EMAIL = 'admin@cyber.com';

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // System Diagnostics
  const hasGeminiKey = !!process.env.API_KEY;
  const hasFirebaseKey = isFirebaseConfigured;

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      // Persistência Imediata
      await updateUser(updatedUser);
      await refreshUser(); // Atualiza o estado global no App.tsx

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleConfirmDelete = async () => {
    try {
        setIsSaving(true); // Bloqueia UI
        await deleteUser(currentUser.id);
        // Limpa sessão local explicitamente
        saveCurrentUser(null);
        setShowDeleteConfirm(false);
        onDeleteAccount(); // Chama o logout/reset do pai
    } catch (error) {
        console.error("Erro ao deletar conta:", error);
        alert("Não foi possível excluir a conta no momento. Tente novamente.");
        setIsSaving(false);
        setShowDeleteConfirm(false);
    }
  };

  const handleVersionClick = async () => {
    const newCount = devClicks + 1;
    setDevClicks(newCount);

    if (newCount === 7) {
        if (currentUser.email.toLowerCase() === ADMIN_EMAIL) {
            const newStatus = !currentUser.isAdmin;
            await updateUser({ ...currentUser, isAdmin: newStatus });
            refreshUser();
            alert(`SISTEMA ROOT: Privilégios de Superusuário ${newStatus ? 'ATIVADOS' : 'DESATIVADOS'}.`);
        } else {
            alert(`⛔ ACESSO NEGADO\n\nConta não autorizada para Root.`);
        }
        setDevClicks(0);
    }
  };

  if (view === 'appearance') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">Estilo</h2>
          </div>

          <div className="space-y-10">
            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Tema de Cores</p>
                <div className="grid grid-cols-2 gap-4">
                    {THEMES.map(theme => (
                        <button 
                          key={theme.id}
                          onClick={() => onThemeChange(theme.id)}
                          className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${appTheme === theme.id ? 'border-brand bg-brand/5 shadow-xl' : 'border-gray-50 dark:border-white/5 hover:border-gray-200'}`}
                        >
                           <div className={`w-14 h-14 rounded-2xl ${theme.color} shadow-lg flex items-center justify-center`}>
                              {appTheme === theme.id && <CheckIcon className="h-7 w-7 text-white" />}
                           </div>
                           <span className={`text-xs font-black uppercase ${appTheme === theme.id ? 'text-brand' : 'text-gray-400'}`}>{theme.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 flex items-center justify-between">
                <div>
                    <p className="font-black text-sm dark:text-white uppercase tracking-tighter">Modo Escuro</p>
                    <p className="text-xs text-gray-400 font-bold">Inverter cores do sistema</p>
                </div>
                <button onClick={toggleTheme} className={`w-14 h-7 rounded-full transition-all relative ${darkMode ? 'bg-brand' : 'bg-gray-200'}`}>
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${darkMode ? 'right-1' : 'left-1'}`}></div>
                </button>
            </div>
          </div>
        </div>
    );
  }

  if (view === 'system') {
      return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
            <div className="flex items-center gap-6 mb-10">
                <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
                <h2 className="text-4xl font-black dark:text-white tracking-tighter">Sistema</h2>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-white/10 space-y-6">
                <h3 className="text-lg font-black dark:text-white uppercase tracking-tighter flex items-center gap-2">
                    <ServerIcon className="h-6 w-6 text-brand" /> Status das Conexões
                </h3>

                <div className="space-y-4">
                    <div className={`p-4 rounded-2xl border-2 flex items-center justify-between ${hasFirebaseKey ? 'border-green-500/20 bg-green-50 dark:bg-green-900/10' : 'border-red-500/20 bg-red-50 dark:bg-red-900/10'}`}>
                        <div className="flex items-center gap-3">
                            <SignalIcon className={`h-6 w-6 ${hasFirebaseKey ? 'text-green-600' : 'text-red-500'}`} />
                            <div>
                                <p className="font-black text-sm dark:text-white uppercase">Banco de Dados (Firebase)</p>
                                <p className="text-xs text-gray-500 font-medium">{hasFirebaseKey ? 'Conectado e Seguro' : 'Chave API não encontrada'}</p>
                            </div>
                        </div>
                        <div className={`w-3 h-3 rounded-full ${hasFirebaseKey ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></div>
                    </div>

                    <div className={`p-4 rounded-2xl border-2 flex items-center justify-between ${hasGeminiKey ? 'border-blue-500/20 bg-blue-50 dark:bg-blue-900/10' : 'border-orange-500/20 bg-orange-50 dark:bg-orange-900/10'}`}>
                        <div className="flex items-center gap-3">
                            <CpuChipIcon className={`h-6 w-6 ${hasGeminiKey ? 'text-blue-600' : 'text-orange-500'}`} />
                            <div>
                                <p className="font-black text-sm dark:text-white uppercase">Inteligência Artificial (Gemini)</p>
                                <p className="text-xs text-gray-500 font-medium">{hasGeminiKey ? 'Operacional' : 'Modo Offline (Sem Chave)'}</p>
                            </div>
                        </div>
                        <div className={`w-3 h-3 rounded-full ${hasGeminiKey ? 'bg-blue-500 animate-pulse' : 'bg-orange-500'}`}></div>
                    </div>
                </div>

                <div className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-xs text-gray-500 font-mono border border-dashed border-gray-200 dark:border-white/10">
                    <p>APP_VERSION: 1.3.3-stable</p>
                    <p>ENV: {(import.meta as any).env.MODE || 'production'}</p>
                    <p>BUILD_TIME: {new Date().toLocaleDateString()}</p>
                </div>
            </div>
        </div>
      );
  }

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-3xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
