        onConfirm={handleConfirmDelete}
        title="Excluir Conta?"
        message="Esta ação é irreversível. Todos os seus dados, saldo e conteúdo serão apagados permanentemente."
        confirmText="Sim, Apagar Tudo"
        type="danger"
        loading={isSaving}
      />
    </div>
  );
};

export default SettingsPage;

