export const getEvents = (): CyberEvent[] => {
  const eventsJson = localStorage.getItem(EVENTS_KEY);
  return eventsJson ? JSON.parse(eventsJson) : [];
};

export const createEvent = (evt: CyberEvent) => {
  const evts = getEvents();
  localStorage.setItem(EVENTS_KEY, JSON.stringify([evt, ...evts]));
};

export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const evt = evts.find(e => e.id === eId);
  if (evt) {
    if (evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
    else evt.attendees.push(uId);
    localStorage.setItem(EVENTS_KEY, JSON.stringify(evts));
  }
};

export const indicatePostToUser = (pId: string, from: string, to: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(to)) return false;
    post.indicatedUserIds.push(to);
    updatePost(post);
    createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: post.id, timestamp: Date.now() });
    return true;
  }
  return false;
};

export const getGlobalSettings = () => {
    const settings = localStorage.getItem(SETTINGS_KEY);
    return settings ? JSON.parse(settings) : { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false };
};

export const updateGlobalSettings = (settings: GlobalSettings) => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
};

export const boostPost = (pId: string, uId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && updateUserBalance(uId, -budget)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 86400000);
    updatePost(post);
    return true;
  }
  return false;
};

export const saveAffiliateLink = (uId: string, pId: string, link: string) => {
  const links = JSON.parse(localStorage.getItem('cyber_affiliate_links') || '[]');
  links.push({ uId, pId, link, timestamp: Date.now() });
  localStorage.setItem('cyber_affiliate_links', JSON.stringify(links));
};

export const getAffiliateLinks = async (userId: string) => {
    const links = JSON.parse(localStorage.getItem('cyber_affiliate_links') || '[]');
    const products = getProducts();
    return links.filter((l: any) => l.uId === userId).map((l: any) => {
        const p = products.find(prod => prod.id === l.pId);
        return {
            id: l.link, 
            link: l.link,
            timestamp: l.timestamp,
            productName: p?.name || 'Unknown',
            productImage: p?.imageUrls?.[0] || '',
            commissionRate: p?.affiliateCommissionRate || 0
        };
    });
};

export const getReports = (): ContentReport[] => {
    const json = localStorage.getItem(REPORTS_KEY);
    return json ? JSON.parse(json) : [];
};

export const saveReports = (reports: ContentReport[]) => {
    localStorage.setItem(REPORTS_KEY, JSON.stringify(reports));
};

export const createReport = (report: Omit<ContentReport, 'id' | 'timestamp' | 'status'>) => {
    const reports = getReports();
    const newReport: ContentReport = {
        ...report,
        id: generateUUID(),
        timestamp: Date.now(),
        status: 'OPEN'
    };
    saveReports([newReport, ...reports]);
};

export const getTransactions = (): Transaction[] => {
    const json = localStorage.getItem(TRANSACTIONS_KEY);
    return json ? JSON.parse(json) : [];
};

export const saveTransactions = (txs: Transaction[]) => {
    localStorage.setItem(TRANSACTIONS_KEY, JSON.stringify(txs));
};

export const createTransaction = (tx: Transaction) => {
    const txs = getTransactions();
    saveTransactions([tx, ...txs]);
};

export const processAdInvestment = async (userId: string, amount: number, description: string): Promise<boolean> => {
    if(updateUserBalance(userId, -amount)) {
        createTransaction({
            id: generateUUID(),
            userId,
            type: TransactionType.PURCHASE,
            amount,
            description: `Ads: ${description}`,
            timestamp: Date.now(),
            status: 'COMPLETED'
        });
        return true;
    }
    return false;
};

export const processDonation = async (fromId: string, toId: string, amount: number, message: string): Promise<boolean> => {
    if(updateUserBalance(fromId, -amount)) {
        updateUserBalance(toId, amount);
        createTransaction({ id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Donation to user ${toId}`, timestamp: Date.now(), status: 'COMPLETED' });
        createTransaction({ id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Donation from user ${fromId}`, timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
    return false;
};

export const handleWalletTransaction = async (userId: string, amount: number, type: 'deposit' | 'withdraw'): Promise<boolean> => {
    if (type === 'withdraw') {
        if (updateUserBalance(userId, -amount)) {
            createTransaction({ id: generateUUID(), userId, type: TransactionType.WITHDRAWAL, amount, description: 'Withdrawal', timestamp: Date.now(), status: 'PENDING' });
            return true;
        }
        return false;
    } else {
        updateUserBalance(userId, amount);
        createTransaction({ id: generateUUID(), userId, type: TransactionType.DEPOSIT, amount, description: 'Deposit', timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
};

export const getPlatformRevenue = async (): Promise<number> => {
    return getTransactions().reduce((acc, tx) => (tx.type === TransactionType.CHAT_FEE || tx.type === TransactionType.BOOST) ? acc + tx.amount : acc, 0);
};

export const subscribeToLivePost = (postId: string, callback: (post: Post | null) => void) => {
    return () => {}; 
};

export const sendLiveMessage = async (postId: string, comment: Comment) => {
    const posts = getPosts();
    const post = posts.find(p => p.id === postId);
    if (post) {
        if (!post.liveChat) post.liveChat = [];
        post.liveChat.push(comment);
        updatePost(post);
    }
};

export const manageLiveViewers = (postId: string, action: 'join' | 'leave') => {
    const posts = getPosts();
    const post = posts.find(p => p.id === postId);
    if (post) {
        post.liveViewerCount = (post.liveViewerCount || 0) + (action === 'join' ? 1 : -1);
        updatePost(post);
    }
};

export const pulseLiveHeart = (postId: string) => {
    const posts = getPosts();
    const post = posts.find(p => p.id === postId);
    if (post) {
        post.liveHeartCount = (post.liveHeartCount || 0) + 1;
        updatePost(post);
    }
};

export const getAppTheme = (): GroupTheme => {
    return (localStorage.getItem('cyber_app_theme') as GroupTheme) || 'blue';
};

export const saveAppTheme = (theme: GroupTheme) => {
    localStorage.setItem('cyber_app_theme', theme);
};

export const updateUserStatus = (userId: string, isOnline: boolean) => {
    const users = getUsers();
    const user = users.find(u => u.id === userId);
    if (user) {
        user.isOnline = isOnline;
        user.lastSeen = Date.now();
        saveUsers(users);
    }
};

export const updateGroupTheme = async (chatId: string, theme: GroupTheme) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        chat.theme = theme;
        saveChats(chats);
    }
};

export const leaveGroup = async (chatId: string, userId: string) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        chat.participants = chat.participants.filter(id => id !== userId);
        saveChats(chats);
    }
};

export const deleteChat = async (chatId: string) => {
    const chats = getChats().filter(c => c.id !== chatId);
    saveChats(chats);
};

export const createGroup = async (name: string, members: string[], adminId: string, description?: string, theme?: GroupTheme, imageFile?: File, isPublic?: boolean) => {
    const chats = getChats();
    let imageUrl = '';
    if (imageFile) imageUrl = await uploadFile(imageFile, 'groups');

    const newGroup: ChatConversation = {
        id: generateUUID(),
        type: ChatType.GROUP,
        participants: [...members, adminId],
        messages: [],
        groupName: name,
        groupImage: imageUrl,
        adminId,
        isPublic,
        description,
        theme
    };
    saveChats([newGroup, ...chats]);
};

export const joinGroup = async (groupId: string, userId: string) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === groupId);
    if (chat && !chat.participants.includes(userId)) {
        chat.participants.push(userId);
        saveChats(chats);
    }
};

export const getSystemLogs = (): SystemLog[] => []; 

export const adminUpdateUser = async (user: User) => updateUser(user);
export const adminDeletePost = async (postId: string) => deletePost(postId);
export const adminDeleteProduct = async (productId: string) => {
    const products = getProducts().filter(p => p.id !== productId);
    saveProducts(products);
};
export const adminProcessReport = async (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
    const reports = getReports();
    const report = reports.find(r => r.id === reportId);
    if(report) {
        report.status = status;
        saveReports(reports);
    }
};

export const createStore = async (store: Store) => {
    const stores = getStores();
    saveStores([...stores, store]);
};

export const fulfillDropshippingOrder = async (saleId: string, userId: string, cost: number) => {
    if (updateUserBalance(userId, -cost)) {
        updateSaleStatus(saleId, OrderStatus.PROCESSING_SUPPLIER);
        return true;
    }
    return false;
};

export const updateSaleTracking = async (saleId: string, trackingCode: string, supplierOrderId?: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(s => s.id === saleId);
    if (sale) {
        sale.trackingCode = trackingCode;
        if(supplierOrderId) sale.supplierOrderId = supplierOrderId;
        saveAffiliateSales(sales);
    }
};

export const processUserUpgrade = async (userId: string, user: User, docFile: File, credentials: string) => {
    if (!updateUserBalance(userId, -29.90)) throw new Error("Saldo insuficiente");
    const docUrl = await uploadFile(docFile, 'docs');
    const updatedUser = { 
        ...user, 
        userType: UserType.CREATOR, 
        credentials, 
        verificationFileUrl: docUrl 
    };
    updateUser(updatedUser);
    const stores = getStores();
    if (!stores.find(s => s.professorId === userId)) {
        const newStore: Store = {
            id: generateUUID(),
            professorId: userId,
            name: `${user.firstName}'s Store`,
            description: 'Welcome',
            productIds: []
        };
        saveStores([...stores, newStore]);
        updatedUser.storeId = newStore.id;
        updateUser(updatedUser);
    }
};

export const getOptimizedVideoUrl = (url: string) => url; 

export const updateUserPassword = async (password: string) => {
    console.log("Password updated (mock)");
};

export const deleteUser = async (userId: string) => {
    let users = getUsers();
    users = users.filter(u => u.id !== userId);
    saveUsers(users);

    // Also remove from local session
    if (localStorage.getItem(CURRENT_USER_KEY) === userId) {
        localStorage.removeItem(CURRENT_USER_KEY);
    }
};

// Support functions
export const getSupportTickets = async (userId?: string): Promise<SupportTicket[]> => {
    const json = localStorage.getItem(SUPPORT_TICKETS_KEY);
    const tickets = json ? JSON.parse(json) as SupportTicket[] : [];
    if (userId) return tickets.filter(t => t.userId === userId);
    return tickets;
};

export const saveSupportTickets = (tickets: SupportTicket[]) => {
    localStorage.setItem(SUPPORT_TICKETS_KEY, JSON.stringify(tickets));
};

export const createSupportTicket = async (ticketData: Pick<SupportTicket, 'userId' | 'subject' | 'category'>, initialMessage: string, attachmentUrl?: string, attachmentType?: 'image' | 'video') => {
    const tickets = await getSupportTickets();
    const newTicket: SupportTicket = {
        id: generateUUID(),
        userId: ticketData.userId,
        subject: ticketData.subject,
        category: ticketData.category,
        status: 'OPEN',
        createdAt: Date.now(),
        updatedAt: Date.now(),
        messages: [
            {
                id: generateUUID(),
                senderId: ticketData.userId,
                text: initialMessage,
                timestamp: Date.now(),
                attachmentUrl,
                attachmentType
            }
        ]
    };
    saveSupportTickets([newTicket, ...tickets]);
    return newTicket;
};

export const addSupportMessage = async (ticketId: string, messageData: { senderId: string, text: string, attachmentUrl?: string, attachmentType?: 'image' | 'video' }) => {
    const tickets = await getSupportTickets();
    const ticket = tickets.find(t => t.id === ticketId);
    if (ticket) {
        const newMessage: SupportMessage = {
            id: generateUUID(),
            senderId: messageData.senderId,
            text: messageData.text,
            timestamp: Date.now(),
            attachmentUrl: messageData.attachmentUrl,
            attachmentType: messageData.attachmentType
        };
        ticket.messages.push(newMessage);
        ticket.updatedAt = Date.now();
        saveSupportTickets(tickets);
    }
};

import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig(({ mode }) => {
  // Carrega variáveis de ambiente
  const env = loadEnv(mode, '.', '');

  return {
    plugins: [react()],
    define: {
      // Mantém compatibilidade para libs que usam process.env (como Google GenAI SDK)
      // Mas NÃO sobrescreve os VITE_ para deixar o import.meta.env funcionar nativamente
      'process.env.API_KEY': JSON.stringify(env.API_KEY || env.VITE_API_KEY),
      // Polyfill simples para evitar crash de 'process is not defined'
      'process.env': {},
    },
    build: {
      outDir: 'dist',
      sourcemap: true,
      commonjsOptions: {
        transformMixedEsModules: true,
      },
    },
    server: {
      host: true
    }
  };
});

/// <reference types="vite/client" />
import { initializeApp, getApps, getApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";

// Usando import.meta.env para compatibilidade nativa com Vite e Vercel
const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID
};

// Verifica se a chave de API está presente
export const isFirebaseConfigured = !!(
  firebaseConfig.apiKey && 
  firebaseConfig.apiKey.length > 0
);

let app;
let auth;
let db;
let storage;

if (isFirebaseConfigured) {
  try {
    // Inicializa apenas se não existir instância
    app = !getApps().length ? initializeApp(firebaseConfig) : getApp();
    auth = getAuth(app);
    db = getFirestore(app);
    storage = getStorage(app);
    console.log("Firebase conectado com sucesso:", firebaseConfig.projectId);
  } catch (error) {
    console.error("Erro ao inicializar Firebase:", error);
  }
} else {
  console.warn("Firebase não configurado. Verifique as variáveis de ambiente VITE_FIREBASE_*");
}

export { auth, db, storage };
export default app;

