    if (chat) {
        if (hardDelete) {
             chat.messages = chat.messages.filter(m => m.id !== messageId);
        } else {
            const msg = chat.messages.find(m => m.id === messageId);
            if (msg) {
                msg.isDeleted = true;
                msg.text = undefined;
                msg.imageUrl = undefined;
                msg.fileUrl = undefined;
                msg.fileType = undefined;
                msg.fileName = undefined;
            }
        }
        saveChats(chats);
    }
};

