export const addProductRating = (saleId: string, rating: number, comment: string) => {
  const sales = getAffiliateSales();
  const products = getProducts();
  const sale = sales.find(s => s.id === saleId);
  if (!sale || sale.isRated) return false;

  const product = products.find(p => p.id === sale.productId);
  if (!product) return false;

  sale.isRated = true;
  const newRating: ProductRating = { id: `rating-${Date.now()}`, saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() };
  product.ratings.push(newRating);
  product.ratingCount = product.ratings.length;
  product.averageRating = product.ratings.reduce((sum, r) => sum + r.rating, 0) / product.ratingCount;

  saveAffiliateSales(sales);
  saveProducts(products);
  return true;
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  let users = getUsers();
  const allSales = getAffiliateSales();

  for (const item of cartItems) {
    const product = findProductById(item.productId);
    if (!product) continue;
    const store = findStoreById(product.storeId);
    if (!store) continue;

    const productOwner = users.find(u => u.id === store.professorId);
    if (!productOwner) continue;

    const itemTotal = product.price * item.quantity;
    const netRevenue = itemTotal * (1 - product.affiliateCommissionRate);
    productOwner.balance = (productOwner.balance || 0) + netRevenue;

    let commissionEarned = 0;
    if (affiliateUserId) {
      const affiliate = users.find(u => u.id === affiliateUserId);
      if (affiliate) {
        commissionEarned = itemTotal * product.affiliateCommissionRate;
        affiliate.balance = (affiliate.balance || 0) + commissionEarned;
        createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliate.id, actorId: buyerId, timestamp: Date.now() });
      }
    }

    const newSale: AffiliateSale = {
      id: `sale-${Date.now()}-${item.productId}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned,
      saleAmount: itemTotal,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      isRated: false,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl
    };
    allSales.push(newSale);
  }

  saveUsers(users);
  saveAffiliateSales(allSales);
  clearCart();
  return true;
};

export const updatePostLikes = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    updatePost(post);
  }
};

