export const toggleFollowUser = (currentUserId: string, userIdToFollow: string) => {
  let allUsers = getUsers();
  const current = allUsers.find(u => u.id === currentUserId);
  const target = allUsers.find(u => u.id === userIdToFollow);
  if (current && target) {
    if (current.followedUsers.includes(userIdToFollow)) {
      current.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(userIdToFollow);
      target.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }
    saveUsers(allUsers);
  }
};

export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.type !== ChatType.GROUP && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};

export const startPrivateChat = async (userId1: string, userId2: string) => {
    const chat = getOrCreateConversation(userId1, userId2);
    return chat.id;
};

export const sendMessage = (chatId: string, msg: any) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    chat.messages.push(msg);
    saveChats(chats);
  }
};

export const deleteMessage = async (chatId: string, messageId: string, hardDelete: boolean = false) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        if (hardDelete) {
             chat.messages = chat.messages.filter(m => m.id !== messageId);
        } else {
            const msg = chat.messages.find(m => m.id === messageId);
            if (msg) {
                msg.isDeleted = true;
                msg.text = undefined;
                msg.imageUrl = undefined;
                msg.fileUrl = undefined;
                msg.fileType = undefined;
                msg.fileName = undefined;
            }
        }
        saveChats(chats);
    }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        const msg = chat.messages.find(m => m.id === messageId);
        if (msg) {
            msg.text = newText;
            msg.isEdited = true;
            saveChats(chats);
        }
    }
};

export const markChatMessagesAsRead = async (chatId: string, userId: string) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        chat.messages.forEach(m => {
            if (m.senderId !== userId) {
                m.isRead = true;
            }
        });
        saveChats(chats);
    }
}

