  firebaseConfig.apiKey && 
  firebaseConfig.projectId &&
  firebaseConfig.apiKey !== 'undefined'
);

let app;
let auth;
let db;
let storage;

if (isFirebaseConfigured) {
  try {
    // Inicializa apenas se não existir instância prévia (Singleton)
    app = !getApps().length ? initializeApp(firebaseConfig) : getApp();

    // Inicializa serviços
    auth = getAuth(app);
    db = getFirestore(app);
    storage = getStorage(app);

    console.log("Firebase (Production Mode) conectado:", firebaseConfig.projectId);
