    if (post) {
        if (!post.liveChat) post.liveChat = [];
        post.liveChat.push(comment);
        updatePost(post);
    }
};

export const manageLiveViewers = (postId: string, action: 'join' | 'leave') => {
    const posts = getPosts();
    const post = posts.find(p => p.id === postId);
    if (post) {
        post.liveViewerCount = (post.liveViewerCount || 0) + (action === 'join' ? 1 : -1);
        updatePost(post);
    }
};

export const pulseLiveHeart = (postId: string) => {
    const posts = getPosts();
    const post = posts.find(p => p.id === postId);
    if (post) {
        post.liveHeartCount = (post.liveHeartCount || 0) + 1;
        updatePost(post);
    }
};

export const getAppTheme = (): GroupTheme => {
    return (localStorage.getItem('cyber_app_theme') as GroupTheme) || 'blue';
};

export const saveAppTheme = (theme: GroupTheme) => {
    localStorage.setItem('cyber_app_theme', theme);
};

export const updateUserStatus = (userId: string, isOnline: boolean) => {
    const users = getUsers();
    const user = users.find(u => u.id === userId);
    if (user) {
        user.isOnline = isOnline;
        user.lastSeen = Date.now();
        saveUsers(users);
    }
};

export const updateGroupTheme = async (chatId: string, theme: GroupTheme) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        chat.theme = theme;
        saveChats(chats);
    }
};

export const leaveGroup = async (chatId: string, userId: string) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        chat.participants = chat.participants.filter(id => id !== userId);
        saveChats(chats);
    }
};

export const deleteChat = async (chatId: string) => {
    const chats = getChats().filter(c => c.id !== chatId);
    saveChats(chats);
};

export const createGroup = async (name: string, members: string[], adminId: string, description?: string, theme?: GroupTheme, imageFile?: File, isPublic?: boolean) => {
    const chats = getChats();
    let imageUrl = '';
    if (imageFile) imageUrl = await uploadFile(imageFile, 'groups');

    const newGroup: ChatConversation = {
        id: generateUUID(),
        type: ChatType.GROUP,
        participants: [...members, adminId],
        messages: [],
        groupName: name,
        groupImage: imageUrl,
        adminId,
        isPublic,
        description,
        theme
    };
    saveChats([newGroup, ...chats]);
};

export const joinGroup = async (groupId: string, userId: string) => {
    const chats = getChats();
    const chat = chats.find(c => c.id === groupId);
    if (chat && !chat.participants.includes(userId)) {
        chat.participants.push(userId);
        saveChats(chats);
    }
};

export const getSystemLogs = (): SystemLog[] => []; 

export const adminUpdateUser = async (user: User) => updateUser(user);
export const adminDeletePost = async (postId: string) => deletePost(postId);
export const adminDeleteProduct = async (productId: string) => {
    const products = getProducts().filter(p => p.id !== productId);
    saveProducts(products);
};
export const adminProcessReport = async (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
    const reports = getReports();
    const report = reports.find(r => r.id === reportId);
    if(report) {
        report.status = status;
        saveReports(reports);
    }
};

export const createStore = async (store: Store) => {
    const stores = getStores();
    saveStores([...stores, store]);
};

export const fulfillDropshippingOrder = async (saleId: string, userId: string, cost: number) => {
    if (updateUserBalance(userId, -cost)) {
        updateSaleStatus(saleId, OrderStatus.PROCESSING_SUPPLIER);
        return true;
    }
    return false;
};

export const updateSaleTracking = async (saleId: string, trackingCode: string, supplierOrderId?: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(s => s.id === saleId);
    if (sale) {
        sale.trackingCode = trackingCode;
        if(supplierOrderId) sale.supplierOrderId = supplierOrderId;
        saveAffiliateSales(sales);
    }
};

export const processUserUpgrade = async (userId: string, user: User, docFile: File, credentials: string) => {
    if (!updateUserBalance(userId, -29.90)) throw new Error("Saldo insuficiente");
    const docUrl = await uploadFile(docFile, 'docs');
    const updatedUser = { 
        ...user, 
        userType: UserType.CREATOR, 
        credentials, 
        verificationFileUrl: docUrl 
    };
    updateUser(updatedUser);
    const stores = getStores();
    if (!stores.find(s => s.professorId === userId)) {
        const newStore: Store = {
            id: generateUUID(),
            professorId: userId,
            name: `${user.firstName}'s Store`,
            description: 'Welcome',
            productIds: []
        };
        saveStores([...stores, newStore]);
        updatedUser.storeId = newStore.id;
        updateUser(updatedUser);
    }
};

export const getOptimizedVideoUrl = (url: string) => url; 

export const updateUserPassword = async (password: string) => {
    console.log("Password updated (mock)");
};

export const deleteUser = async (userId: string) => {
    let users = getUsers();
    users = users.filter(u => u.id !== userId);
    saveUsers(users);

    // Also remove from local session
    if (localStorage.getItem(CURRENT_USER_KEY) === userId) {
        localStorage.removeItem(CURRENT_USER_KEY);
    }
};

// Support functions
export const getSupportTickets = async (userId?: string): Promise<SupportTicket[]> => {
    const json = localStorage.getItem(SUPPORT_TICKETS_KEY);
    const tickets = json ? JSON.parse(json) as SupportTicket[] : [];
    if (userId) return tickets.filter(t => t.userId === userId);
    return tickets;
};

export const saveSupportTickets = (tickets: SupportTicket[]) => {
    localStorage.setItem(SUPPORT_TICKETS_KEY, JSON.stringify(tickets));
};

export const createSupportTicket = async (ticketData: Pick<SupportTicket, 'userId' | 'subject' | 'category'>, initialMessage: string, attachmentUrl?: string, attachmentType?: 'image' | 'video') => {
    const tickets = await getSupportTickets();
    const newTicket: SupportTicket = {
        id: generateUUID(),
        userId: ticketData.userId,
        subject: ticketData.subject,
        category: ticketData.category,
        status: 'OPEN',
        createdAt: Date.now(),
        updatedAt: Date.now(),
        messages: [
            {
                id: generateUUID(),
                senderId: ticketData.userId,
                text: initialMessage,
                timestamp: Date.now(),
                attachmentUrl,
                attachmentType
            }
        ]
    };
    saveSupportTickets([newTicket, ...tickets]);
    return newTicket;
};

export const addSupportMessage = async (ticketId: string, messageData: { senderId: string, text: string, attachmentUrl?: string, attachmentType?: 'image' | 'video' }) => {
    const tickets = await getSupportTickets();
    const ticket = tickets.find(t => t.id === ticketId);
    if (ticket) {
        const newMessage: SupportMessage = {
            id: generateUUID(),
            senderId: messageData.senderId,
            text: messageData.text,
            timestamp: Date.now(),
            attachmentUrl: messageData.attachmentUrl,
            attachmentType: messageData.attachmentType
        };
        ticket.messages.push(newMessage);
        ticket.updatedAt = Date.now();
        saveSupportTickets(tickets);
    }
};

import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig(({ mode }) => {
  // Carrega variáveis de ambiente do arquivo .env baseado no modo (development/production)
  // O terceiro argumento '' garante que carregue todas as variáveis, não apenas as com prefixo VITE_
  const env = loadEnv(mode, (process as any).cwd(), '');

  return {
    plugins: [react()],
    define: {
      // Polyfill para process.env para evitar erros de 'process is not defined'
      'process.env': env,
    },
    build: {
      outDir: 'dist',
      sourcemap: true,
      commonjsOptions: {
        transformMixedEsModules: true,
      },
    },
    server: {
      host: true
    }
  };
});

