import { initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";

const firebaseConfig = {
  // Use 'import.meta.env' para projetos Vite
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID
};

// Verifica se a configuração está presente
export const isFirebaseConfigured = !!(firebaseConfig.apiKey && firebaseConfig.apiKey !== 'undefined');

// Inicializa o app
const app = initializeApp(firebaseConfig);

// Exporta os serviços
const auth = getAuth(app);
const db = getFirestore(app);
const storage = getStorage(app);

console.log("Firebase conectado:", firebaseConfig.projectId);

export { auth, db, storage };
export default app;

import { User, Post, ChatConversation, AdCampaign, UserType, Store, Product, AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, Notification, NotificationType, CartItem, ProductRating, OrderStatus, CyberEvent, Story, Transaction, ContentReport, SystemLog, GlobalSettings, TransactionType, ChatType, GroupTheme, SupportTicket, SupportMessage, Message } from '../types';
import { DEFAULT_USERS, DEFAULT_POSTS, DEFAULT_ADS, DEFAULT_STORES, DEFAULT_PRODUCTS, DEFAULT_AFFILIATE_SALES, DEFAULT_PROFILE_PIC, DEFAULT_AUDIO_TRACKS } from '../data/constants';
import { auth, isFirebaseConfigured } from './firebaseClient';
// Importações Modulares do Firebase Auth
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';

const USERS_KEY = 'cyberphone_users';
const POSTS_KEY = 'cyberphone_posts';
const CHATS_KEY = 'cyberphone_chats';
const ADS_KEY = 'cyberphone_ads';
const CURRENT_USER_KEY = 'cyberphone_current_user_id';
const STORES_KEY = 'cyberphone_stores';
const PRODUCTS_KEY = 'cyberphone_products';
const AFFILIATE_SALES_KEY = 'cyberphone_affiliate_sales';
const AUDIO_TRACKS_KEY = 'cyberphone_audio_tracks';
const NOTIFICATIONS_KEY = 'cyberphone_notifications';
const CART_KEY = 'cyberphone_cart';
const STORIES_KEY = 'cyberphone_stories';
const EVENTS_KEY = 'cyberphone_events';
const REPORTS_KEY = 'cyberphone_reports';
const TRANSACTIONS_KEY = 'cyberphone_transactions';
const SETTINGS_KEY = 'cyberphone_settings';
const SUPPORT_TICKETS_KEY = 'cyberphone_support_tickets';

// --- INICIALIZAÇÃO DE DADOS ---
const initializeData = () => {
  if (!localStorage.getItem(USERS_KEY)) localStorage.setItem(USERS_KEY, JSON.stringify(DEFAULT_USERS));
  if (!localStorage.getItem(POSTS_KEY)) localStorage.setItem(POSTS_KEY, JSON.stringify(DEFAULT_POSTS));
  if (!localStorage.getItem(ADS_KEY)) localStorage.setItem(ADS_KEY, JSON.stringify(DEFAULT_ADS));
  if (!localStorage.getItem(CHATS_KEY)) localStorage.setItem(CHATS_KEY, JSON.stringify([]));
  if (!localStorage.getItem(STORES_KEY)) localStorage.setItem(STORES_KEY, JSON.stringify(DEFAULT_STORES));
  if (!localStorage.getItem(PRODUCTS_KEY)) localStorage.setItem(PRODUCTS_KEY, JSON.stringify(DEFAULT_PRODUCTS));
  if (!localStorage.getItem(AFFILIATE_SALES_KEY)) localStorage.setItem(AFFILIATE_SALES_KEY, JSON.stringify(DEFAULT_AFFILIATE_SALES));
  if (!localStorage.getItem(AUDIO_TRACKS_KEY)) localStorage.setItem(AUDIO_TRACKS_KEY, JSON.stringify(DEFAULT_AUDIO_TRACKS));
  if (!localStorage.getItem(NOTIFICATIONS_KEY)) localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify([]));
  if (!localStorage.getItem(CART_KEY)) localStorage.setItem(CART_KEY, JSON.stringify([]));
};

initializeData();

export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

// --- AUTHENTICATION (HYBRID FIREBASE + LOCAL) ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (isFirebaseConfigured && auth) {
    try {
      // Uso correto da sintaxe modular
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Sincroniza/Busca usuário no localStorage usando o UID do Firebase
      const users = getUsers();
      let user = users.find(u => u.id === firebaseUser.uid || u.email === email);

      if (!user) {
        // Se o usuário logou no Firebase mas não tem dados locais (novo dispositivo), cria um perfil básico
        user = {
          id: firebaseUser.uid,
          email: firebaseUser.email || email,
          firstName: 'Usuário',
          lastName: 'Novo',
          userType: UserType.STANDARD,
          phone: '',
          documentId: '',
          birthDate: Date.now(),
          followers: [],
          followedUsers: [],
          balance: 0,
          profilePicture: DEFAULT_PROFILE_PIC
        };
        saveUsers([...users, user]);
      }
      return user;
    } catch (error: any) {
      console.error("Firebase Login Error:", error);
      throw new Error(error.message || 'Erro ao autenticar no Firebase.');
    }
  } else {
    // Fallback Local Only (Caso a chave não esteja configurada)
    const users = getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado (Modo Local). Verifique as chaves do Firebase.');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = `user-${Date.now()}`;

  if (isFirebaseConfigured && auth) {
    try {
      // Uso correto da sintaxe modular
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      console.error("Firebase Register Error:", error);
      throw new Error(error.message || 'Erro ao criar conta no Firebase.');
    }
  } else {
    const users = getUsers();
    if (users.some(u => u.email === userData.email)) {
      throw new Error('Email já cadastrado (Local).');
    }
  }

  const newUser: User = {
    id: uid,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl
  };

  if (newUser.userType === UserType.CREATOR) {
    const allStores = getStores();
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    saveStores([...allStores, {
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName} ${newUser.lastName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
    }]);
  }

  // Salva no localStorage para manter consistência de dados na aplicação
  const users = getUsers();
  saveUsers([...users, newUser]);

  return newUser;
};

// --- DATA ACCESS METHODS (LOCAL STORAGE) ---

export const getCart = (): CartItem[] => {
  const cartJson = localStorage.getItem(CART_KEY);
  return cartJson ? JSON.parse(cartJson) : [];
};

export const saveCart = (cart: CartItem[]) => {
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existingItem = cart.find(item => item.productId === productId && item.selectedColor === selectedColor);
  if (existingItem) {
    existingItem.quantity += quantity;
  } else {
    cart.push({ productId, quantity, selectedColor });
  }
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(item => item.productId !== productId);
  saveCart(cart);
};

export const clearCart = () => {
  saveCart([]);
};

export const getNotifications = (): Notification[] => {
  const notificationsJson = localStorage.getItem(NOTIFICATIONS_KEY);
  if (!notificationsJson) return [];
  try {
    return JSON.parse(notificationsJson);
  } catch (e) {
    return [];
  }
};

export const saveNotifications = (notifications: Notification[]) => {
  localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(notifications));
};

export const createNotification = (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) {
    return;
  }
  const notifications = getNotifications();
  const newNotification: Notification = {
    ...notificationData,
    id: `notif-${Date.now()}-${Math.random()}`,
    isRead: false,
  };
  saveNotifications([newNotification, ...notifications]);
};

export const getNotificationsForUser = (userId: string): Notification[] => {
  return getNotifications().filter(n => n.recipientId === userId);
};

export const markNotificationsAsRead = (userId: string) => {
  let notifications = getNotifications();
  notifications.forEach(n => {
    if (n.recipientId === userId && !n.isRead) {
      n.isRead = true;
    }
  });
  saveNotifications(notifications);
};

export const saveUsers = (users: User[]) => {
  localStorage.setItem(USERS_KEY, JSON.stringify(users));
};

export const getUsers = (): User[] => {
  const usersJson = localStorage.getItem(USERS_KEY);
  if (!usersJson) return [];
  try {
    return JSON.parse(usersJson);
  } catch (e) {
    return [];
  }
};

export const savePosts = (posts: Post[]) => {
  localStorage.setItem(POSTS_KEY, JSON.stringify(posts));
};

export const getPosts = (): Post[] => {
  const postsJson = localStorage.getItem(POSTS_KEY);
  if (!postsJson) return [];
  try {
    return JSON.parse(postsJson);
  } catch (e) {
    return [];
  }
};

export const addPost = (post: Post) => {
  const posts = getPosts();
  savePosts([post, ...posts]);
};

export const deletePost = (postId: string) => {
  let posts = getPosts();
  posts = posts.filter(post => post.id !== postId);
  savePosts(posts);
};

export const pinPost = (postId: string, userId: string) => {
  let posts = getPosts();
  posts.forEach(p => {
    if (p.userId === userId) p.isPinned = (p.id === postId);
  });
  savePosts(posts);
  return true;
};

export const unpinPost = (postId: string, userId: string) => {
  let posts = getPosts();
  const p = posts.find(p => p.id === postId && p.userId === userId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};

export const saveChats = (chats: ChatConversation[]) => {
  localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
};

export const getChats = (userId?: string): ChatConversation[] => {
  const chatsJson = localStorage.getItem(CHATS_KEY);
  if (!chatsJson) return [];
  try {
    const chats = JSON.parse(chatsJson) as ChatConversation[];
    if (userId) {
      return chats.filter(c => c.participants.includes(userId));
    }
    return chats;
  } catch (e) {
    return [];
  }
};

export const saveAds = (ads: AdCampaign[]) => {
  localStorage.setItem(ADS_KEY, JSON.stringify(ads));
};

export const getAds = (): AdCampaign[] => {
  const adsJson = localStorage.getItem(ADS_KEY);
  if (!adsJson) return [];
  try {
    return JSON.parse(adsJson);
  } catch (e) {
    return [];
  }
};

export const createAd = (ad: AdCampaign) => {
    const ads = getAds();
    saveAds([ad, ...ads]);
};

export const saveStores = (stores: Store[]) => {
  localStorage.setItem(STORES_KEY, JSON.stringify(stores));
};

export const getStores = (): Store[] => {
  const storesJson = localStorage.getItem(STORES_KEY);
  if (!storesJson) return [];
  try {
    return JSON.parse(storesJson);
  } catch (e) {
    return [];
  }
};

export const findStoreById = (storeId: string): Store | undefined => {
  return getStores().find(s => s.id === storeId);
};

export const updateStore = (updatedStore: Store) => {
  let stores = getStores();
  stores = stores.map(store => store.id === updatedStore.id ? updatedStore : store);
  saveStores(stores);
};

export const saveProducts = (products: Product[]) => {
  localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
};

export const getProducts = (): Product[] => {
  const productsJson = localStorage.getItem(PRODUCTS_KEY);
  if (!productsJson) return [];
  try {
    return JSON.parse(productsJson);
  } catch (e) {
    return [];
  }
};

export const createProduct = async (product: Product) => {
    const products = getProducts();
    saveProducts([...products, product]);
};

export const findProductById = (productId: string): Product | undefined => {
  return getProducts().find(p => p.id === productId);
};

export const saveAffiliateSales = (sales: AffiliateSale[]) => {
  localStorage.setItem(AFFILIATE_SALES_KEY, JSON.stringify(sales));
};

export const getAffiliateSales = (): AffiliateSale[] => {
  const salesJson = localStorage.getItem(AFFILIATE_SALES_KEY);
  if (!salesJson) return [];
  try {
    return JSON.parse(salesJson);
  } catch (e) {
    return [];
  }
};

export const getPurchasesByBuyerId = (userId: string): AffiliateSale[] => {
  return getAffiliateSales().filter(s => s.buyerId === userId);
};

export const getSalesByAffiliateId = (affiliateUserId: string): AffiliateSale[] => {
  return getAffiliateSales().filter(sale => sale.affiliateUserId === affiliateUserId);
};

export const getSalesByStoreId = (storeId: string): AffiliateSale[] => {
  return getAffiliateSales().filter(sale => sale.storeId === storeId);
};

export const updateSaleStatus = (saleId: string, status: OrderStatus) => {
  const sales = getAffiliateSales().map(s => s.id === saleId ? { ...s, status } : s);
  saveAffiliateSales(sales);
};

export const getAudioTracks = async (): Promise<AudioTrack[]> => {
  const tracksJson = localStorage.getItem(AUDIO_TRACKS_KEY);
  if (!tracksJson) return DEFAULT_AUDIO_TRACKS;
  try {
    return JSON.parse(tracksJson);
  } catch (e) {
    return [];
  }
};

export const findAudioTrackById = async (id: string): Promise<AudioTrack | undefined> => {
  const tracks = await getAudioTracks();
  return tracks.find(t => t.id === id);
