export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const useFirestore = () => isFirebaseConfigured && db;

// --- AUTHENTICATION ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Get User Profile from Firestore
      const userDoc = await getDocFromFirestore('profiles', firebaseUser.uid);
      if (userDoc) return userDoc as User;

      // Fallback: Create basic profile if auth exists but profile doesn't
      const newUser = {
        id: firebaseUser.uid,
        email: firebaseUser.email || email,
        firstName: 'Usuário',
        lastName: 'Novo',
        userType: UserType.STANDARD,
        phone: '',
        documentId: '',
        birthDate: Date.now(),
        followers: [],
        followedUsers: [],
        balance: 0,
        profilePicture: DEFAULT_PROFILE_PIC
      } as User;
      await setDoc(doc(db, 'profiles', newUser.id), newUser);
      return newUser;
    } catch (error: any) {
      console.error("Firebase Login Error:", error);
      throw new Error(error.message || 'Erro ao autenticar no Firebase.');
    }
  } else {
    const users = await getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado (Modo Local).');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = `user-${Date.now()}`;

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      console.error("Firebase Register Error:", error);
      throw new Error(error.message || 'Erro ao criar conta no Firebase.');
    }
  } else {
    const users = await getUsers();
    if (users.some(u => u.email === userData.email)) {
      throw new Error('Email já cadastrado (Local).');
    }
  }

  const newUser: User = {
    id: uid,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl
  };

  if (newUser.userType === UserType.CREATOR) {
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    const newStore = {
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName} ${newUser.lastName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
    };
    if (useFirestore()) {
        await setDoc(doc(db, 'stores', storeId), newStore);
    } else {
        const stores = await getStores();
        saveStores([...stores, newStore]);
    }
  }

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), newUser);
  } else {
      const users = await getUsers();
      saveUsers([...users, newUser]);
  }

  return newUser;
};

// --- GENERIC FIRESTORE HELPERS ---

async function getCollectionFromFirestore<T>(colName: string): Promise<T[]> {
    if (!useFirestore()) return [];
    try {
        const q = query(collection(db, colName));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as T));
    } catch (e) {
        console.error(`Error fetching ${colName}:`, e);
        return [];
    }
}

async function getDocFromFirestore<T>(colName: string, id: string): Promise<T | undefined> {
    if (!useFirestore()) return undefined;
    // We reuse getDocs with where for simplicity in this hybrid setup or explicit doc get could be used but 
    // Typescript setup for `doc` is safer with `getDocs` + `query` if structure varies.
    // Actually standard doc get:
    try {
        const snapshot = await getDocs(query(collection(db, colName), where('id', '==', id)));
        if (!snapshot.empty) return snapshot.docs[0].data() as T;
    } catch (e) {}
    return undefined;
}

// --- DATA ACCESS METHODS ---

export const getCart = (): CartItem[] => {
  const cartJson = localStorage.getItem(CART_KEY);
  return cartJson ? JSON.parse(cartJson) : [];
};

export const saveCart = (cart: CartItem[]) => {
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existingItem = cart.find(item => item.productId === productId && item.selectedColor === selectedColor);
  if (existingItem) {
    existingItem.quantity += quantity;
  } else {
    cart.push({ productId, quantity, selectedColor });
  }
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(item => item.productId !== productId);
  saveCart(cart);
};

export const clearCart = () => {
  saveCart([]);
};

// NOTIFICATIONS
export const getNotifications = async (): Promise<Notification[]> => {
  if (useFirestore()) return getCollectionFromFirestore('notifications');
  const notificationsJson = localStorage.getItem(NOTIFICATIONS_KEY);
  return notificationsJson ? JSON.parse(notificationsJson) : [];
};

export const saveNotifications = (notifications: Notification[]) => {
  localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(notifications));
};

export const createNotification = async (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) return;
  const newNotification: Notification = {
    ...notificationData,
    id: `notif-${Date.now()}-${Math.random()}`,
    isRead: false,
  };

  if (useFirestore()) {
      await setDoc(doc(db, 'notifications', newNotification.id), newNotification);
  } else {
      const notifications = await getNotifications();
      saveNotifications([newNotification, ...notifications]);
  }
};

export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
  const all = await getNotifications();
  return all.filter(n => n.recipientId === userId);
};

export const markNotificationsAsRead = async (userId: string) => {
  const notifications = await getNotifications();
  if (useFirestore()) {
      const userNotifs = notifications.filter(n => n.recipientId === userId && !n.isRead);
      for (const n of userNotifs) {
          await updateDoc(doc(db, 'notifications', n.id), { isRead: true });
      }
  } else {
      notifications.forEach(n => {
        if (n.recipientId === userId && !n.isRead) n.isRead = true;
      });
      saveNotifications(notifications);
  }
};

// USERS
export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) return getCollectionFromFirestore('profiles');
  const usersJson = localStorage.getItem(USERS_KEY);
  return usersJson ? JSON.parse(usersJson) : [];
};

export const saveUsers = (users: User[]) => {
  localStorage.setItem(USERS_KEY, JSON.stringify(users));
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
      try {
          // Attempt direct doc fetch first if ID is UUID-like or simple string
          const d = await getDocFromFirestore<User>('profiles', userId); 
          if(d) return d;
          // Fallback to searching all users if id isn't the doc id (unlikely in this schema)
          const users = await getUsers();
          return users.find(u => u.id === userId);
      } catch (e) { return undefined; }
  }
  const users = await getUsers();
  return users.find(u => u.id === userId);
};

export const updateUser = async (updatedUser: User) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', updatedUser.id), updatedUser, { merge: true });
  } else {
      let users = await getUsers();
      users = users.map(user => user.id === updatedUser.id ? updatedUser : user);
      saveUsers(users);
  }
};

