export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
      try {
          const q = query(collection(db, 'posts'), orderBy('timestamp', 'desc'));
          const snapshot = await getDocs(q);
          return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Post));
      } catch (e) { return []; }
  }
  const postsJson = localStorage.getItem(POSTS_KEY);
  return postsJson ? JSON.parse(postsJson) : [];
};

export const savePosts = (posts: Post[]) => {
  localStorage.setItem(POSTS_KEY, JSON.stringify(posts));
};

export const addPost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), post);
  } else {
      const posts = await getPosts();
      savePosts([post, ...posts]);
  }
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) {
      await deleteDoc(doc(db, 'posts', postId));
  } else {
      let posts = await getPosts();
      posts = posts.filter(post => post.id !== postId);
      savePosts(posts);
  }
};

export const updatePost = async (updatedPost: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', updatedPost.id), updatedPost, { merge: true });
  } else {
      let posts = await getPosts();
      posts = posts.map(post => post.id === updatedPost.id ? updatedPost : post);
      savePosts(posts);
  }
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
    await updatePost(post);
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
    const posts = await getPosts();
    const post = posts.find(p => p.id === postId);
    if (post && post.comments) {
        post.comments = post.comments.filter(c => c.id !== commentId);
        await updatePost(post);
    }
};

// CHATS
export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
      try {
          const chatsRef = collection(db, 'chats');
          // Simple client-side filtering for now as array-contains might need index
          const snapshot = await getDocs(chatsRef);
          const allChats = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as ChatConversation));
          return userId ? allChats.filter(c => c.participants.includes(userId)) : allChats;
      } catch (e) { return []; }
  }
  const chatsJson = localStorage.getItem(CHATS_KEY);
  if (!chatsJson) return [];
  const chats = JSON.parse(chatsJson) as ChatConversation[];
  if (userId) return chats.filter(c => c.participants.includes(userId));
  return chats;
};

export const saveChats = (chats: ChatConversation[]) => {
  localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const chats = await getChats();
  let chat = chats.find(c => c.type !== ChatType.GROUP && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    if (useFirestore()) {
        await setDoc(doc(db, 'chats', chat.id), chat);
    } else {
        saveChats([...chats, chat]);
    }
  }
  return chat;
};

export const startPrivateChat = async (userId1: string, userId2: string) => {
    const chat = await getOrCreateConversation(userId1, userId2);
    return chat.id;
};

export const sendMessage = async (chatId: string, msg: any) => {
  const chats = await getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    if (!chat.messages) chat.messages = [];
    chat.messages.push(msg);
    if (useFirestore()) {
        await updateDoc(doc(db, 'chats', chatId), { messages: chat.messages });
    } else {
        saveChats(chats);
    }
  }
};

