export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  let allUsers = await getUsers();
  const current = allUsers.find(u => u.id === currentUserId);
  const target = allUsers.find(u => u.id === userIdToFollow);

  if (current && target) {
    let updatedCurrent = {...current};
    let updatedTarget = {...target};

    if (current.followedUsers.includes(userIdToFollow)) {
      updatedCurrent.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      updatedTarget.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      updatedCurrent.followedUsers.push(userIdToFollow);
      updatedTarget.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }

    await updateUser(updatedCurrent);
    await updateUser(updatedTarget);
  }
};

