export const addStory = async (uId: string, item: any) => {
  const stories = await getStories();
  const user = await findUserById(uId);
  if (!user) return;

  let userStory = stories.find(s => s.userId === uId);
  if (!userStory) {
    userStory = { id: `story-${uId}`, userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    if (!useFirestore()) stories.push(userStory);
  }

  if (!userStory.items) userStory.items = [];
  userStory.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });

  if (useFirestore()) {
      await setDoc(doc(db, 'stories', userStory.id!), userStory);
  } else {
      localStorage.setItem(STORIES_KEY, JSON.stringify(stories));
  }
};

