// --- AUTHENTICATION ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Get User Profile from Firestore
      const userDoc = await getDocFromFirestore('profiles', firebaseUser.uid);
      if (userDoc) return userDoc as User;

      // Fallback: Create basic profile if auth exists but profile doesn't
      const newUser = {
        id: firebaseUser.uid,
        email: firebaseUser.email || email,
        firstName: 'Usuário',
        lastName: 'Novo',
        userType: UserType.STANDARD,
        phone: '',
        documentId: '',
        birthDate: Date.now(),
        followers: [],
        followedUsers: [],
        balance: 0,
        profilePicture: DEFAULT_PROFILE_PIC
      } as User;
      await setDoc(doc(db, 'profiles', newUser.id), newUser);
      return newUser;
    } catch (error: any) {
      console.error("Firebase Login Error:", error);
      throw new Error(error.message || 'Erro ao autenticar no Firebase.');
    }
  } else {
    const users = await getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado (Modo Local).');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = `user-${Date.now()}`;

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      console.error("Firebase Register Error:", error);
      throw new Error(error.message || 'Erro ao criar conta no Firebase.');
    }
  } else {
    const users = await getUsers();
    if (users.some(u => u.email === userData.email)) {
      throw new Error('Email já cadastrado (Local).');
    }
  }

  const newUser: User = {
    id: uid,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl
  };

  if (newUser.userType === UserType.CREATOR) {
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    const newStore = {
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName} ${newUser.lastName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
    };
    if (useFirestore()) {
        await setDoc(doc(db, 'stores', storeId), newStore);
    } else {
        const stores = await getStores();
        saveStores([...stores, newStore]);
    }
  }

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), newUser);
  } else {
      const users = await getUsers();
      saveUsers([...users, newUser]);
  }

  return newUser;
};

// --- GENERIC FIRESTORE HELPERS ---

async function getCollectionFromFirestore<T>(colName: string): Promise<T[]> {
    if (!useFirestore()) return [];
    try {
        const q = query(collection(db, colName));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as T));
    } catch (e) {
        console.error(`Error fetching ${colName}:`, e);
        return [];
    }
}

async function getDocFromFirestore<T>(colName: string, id: string): Promise<T | undefined> {
    if (!useFirestore()) return undefined;
    try {
        // Query by id field if using local storage style IDs within docs, or document ID
        // Assuming documents are keyed by ID or have ID field.
        // Trying direct doc access first
        const docRef = doc(db, colName, id);
        // But since we might not know if ID is doc ID or field ID, sticking to collection query if structure is uncertain
        // However, for profiles we set ID as doc ID.
        // For mixed usage, query is safer if IDs are generated UUIDs stored as fields.
        const q = query(collection(db, colName), where('id', '==', id));
        const snapshot = await getDocs(q);
        if (!snapshot.empty) return snapshot.docs[0].data() as T;
    } catch (e) {}
    return undefined;
}

