export const createNotification = async (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) return;
  const newNotification: Notification = {
    ...notificationData,
    id: `notif-${Date.now()}-${Math.random()}`,
    isRead: false,
  };

  if (useFirestore()) {
      await setDoc(doc(db, 'notifications', newNotification.id), newNotification);
  } else {
      const notifications = await getNotifications();
      saveNotifications([newNotification, ...notifications]);
  }
};

export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
  const all = await getNotifications();
  return all.filter(n => n.recipientId === userId);
};

export const markNotificationsAsRead = async (userId: string) => {
  const notifications = await getNotifications();
  if (useFirestore()) {
      const userNotifs = notifications.filter(n => n.recipientId === userId && !n.isRead);
      for (const n of userNotifs) {
          await updateDoc(doc(db, 'notifications', n.id), { isRead: true });
      }
  } else {
      notifications.forEach(n => {
        if (n.recipientId === userId && !n.isRead) n.isRead = true;
      });
      saveNotifications(notifications);
  }
};

