export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
      try {
          const d = await getDocFromFirestore<User>('profiles', userId); 
          if(d) return d;
          const users = await getUsers();
          return users.find(u => u.id === userId);
      } catch (e) { return undefined; }
  }
  const users = await getUsers();
  return users.find(u => u.id === userId);
};

export const updateUser = async (updatedUser: User) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', updatedUser.id), updatedUser, { merge: true });
  } else {
      let users = await getUsers();
      users = users.map(user => user.id === updatedUser.id ? updatedUser : user);
      saveUsers(users);
  }
};

export const updateUserBalance = async (userId: string, amount: number) => {
  if (useFirestore()) {
      try {
        const u = await findUserById(userId);
        if (u) {
            const newBal = (u.balance || 0) + amount;
            await updateDoc(doc(db, 'profiles', userId), { balance: newBal });
            return true;
        }
      } catch(e) { console.error(e); }
      return false;
  } else {
      const users = await getUsers();
      const user = users.find(u => u.id === userId);
      if (user) {
        user.balance = (user.balance || 0) + amount;
        saveUsers(users);
        return true;
      }
      return false;
  }
};

