    const sales = await getAffiliateSales();
    const products = await getProducts();
    const sale = sales.find(s => s.id === saleId);
    if (!sale || sale.isRated) return false;
    const product = products.find(p => p.id === sale.productId);
    if (!product) return false;

    sale.isRated = true;
    const newRating: ProductRating = { id: `rating-${Date.now()}`, saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() };
    product.ratings.push(newRating);
    product.ratingCount = product.ratings.length;
    product.averageRating = product.ratings.reduce((sum, r) => sum + r.rating, 0) / product.ratingCount;

    if (useFirestore()) {
        await updateDoc(doc(db, 'affiliate_sales', saleId), { isRated: true });
        await updateDoc(doc(db, 'products', product.id), { ratings: product.ratings, ratingCount: product.ratingCount, averageRating: product.averageRating });
    } else {
        localStorage.setItem(AFFILIATE_SALES_KEY, JSON.stringify(sales));
        localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
    }
    return true;
};

