export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
    const users = await getUsers();
    const products = await getProducts();
    const stores = await getStores();

    const newSales: AffiliateSale[] = [];

    for (const item of cartItems) {
        const product = products.find(p => p.id === item.productId);
        if (!product) continue;
        const store = stores.find(s => s.id === product.storeId);
        if (!store) continue;

        const owner = users.find(u => u.id === store.professorId);

        const total = product.price * item.quantity;
        let commission = 0;

        if (affiliateUserId && affiliateUserId !== owner?.id) {
            commission = total * product.affiliateCommissionRate;
            const affiliate = users.find(u => u.id === affiliateUserId);
            if (affiliate) {
                await updateUserBalance(affiliate.id, commission);
                await createNotification({ 
                    type: NotificationType.AFFILIATE_SALE, 
                    recipientId: affiliate.id, 
                    actorId: buyerId, 
                    timestamp: Date.now()
                });
            }
        }

        if (owner) {
            await updateUserBalance(owner.id, total - commission);
        }

        const sale: AffiliateSale = {
            id: `sale-${Date.now()}-${generateUUID().slice(0,4)}`,
            productId: product.id,
            buyerId,
            affiliateUserId: affiliateUserId || '',
            storeId: store.id,
            commissionEarned: commission,
            saleAmount: total,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            isRated: false,
            shippingAddress,
            digitalContentUrl: product.digitalContentUrl,
            isDropshipping: product.isDropshipping,
            supplierCost: product.originalPrice ? product.originalPrice * item.quantity : undefined
        };
        newSales.push(sale);
    }

    if (useFirestore()) {
        for (const sale of newSales) {
            await setDoc(doc(db, 'affiliate_sales', sale.id), sale);
        }
    } else {
        const sales = await getAffiliateSales();
        saveAffiliateSales([...newSales, ...sales]);
    }
    clearCart();
    return true;
};

