import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostSaves, 
  unpinPost, 
  pinPost,
  createReport,
  updatePostShares,
  deletePost,
  getOptimizedVideoUrl
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  CheckBadgeIcon,
  MapPinIcon as PinIconOutline,
  SignalIcon,
  ShareIcon,
  PlayIcon,
  UserGroupIcon,
  PauseIcon,
  SpeakerWaveIcon,
  SpeakerXMarkIcon,
  ArrowsPointingOutIcon,
  LockClosedIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon,
  VideoCameraIcon
} from '@heroicons/react/24/solid';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';
import IndicateModal from './IndicateModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  // Optimistic UI states
  const [localLikes, setLocalLikes] = useState<string[]>(post.likes || []);
  const [isLiked, setIsLiked] = useState(post.likes?.includes(currentUser.id) || false);
  const [localSaves, setLocalSaves] = useState<string[]>(post.saves || []);
  const [isSaved, setIsSaved] = useState(post.saves?.includes(currentUser.id) || false);

  // Video Player States
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [showControls, setShowControls] = useState(true);

  const isFollowing = currentUser.followedUsers?.includes(post.userId);

  // Gera um delay aleatório para a animação de flutuação, para que os cards não se movam em uníssono.
  const animationDelay = useMemo(() => `${Math.random() * 5}s`, []);

  useEffect(() => {
    setLocalLikes(post.likes || []);
    setIsLiked(post.likes?.includes(currentUser.id) || false);
    setLocalSaves(post.saves || []);
    setIsSaved(post.saves?.includes(currentUser.id) || false);
  }, [post.likes, post.saves, currentUser.id]);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();
  }, [post.userId]);

  // Video Player Logic
  const formatTime = (seconds: number) => {
    if (isNaN(seconds)) return "00:00";
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const togglePlay = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
        setIsPlaying(false);
      } else {
        videoRef.current.play();
        setIsPlaying(true);
      }
    }
  };

  const toggleMute = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
      setIsMuted(!isMuted);
    }
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      const current = videoRef.current.currentTime;
      const total = videoRef.current.duration;
      setCurrentTime(current);
      setDuration(total);
      setProgress((current / total) * 100);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (videoRef.current) {
      const newTime = (parseFloat(e.target.value) / 100) * videoRef.current.duration;
      videoRef.current.currentTime = newTime;
      setProgress(parseFloat(e.target.value));
    }
  };

  const handleFullscreen = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (videoRef.current) {
      if (videoRef.current.requestFullscreen) {
        videoRef.current.requestFullscreen();
      }
    }
  };

  if (!post || !currentUser || !post.id || !postAuthor) return null;

  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsLiked = isLiked;
    const prevLikes = [...localLikes];

    setIsLiked(!prevIsLiked);
    if (prevIsLiked) {
      setLocalLikes(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalLikes(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostLikes(post.id, currentUser.id);
    } catch (error) {
      setIsLiked(prevIsLiked);
      setLocalLikes(prevLikes);
      console.error("Falha ao curtir post", error);
    }
  };

  const handleSave = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsSaved = isSaved;
    const prevSaves = [...localSaves];

    setIsSaved(!prevIsSaved);
    if (prevIsSaved) {
      setLocalSaves(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalSaves(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostSaves(post.id, currentUser.id);
    } catch (error) {
      setIsSaved(prevIsSaved);
      setLocalSaves(prevSaves);
    }
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';
  const contentLength = post.content?.length || 0;

  // Lógica Adaptativa de Tamanho (Otimizada para Mobile)
  let containerMinHeight = 'auto';
  let fontSizeClass = 'text-sm md:text-lg text-gray-900 dark:text-white';
  let paddingClass = 'py-2';

  if (hasBg) {
    if (contentLength < 60) {
        // Frase Curta
        containerMinHeight = '180px md:min-h-[200px]'; 
        fontSizeClass = `${post.textColor || 'text-white'} text-2xl md:text-4xl leading-tight`;
        paddingClass = 'p-6 md:p-8';
    } else if (contentLength < 150) {
        // Frase Média
        containerMinHeight = '220px md:min-h-[300px]';
        fontSizeClass = `${post.textColor || 'text-white'} text-lg md:text-2xl leading-snug`;
        paddingClass = 'p-6 md:p-10';
    } else {
        // Texto Longo
        containerMinHeight = '280px md:min-h-[400px]';
        fontSizeClass = `${post.textColor || 'text-white'} text-base md:text-xl leading-relaxed`;
        paddingClass = 'p-8 md:p-12';
    }
  }

  // Verifica se é um Replay de Live (Gravada)
  const isRecordedLive = post.type === PostType.LIVE && post.liveStream?.status === 'ENDED' && post.liveStream.recordingUrl;

  return (
    <>
      <div 
        onClick={() => {
          if (post.type === PostType.LIVE && post.liveStream?.status !== 'ENDED') onNavigate('live', { postId: post.id });
          else if (post.type === PostType.REEL) onNavigate('reels-page', { startPostId: post.id });
          else if (!isRecordedLive) setShowDetailModal(true); // Don't open detail modal on video click if handled inside
        }}
        style={{ animationDelay }}
        className="bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 cursor-pointer group animate-float hover-pause hover:shadow-2xl hover:-translate-y-2 transition-all duration-300"
      >
        <div className="p-4 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-5 min-w-0">
            <div className="relative cursor-pointer shrink-0" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-brand rounded-lg md:rounded-xl p-0.5 md:p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-3 w-3 md:h-4 md:w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-col">
                <div className="flex items-center gap-1 md:gap-2">
                  <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-xl truncate tracking-tighter hover:text-brand transition-colors">
                      {postAuthor.firstName}
                  </h4>
                  {post.isPinned && <PinIconSolid className="h-3 w-3 md:h-4 md:w-4 text-brand shrink-0" />}
                  {isPostBoosted && <BoltIcon className="h-3 w-3 md:h-4 md:w-4 text-orange-500 animate-pulse shrink-0" />}
                </div>
                {post.groupId && (
                  <div className="flex items-center gap-1 text-[8px] md:text-[9px] font-black text-brand uppercase tracking-widest mt-0.5 truncate">
                     <UserGroupIcon className="h-3 w-3" /> <span className="truncate">{post.groupName}</span>
                  </div>
                )}
              </div>
              <p className="text-[8px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5 truncate">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-brand">⚡ Promo</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-2 md:p-3 rounded-xl md:rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-brand transition-all shrink-0"
          >
            <EllipsisHorizontalIcon className="h-6 w-6 md:h-7 md:w-7" />
          </button>
        </div>

        <div className={`px-4 md:px-8 ${hasBg ? 'pb-6 md:pb-8' : 'pb-4'}`}>

          {/* CASO: LIVE ATIVA */}
          {post.type === PostType.LIVE && !post.liveStream?.recordingUrl && post.liveStream ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute top-4 left-4 md:top-6 md:left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-3 py-1 md:px-4 md:py-1.5 rounded-full text-[9px] md:text-[10px] font-black flex items-center gap-1.5 shadow-2xl animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3 md:h-3.5 md:w-3.5" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-6 md:py-8 flex flex-col items-center text-center">
                   <h3 className="text-xl md:text-4xl font-black mb-6 md:mb-8 tracking-tighter uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button className="bg-brand text-white px-8 py-4 md:px-10 md:py-5 rounded-[2rem] md:rounded-[2.2rem] font-black text-[10px] md:text-sm uppercase tracking-[0.2em] shadow-xl flex items-center justify-center gap-3 md:gap-4">
                      <PlayIcon className="h-5 w-5 md:h-6 md:w-6" /> Entrar Agora
                   </button>
                </div>
             </div>
          ) : 

          /* CASO: LIVE GRAVADA (REPLAY - PLAYER CUSTOMIZADO) */
          isRecordedLive ? (
             <div 
               className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-black relative shadow-xl mt-2 aspect-video flex items-center justify-center group"
               onMouseEnter={() => setShowControls(true)}
               onMouseLeave={() => isPlaying && setShowControls(false)}
             >
                <video 
                  ref={videoRef}
                  src={getOptimizedVideoUrl(post.liveStream!.recordingUrl!)} 
                  className="w-full h-full object-cover" 
                  playsInline
                  preload="metadata"
                  onTimeUpdate={handleTimeUpdate}
                  onEnded={() => setIsPlaying(false)}
                  onClick={togglePlay}
                />

                {/* Big Center Play Button */}
                {!isPlaying && (
                  <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
                     <div className="bg-white/20 backdrop-blur-md p-6 rounded-full border border-white/20 shadow-2xl animate-scale-in">
                        <PlayIcon className="h-12 w-12 text-white fill-white" />
                     </div>
                  </div>
                )}

                {/* Badge Top Left */}
                <div className="absolute top-4 left-4 z-20 transition-opacity duration-300" style={{ opacity: showControls || !isPlaying ? 1 : 0 }}>
                   <div className="bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-xl text-[9px] font-black uppercase text-white shadow-lg flex items-center gap-2 border border-white/10">
                      <VideoCameraIcon className="h-3 w-3 text-purple-400" /> Replay
                   </div>
                </div>

                {/* Custom Controls Bar */}
                <div className={`absolute bottom-0 left-0 w-full bg-gradient-to-t from-black/90 via-black/50 to-transparent p-4 md:p-6 z-20 transition-all duration-300 ${showControls || !isPlaying ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>

                   {/* Title */}
                   <p className="text-white text-xs md:text-sm font-bold line-clamp-1 mb-3 drop-shadow-md px-1">{post.liveStream?.title}</p>

                   {/* Progress Bar */}
                   <div className="relative w-full h-1.5 bg-white/20 rounded-full mb-3 cursor-pointer group/seek">
                      <div 
                        className="absolute top-0 left-0 h-full bg-purple-500 rounded-full transition-all duration-100 ease-linear shadow-[0_0_10px_rgba(168,85,247,0.5)]" 
                        style={{ width: `${progress}%` }}
                      >
                         <div className="absolute right-0 top-1/2 -translate-y-1/2 w-3 h-3 bg-white rounded-full scale-0 group-hover/seek:scale-100 transition-transform shadow-sm" />
                      </div>
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={progress} 
                        onChange={handleSeek}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                      />
                   </div>

                   {/* Controls Row */}
                   <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4">
                         <button onClick={togglePlay} className="text-white hover:text-purple-400 transition-colors">
                            {isPlaying ? <PauseIcon className="h-6 w-6" /> : <PlayIcon className="h-6 w-6" />}
                         </button>
                         <button onClick={toggleMute} className="text-white/80 hover:text-white transition-colors">
                            {isMuted ? <SpeakerXMarkIcon className="h-5 w-5" /> : <SpeakerWaveIcon className="h-5 w-5" />}
                         </button>
                         <span className="text-[10px] font-mono font-medium text-white/80">
                            {formatTime(currentTime)} / {formatTime(duration)}
                         </span>
                      </div>
                      <button onClick={handleFullscreen} className="text-white hover:text-purple-400 transition-colors">
                         <ArrowsPointingOutIcon className="h-5 w-5" />
                      </button>
                   </div>
                </div>
             </div>
          ) :

          /* CASO: REEL */
          post.type === PostType.REEL && post.reel ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-black relative shadow-xl mt-2 aspect-[9/16] max-h-[500px] md:max-h-[600px] flex items-center justify-center group">
                <video 
                  src={getOptimizedVideoUrl(post.reel.videoUrl)} 
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-500" 
                  muted 
                  loop 
                  playsInline
                  preload="metadata"
                  onMouseOver={(e) => e.currentTarget.play()}
                  onMouseOut={(e) => e.currentTarget.pause()}
                />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                   <div className="bg-white/20 backdrop-blur-md p-3 md:p-4 rounded-full border border-white/10 group-hover:scale-110 transition-transform">
                      <PlayIcon className="h-8 w-8 md:h-10 md:w-10 text-white fill-white" />
                   </div>
                </div>
                <div className="absolute bottom-0 left-0 w-full p-4 md:p-6 bg-gradient-to-t from-black/80 to-transparent pointer-events-none">
                   <p className="text-white text-xs md:text-sm font-medium line-clamp-2">{post.reel.description}</p>
                </div>
             </div>
          ) : (
            /* CASO: POST NORMAL (TEXTO/IMAGEM) */
            <>
              {post.content && (
                <div 
                  className={`rounded-[2rem] md:rounded-[3rem] transition-all duration-500 w-full flex items-center justify-center
                    ${hasBg ? `${post.backgroundColor} text-center shadow-inner mb-4` : 'text-left bg-transparent'} 
                    ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    // Use a classe para altura mínima, o style é override se necessário
                  }}
                >
                  <div className={`w-full ${hasBg ? containerMinHeight : ''} flex items-center justify-center ${hasBg ? paddingClass : 'p-0'}`}>
                    <p className={`font-black whitespace-pre-wrap break-words w-full ${fontSizeClass}`}>
                      {post.content}
                    </p>
                  </div>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl mt-2">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[500px] md:max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-4 md:px-12 py-4 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-2 md:gap-3 px-4 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${isLiked ? 'text-brand bg-brand/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {isLiked ? <HeartIconSolid className="h-5 w-5 md:h-8 md:w-8" /> : <HeartIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{localLikes.length}</span>
            </button>
            <button 
                onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} 
                className="flex items-center gap-2 md:gap-3 px-4 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90"
            >
              {post.disableComments ? <LockClosedIcon className="h-5 w-5 md:h-8 md:w-8 text-gray-300" /> : <ChatIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button className="p-3 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ShareIcon className="h-5 w-5 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={handleSave} className={`p-3 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${isSaved ? 'text-brand bg-brand/10' : 'text-gray-300 hover:bg-gray-50'}`}>
            {isSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor} 
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)} 
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }} 
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }} 
          onPin={() => { if(post.isPinned) unpinPost(post.id, currentUser.id); else pinPost(post.id, currentUser.id); onPostUpdatedOrDeleted(); setShowActionsModal(false); }} 
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }} 
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }} 
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }} 
          onReport={() => { 
            if(window.confirm("Deseja realmente denunciar esta publicação?")) {
              createReport({ reporterId: currentUser.id, targetId: post.id, targetType: 'POST', reason: 'DENÚNCIA', details: 'Via PostCard' }); 
              alert("Denúncia enviada com sucesso. Nossa equipe irá analisar.");
              setShowActionsModal(false); 
            }
          }} 
        />
      )}

      {showDetailModal && <PostDetailModal post={post} currentUser={currentUser} onClose={() => setShowDetailModal(false)} onUpdate={onPostUpdatedOrDeleted} onNavigate={onNavigate} refreshUser={refreshUser} />}
      {showBoostModal && <BoostPostModal post={post} currentUser={currentUser} onClose={() => setShowBoostModal(false)} onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }} />}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)} 
          onConfirm={async () => { 
            await deletePost(post.id); 
            onPostUpdatedOrDeleted(); 
            setShowDeleteModal(false); 
          }} 
        />
      )}

      {showEditModal && <EditPostModal postId={post.id} currentUser={currentUser} onClose={() => setShowEditModal(false)} onSuccess={onPostUpdatedOrDeleted} />}
      {showIndicateModal && <IndicateModal post={post} currentUser={currentUser} onClose={() => setShowIndicateModal(false)} onPostUpdated={onPostUpdatedOrDeleted} />}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Post, User, UserType, Comment } from '../types';
import { findUserById, addPostComment, deleteComment, updatePostLikes, updatePostSaves, updatePostShares, toggleFollowUser, generateUUID, getPosts } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  XMarkIcon, 
  ChatBubbleOvalLeftIcon,
  HeartIcon as HeartIconOutline,
  BookmarkIcon as BookmarkIconOutline,
  ShareIcon,
  EllipsisHorizontalIcon,
  ArrowLeftIcon,
  PaperAirplaneIcon,
  ArrowDownTrayIcon,
  TrashIcon,
  LockClosedIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  CheckBadgeIcon
} from '@heroicons/react/24/solid';

interface PostDetailModalProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onUpdate: () => void;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const PostDetailModal: React.FC<PostDetailModalProps> = ({ post, currentUser, onClose, onUpdate, onNavigate, refreshUser }) => {
  const [commentText, setCommentText] = useState('');
  const [author, setAuthor] = useState<User | null>(null);
  const [comments, setComments] = useState<Comment[]>(post.comments || []);
  const [loadingComments, setLoadingComments] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const commentsEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const user = await findUserById(post.userId);
      setAuthor(user || null);
    };
    fetchAuthor();
  }, [post.userId]);

  // Função para buscar comentários atualizados
  const fetchComments = async () => {
    // setLoadingComments(true); // Opcional: evitar flicker
    const allPosts = await getPosts();
    const currentPost = allPosts.find(p => p.id === post.id);
    if (currentPost) {
      setComments(currentPost.comments || []);
    }
    setLoadingComments(false);
  };

  useEffect(() => {
    fetchComments();
  }, [post.id]);

  const isOwner = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);
  const commentsDisabled = post.disableComments && !isOwner;

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onUpdate();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onUpdate();
  };

  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!post.imageUrl) return;

    try {
      const response = await fetch(post.imageUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `cyberphone-midia-${post.id}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      window.open(post.imageUrl, '_blank');
    }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Publicação de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onUpdate();
    } catch (err) {}
  };

  const handleFollow = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, post.userId);
    refreshUser();
    onUpdate();
  };

  const handleDeleteComment = async (commentId: string) => {
    if (confirm("Apagar este comentário?")) {
        await deleteComment(post.id, commentId);
        await fetchComments();
        onUpdate();
    }
  };

  const handleSendComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim() || commentsDisabled) return;

    const newComment: Comment = {
      id: generateUUID(),
      userId: currentUser.id,
      userName: `${currentUser.firstName} ${currentUser.lastName}`,
      profilePic: currentUser.profilePicture,
      text: commentText,
      timestamp: Date.now()
    };

    // Aguarda a persistência no banco
    await addPostComment(post.id, newComment);

    setCommentText('');

    // Atualiza a lista localmente e notifica o pai
    await fetchComments();
    onUpdate();

    setTimeout(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTo({
          top: scrollRef.current.scrollHeight,
          behavior: 'smooth'
        });
      }
    }, 100);
  };

  if (!author) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';
  const contentLength = post.content?.length || 0;

  // Lógica Adaptativa de Tamanho (Consistente com PostCard)
  let containerMinHeight = 'auto';
  let fontSizeClass = 'text-base md:text-lg text-left text-gray-900 dark:text-white';
  let paddingClass = 'p-0'; // Default no padding for plain text in modal

  if (hasBg) {
    if (contentLength < 60) {
        containerMinHeight = '250px'; 
        fontSizeClass = `${post.textColor || 'text-white'} text-3xl md:text-5xl text-center leading-tight`;
        paddingClass = 'p-10';
    } else if (contentLength < 150) {
        containerMinHeight = '350px';
        fontSizeClass = `${post.textColor || 'text-white'} text-2xl md:text-3xl text-center leading-snug`;
        paddingClass = 'p-12';
    } else {
        containerMinHeight = '450px';
        fontSizeClass = `${post.textColor || 'text-white'} text-xl md:text-2xl text-center leading-relaxed`;
        paddingClass = 'p-14';
    }
  }

  return createPortal(
    <div className="fixed inset-0 z-[10000] bg-black/90 flex items-center justify-center animate-fade-in overflow-hidden backdrop-blur-md">

      <div className="w-full h-full md:h-[95vh] md:max-w-6xl md:rounded-[3rem] bg-white dark:bg-[#0a0c10] flex flex-col md:flex-row overflow-hidden relative shadow-2xl">

        {/* Mobile Header */}
        <div className="flex items-center justify-between px-4 md:hidden z-[101] bg-black/40 backdrop-blur-xl border-b border-white/10 h-16 shrink-0">
           <button onClick={onClose} className="p-2 text-white">
