             <button onClick={handleSave} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasSaved ? 'bg-yellow-500 text-white' : 'bg-black/40 text-white'}`}>
                {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
