             </div>
             {!isOwner && (
               <button 
                 onClick={handleFollow}
                 className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 ${isFollowing ? 'bg-gray-100 dark:bg-white/5 text-gray-500' : 'bg-blue-600 text-white shadow-xl shadow-blue-500/20'}`}
