               </div>
             )}

             <div 
               className={`rounded-[2.5rem] flex flex-col items-center justify-center transition-all duration-500
                 ${post.fontFamily || 'font-sans'}
                 ${hasBg ? `${post.backgroundColor} ${post.textColor || 'text-white'} shadow-inner` : 'w-full'}
