                <p className={`font-black leading-snug whitespace-pre-wrap break-words w-full ${fontSizeClass}`}>{post.content}</p>
                <div className={`text-[8px] font-black uppercase tracking-[0.2em] pt-8 mt-4 border-t w-full opacity-30 ${hasBg ? 'border-white/20' : 'border-gray-100'}`}>
                   Publicado em {new Date(post.timestamp).toLocaleDateString()}
