import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";

// Função robusta para capturar variáveis de ambiente do Vite ou Process
const getEnvVar = (key: string) => {
  if (typeof import.meta !== 'undefined' && (import.meta as any).env && (import.meta as any).env[key]) {
    return (import.meta as any).env[key];
  }
  if (typeof process !== 'undefined' && process.env && process.env[key]) {
    return process.env[key];
  }
  return '';
};

const firebaseConfig = {
  apiKey: getEnvVar('VITE_FIREBASE_API_KEY'),
  authDomain: getEnvVar('VITE_FIREBASE_AUTH_DOMAIN'),
  projectId: getEnvVar('VITE_FIREBASE_PROJECT_ID'),
  storageBucket: getEnvVar('VITE_FIREBASE_STORAGE_BUCKET'),
  messagingSenderId: getEnvVar('VITE_FIREBASE_MESSAGING_SENDER_ID'),
  appId: getEnvVar('VITE_FIREBASE_APP_ID')
};

// Verifica se as chaves essenciais estão presentes
export const isFirebaseConfigured = !!(
  firebaseConfig.apiKey && 
  firebaseConfig.projectId &&
  firebaseConfig.apiKey !== 'undefined' &&
  firebaseConfig.apiKey !== ''
);

let app;
let auth: any;
let db: any;
let storage: any;

if (isFirebaseConfigured) {
  try {
    app = !getApps().length ? initializeApp(firebaseConfig) : getApp();
    auth = getAuth(app);
    db = getFirestore(app);
    storage = getStorage(app);
    console.log("🔥 Firebase Cloud Conectado:", firebaseConfig.projectId);
  } catch (error) {
    console.error("❌ Erro ao conectar ao Firebase:", error);
  }
} else {
  console.warn("⚠️ Firebase não configurado. O App está operando em MODO LOCAL (LocalStorage).");
}

export { auth, db, storage };
export default app;

