export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const useFirestore = () => isFirebaseConfigured && db;

// --- AUTHENTICATION ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Busca perfil direto pelo ID no Firestore
      const userDoc = await findUserById(firebaseUser.uid);
      if (userDoc) return userDoc;

      // Se não existe o documento mas o auth sim, cria o perfil básico
      const newUser = {
        id: firebaseUser.uid,
        email: firebaseUser.email || email,
        firstName: 'Usuário',
        lastName: 'Novo',
        userType: UserType.STANDARD,
        phone: '',
        documentId: '',
        birthDate: Date.now(),
        followers: [],
        followedUsers: [],
        balance: 0,
        profilePicture: DEFAULT_PROFILE_PIC
      } as User;
      await setDoc(doc(db, 'profiles', firebaseUser.uid), newUser);
      return newUser;
    } catch (error: any) {
      console.error("Firebase Login Error:", error);
      throw new Error('Email ou senha inválidos no sistema cloud.');
    }
  } else {
    const users = await getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado (Modo Local).');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = `user-${Date.now()}`;

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      console.error("Firebase Register Error:", error);
      throw new Error(error.message || 'Erro ao criar conta cloud.');
    }
  } else {
    const users = await getUsers();
    if (users.some(u => u.email === userData.email)) {
      throw new Error('Email já cadastrado (Local).');
    }
  }

  const newUser: User = {
    id: uid,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl
  };

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), newUser);
      if (newUser.userType === UserType.CREATOR) {
          const storeId = `store-${Date.now()}`;
          const newStore = { id: storeId, professorId: uid, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] };
          await setDoc(doc(db, 'stores', storeId), newStore);
          await updateDoc(doc(db, 'profiles', uid), { storeId });
      }
  } else {
      const users = await getUsers();
      if (newUser.userType === UserType.CREATOR) {
          const storeId = `store-${Date.now()}`;
          newUser.storeId = storeId;
          const stores = JSON.parse(localStorage.getItem(STORES_KEY) || '[]');
          stores.push({ id: storeId, professorId: uid, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] });
          localStorage.setItem(STORES_KEY, JSON.stringify(stores));
      }
      saveUsers([...users, newUser]);
  }

  return newUser;
};

// --- DATA ACCESS METHODS ---

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
      try {
          const docRef = doc(db, 'profiles', userId);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) return { ...docSnap.data() } as User;

          // Fallback: se o ID não for a chave do documento, tentar query (legado)
          const q = query(collection(db, 'profiles'), where('id', '==', userId));
          const snap = await getDocs(q);
          if (!snap.empty) return snap.docs[0].data() as User;
      } catch (e) {
          console.error("Firestore error finding user:", e);
      }
  }
  const users = await getUsers();
  return users.find(u => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    const snapshot = await getDocs(collection(db, 'profiles'));
    return snapshot.docs.map(d => ({ ...d.data() } as User));
  }
  const usersJson = localStorage.getItem(USERS_KEY);
  return usersJson ? JSON.parse(usersJson) : [];
};

export const saveUsers = (users: User[]) => {
  localStorage.setItem(USERS_KEY, JSON.stringify(users));
};

export const updateUser = async (updatedUser: User) => {
  if (useFirestore()) {
      const docRef = doc(db, 'profiles', updatedUser.id);
      await setDoc(docRef, updatedUser, { merge: true });
  } else {
      let users = await getUsers();
      users = users.map(user => user.id === updatedUser.id ? updatedUser : user);
      saveUsers(users);
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
      try {
          const q = query(collection(db, 'posts'), orderBy('timestamp', 'desc'));
          const snapshot = await getDocs(q);
          return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Post));
      } catch (e) {
          const snapshot = await getDocs(collection(db, 'posts'));
          return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Post));
      }
  }
  const postsJson = localStorage.getItem(POSTS_KEY);
  return postsJson ? JSON.parse(postsJson) : [];
};

export const addPost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), post);
  } else {
      const posts = await getPosts();
      savePosts([post, ...posts]);
  }
};

export const savePosts = (posts: Post[]) => {
  localStorage.setItem(POSTS_KEY, JSON.stringify(posts));
};

export const updatePost = async (updatedPost: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', updatedPost.id), updatedPost, { merge: true });
  } else {
      let posts = await getPosts();
      posts = posts.map(post => post.id === updatedPost.id ? updatedPost : post);
      savePosts(posts);
  }
};

export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
      const snapshot = await getDocs(collection(db, 'chats'));
      const all = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as ChatConversation));
      return userId ? all.filter(c => c.participants.includes(userId)) : all;
  }
  const chatsJson = localStorage.getItem(CHATS_KEY);
  const chats = chatsJson ? JSON.parse(chatsJson) : [];
  if (userId) return chats.filter((c: any) => c.participants.includes(userId));
  return chats;
};

export const saveChats = (chats: ChatConversation[]) => {
  localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
      const chatRef = doc(db, 'chats', chatId);
      const chatSnap = await getDoc(chatRef);
      if (chatSnap.exists()) {
          const data = chatSnap.data() as ChatConversation;
          const messages = [...(data.messages || []), msg];
          await updateDoc(chatRef, { messages });
      }
  } else {
      const chats = await getChats();
      const chat = chats.find(c => c.id === chatId);
      if (chat) {
        chat.messages.push(msg);
        saveChats(chats);
      }
  }
};

export const getStores = async (): Promise<Store[]> => {
  if (useFirestore()) {
      const snapshot = await getDocs(collection(db, 'stores'));
      return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Store));
  }
  const storesJson = localStorage.getItem(STORES_KEY);
  return storesJson ? JSON.parse(storesJson) : [];
};

export const findStoreById = async (storeId: string): Promise<Store | undefined> => {
    if (useFirestore()) {
        const snap = await getDoc(doc(db, 'stores', storeId));
        if (snap.exists()) return snap.data() as Store;
    }
    const stores = await getStores();
    return stores.find(s => s.id === storeId);
};

export const getProducts = async (): Promise<Product[]> => {
