// --- MISC HELPERS (HIBRIDOS) ---

export const getCart = (): CartItem[] => {
  const cartJson = localStorage.getItem(CART_KEY);
  return cartJson ? JSON.parse(cartJson) : [];
};
export const saveCart = (cart: CartItem[]) => localStorage.setItem(CART_KEY, JSON.stringify(cart));
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existingItem = cart.find(item => item.productId === productId && item.selectedColor === selectedColor);
  if (existingItem) existingItem.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) cart = cart.filter(item => item.productId !== productId);
  else {
    const item = cart.find(item => item.productId === productId);
    if (item) item.quantity = quantity;
  }
  saveCart(cart);
};
export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(item => item.productId !== productId);
  saveCart(cart);
};
export const clearCart = () => saveCart([]);

export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
    if (useFirestore()) {
        const q = query(collection(db, 'notifications'), where('recipientId', '==', userId));
        const snap = await getDocs(q);
        return snap.docs.map(d => ({ id: d.id, ...d.data() } as Notification));
    }
    const notificationsJson = localStorage.getItem(NOTIFICATIONS_KEY);
    const all = notificationsJson ? JSON.parse(notificationsJson) : [];
    return all.filter((n: any) => n.recipientId === userId);
};

export const createNotification = async (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) return;
  const newNotification = { ...notificationData, id: generateUUID(), isRead: false };
  if (useFirestore()) {
      await setDoc(doc(db, 'notifications', newNotification.id), newNotification);
  } else {
      const all = JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || '[]');
      localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify([newNotification, ...all]));
  }
};

export const markNotificationsAsRead = async (userId: string) => {
    if (useFirestore()) {
        const q = query(collection(db, 'notifications'), where('recipientId', '==', userId), where('isRead', '==', false));
        const snap = await getDocs(q);
        for (const d of snap.docs) {
            await updateDoc(doc(db, 'notifications', d.id), { isRead: true });
        }
    } else {
        const all = JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || '[]');
        all.forEach((n: any) => { if (n.recipientId === userId) n.isRead = true; });
        localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(all));
    }
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const user = await findUserById(userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    await updateUser(user);
    return true;
  }
  return false;
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
    await updatePost(post);
  }
};

export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const current = await findUserById(currentUserId);
  const target = await findUserById(userIdToFollow);
  if (current && target) {
    if (current.followedUsers.includes(userIdToFollow)) {
      current.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(userIdToFollow);
      target.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }
    await updateUser(current);
    await updateUser(target);
  }
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const chats = await getChats();
  let chat = chats.find(c => c.type !== ChatType.GROUP && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    if (useFirestore()) await setDoc(doc(db, 'chats', chat.id), chat);
    else saveChats([...chats, chat]);
  }
  return chat;
};

