export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
      try {
          const docRef = doc(db, 'profiles', userId);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) return { ...docSnap.data() } as User;

          // Fallback: se o ID não for a chave do documento, tentar query (legado)
          const q = query(collection(db, 'profiles'), where('id', '==', userId));
          const snap = await getDocs(q);
          if (!snap.empty) return snap.docs[0].data() as User;
      } catch (e) {
          console.error("Firestore error finding user:", e);
      }
  }
  const users = await getUsers();
  return users.find(u => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    const snapshot = await getDocs(collection(db, 'profiles'));
    return snapshot.docs.map(d => ({ ...d.data() } as User));
  }
  const usersJson = localStorage.getItem(USERS_KEY);
  return usersJson ? JSON.parse(usersJson) : [];
};

