    await updateUser(user);
    return true;
  }
  return false;
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
    await updatePost(post);
  }
};

export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const current = await findUserById(currentUserId);
  const target = await findUserById(userIdToFollow);
  if (current && target) {
    if (current.followedUsers.includes(userIdToFollow)) {
      current.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(userIdToFollow);
      target.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }
    await updateUser(current);
    await updateUser(target);
  }
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const chats = await getChats();
  let chat = chats.find(c => c.type !== ChatType.GROUP && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    if (useFirestore()) await setDoc(doc(db, 'chats', chat.id), chat);
    else saveChats([...chats, chat]);
  }
  return chat;
};

export const startPrivateChat = async (userId1: string, userId2: string) => {
    const chat = await getOrCreateConversation(userId1, userId2);
    return chat.id;
};

export const deleteMessage = async (chatId: string, messageId: string, hard?: boolean) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
        const msg = chat.messages.find(m => m.id === messageId);
        if (msg) {
            msg.isDeleted = true;
            msg.text = undefined;
            msg.imageUrl = undefined;
            if (useFirestore()) await updateDoc(doc(db, 'chats', chatId), { messages: chat.messages });
            else saveChats(chats);
        }
    }
};

