export const processAdInvestment = async (userId: string, amount: number, description: string): Promise<boolean> => {
    if(await updateUserBalance(userId, -amount)) {
        await createTransaction({ id: generateUUID(), userId, type: TransactionType.PURCHASE, amount, description: `Ads: ${description}`, timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
    return false;
};

export const processDonation = async (fromId: string, toId: string, amount: number, message: string): Promise<boolean> => {
    if(await updateUserBalance(fromId, -amount)) {
        await updateUserBalance(toId, amount);
        await createTransaction({ id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Doação para ${toId}`, timestamp: Date.now(), status: 'COMPLETED' });
        await createTransaction({ id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Recebido de ${fromId}`, timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
    return false;
};

export const handleWalletTransaction = async (userId: string, amount: number, type: 'deposit' | 'withdraw'): Promise<boolean> => {
    if (type === 'withdraw') {
        if (await updateUserBalance(userId, -amount)) {
            await createTransaction({ id: generateUUID(), userId, type: TransactionType.WITHDRAWAL, amount, description: 'Saque solicitado', timestamp: Date.now(), status: 'PENDING' });
            return true;
        }
        return false;
    } else {
        await updateUserBalance(userId, amount);
        await createTransaction({ id: generateUUID(), userId, type: TransactionType.DEPOSIT, amount, description: 'Depósito via Cripto/Card', timestamp: Date.now(), status: 'COMPLETED' });
        return true;
    }
};

