export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const products = await getProducts();
  const stores = await getStores();
  const newSales: AffiliateSale[] = [];

  for (const item of cartItems) {
    const product = products.find(p => p.id === item.productId);
    if (!product) continue;
    const store = stores.find(s => s.id === product.storeId);
    if (!store) continue;

    const itemTotal = product.price * item.quantity;
    const netRevenue = itemTotal * (1 - product.affiliateCommissionRate);
    await updateUserBalance(store.professorId, netRevenue);

    let commissionEarned = 0;
    if (affiliateUserId) {
        commissionEarned = itemTotal * product.affiliateCommissionRate;
        await updateUserBalance(affiliateUserId, commissionEarned);
        await createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, timestamp: Date.now() });
    }

    const newSale: AffiliateSale = {
      id: generateUUID(),
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned,
      saleAmount: itemTotal,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      isRated: false,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl,
      isDropshipping: product.isDropshipping,
      supplierCost: product.originalPrice ? product.originalPrice * item.quantity : undefined
    };
    newSales.push(newSale);
  }

  if (useFirestore()) {
      for (const sale of newSales) await setDoc(doc(db, 'affiliate_sales', sale.id), sale);
  } else {
      const allSales = await getAffiliateSales();
      saveAffiliateSales([...allSales, ...newSales]);
  }
  clearCart();
  return true;
};

export const updateUserStatus = async (userId: string, isOnline: boolean) => {
    if (useFirestore()) {
        try {
            await updateDoc(doc(db, 'profiles', userId), { isOnline, lastSeen: Date.now() });
        } catch (e) {}
    } else {
        const users = await getUsers();
        const user = users.find(u => u.id === userId);
        if (user) {
            user.isOnline = isOnline;
            user.lastSeen = Date.now();
            saveUsers(users);
        }
    }
};

