export const pinPost = async (postId: string, userId: string) => {
  if (useFirestore()) {
    const allPosts = await getPosts();
    for (const p of allPosts.filter(p => p.userId === userId)) {
        if (p.isPinned) await updateDoc(doc(db, 'posts', p.id), { isPinned: false });
