    await updateDoc(doc(db, 'posts', postId), { isPinned: true });
  } else {
    let posts = await getPosts();
    posts.forEach(p => {
      if (p.userId === userId) p.isPinned = (p.id === postId);
    });
    savePosts(posts);
  }
  return true;
};

