    const all = snap.docs.map(d => ({ id: d.id, ...d.data() } as ChatConversation));
    return userId ? all.filter(c => c.participants.includes(userId)) : all;
  }
  const all = JSON.parse(localStorage.getItem(CHATS_KEY) || '[]');
  return userId ? all.filter((c: any) => c.participants.includes(userId)) : all;
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), msg] });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages.push(msg);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

