  if (!localStorage.getItem(PRODUCTS_KEY)) localStorage.setItem(PRODUCTS_KEY, JSON.stringify(DEFAULT_PRODUCTS));
  if (!localStorage.getItem(AFFILIATE_SALES_KEY)) localStorage.setItem(AFFILIATE_SALES_KEY, JSON.stringify(DEFAULT_AFFILIATE_SALES));
