  { id: 'font-slab', class: 'font-serif font-black tracking-tight', label: 'Manchete' },
  { id: 'font-script', class: 'font-serif italic font-light', label: 'Carta' },
  { id: 'font-modern', class: 'font-sans font-medium tracking-[0.2em]', label: 'Moderna' },
  { id: 'font-tight', class: 'font-sans font-bold tracking-tighter', label: 'Compacta' },
  { id: 'font-tall', class: 'font-sans font-light leading-loose', label: 'Alta' },
  { id: 'font-retro', class: 'font-mono font-black uppercase text-shadow-sm', label: 'Retro' },
  { id: 'font-elegant', class: 'font-serif font-medium tracking-wide', label: 'Elegante' },
  { id: 'font-impact', class: 'font-sans font-extrabold uppercase italic', label: 'Impacto' },
  { id: 'font-soft', class: 'font-sans font-semibold rounded-lg', label: 'Suave' },
  { id: 'font-cyber', class: 'font-mono uppercase tracking-[0.3em] font-light', label: 'Cyber' },
  { id: 'font-news', class: 'font-serif font-bold leading-tight', label: 'Jornal' },
  { id: 'font-comic', class: 'font-sans font-extrabold tracking-wide', label: 'Cartoon' },
];

type StyleTab = 'bg' | 'text' | 'font';

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');

  // Customizações de Texto
  const [selectedBg, setSelectedBg] = useState(BG_OPTIONS[0]);
  const [selectedTextColor, setSelectedTextColor] = useState(TEXT_COLORS[0]);
  const [selectedFont, setSelectedFont] = useState(FONT_OPTIONS[0]);

  const [showStyleTools, setShowStyleTools] = useState(false);
  const [activeStyleTab, setActiveStyleTab] = useState<StyleTab>('bg');

  // Mídia
  const [imageUrl, setImageUrl] = useState('');
  const [imageFile, setImageFile] = useState<File | null>(null);

  // Reel Data
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);
  const [reelMeta, setReelMeta] = useState<{audioTrackId?: string, aiPrompt?: string, filter?: string}>({});

  const [showRecordModal, setShowRecordModal] = useState(false);

  // Live Data
  const [liveTitle, setLiveTitle] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('0');

  // Configs
  const [selectedGroup, setSelectedGroup] = useState<{id?: string, name: string}>({ name: 'Feed Geral' });
  const [myGroups, setMyGroups] = useState<ChatConversation[]>([]);
  const [showGroupSelector, setShowGroupSelector] = useState(false);
  const [disableComments, setDisableComments] = useState(false);

  const [loading, setLoading] = useState(false);
  const [statusText, setStatusText] = useState('Publicar');

  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;
  const isProfessor = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (!selectedBg) return;
    if (selectedBg.id === 'transparent' || selectedBg.id === 'white') {
        const color = TEXT_COLORS.find(c => c.id === 'text-gray-900');
        if (color) setSelectedTextColor(color);
    } else {
        const color = TEXT_COLORS.find(c => c.id === 'text-white');
        if (color) setSelectedTextColor(color);
    }
  }, [selectedBg]);

  useEffect(() => {
    const loadMyGroups = async () => {
       const allChats = await getChats();
       const groups = allChats.filter(c => c.type === 'GROUP' && c.participants.includes(currentUser.id));
       setMyGroups(groups);
    };
    loadMyGroups();
  }, [currentUser.id]);

  const resetForm = () => {
    setIsExpanded(false);
    setPostType(PostType.TEXT);
    setContent('');
    setImageUrl('');
    setReelUrl('');
    setImageFile(null);
    setReelFile(null);
    setReelMeta({});
    setLiveTitle('');
    setIsLivePaid(false);
    setLivePrice('0');
    setSelectedBg(BG_OPTIONS[0]);
    setSelectedTextColor(TEXT_COLORS[0]);
    setSelectedFont(FONT_OPTIONS[0]);
    setShowStyleTools(false);
    setSelectedGroup({ name: 'Feed Geral' });
    setDisableComments(false);
    setStatusText('Publicar');
  };

  const switchToType = (type: PostType) => {
      setPostType(type);
      if (type === PostType.TEXT) {
          setImageFile(null); setImageUrl('');
          setReelFile(null); setReelUrl('');
      } else if (type === PostType.IMAGE) {
          setReelFile(null); setReelUrl('');
      } else if (type === PostType.REEL) {
          setImageFile(null); setImageUrl('');
      }
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setImageUrl(URL.createObjectURL(file));
      switchToType(PostType.IMAGE);
      setShowStyleTools(false);
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file));
      switchToType(PostType.REEL);
    }
  };

  const handleRecordedReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setReelFile(videoBlob);
    setReelUrl(URL.createObjectURL(videoBlob));
    setReelMeta({ audioTrackId, aiPrompt, filter });
    switchToType(PostType.REEL);
    setShowRecordModal(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (postType !== PostType.LIVE && !content.trim() && !imageFile && !reelFile) return;
    if (postType === PostType.LIVE && !liveTitle.trim()) {
        alert("Digite um título para sua Live.");
        return;
    }

    setLoading(true);

    try {
      let finalImageUrl = imageUrl;
      let finalReelUrl = reelUrl;

      if (postType === PostType.IMAGE && imageFile) {
        setStatusText('Enviando Imagem...');
        finalImageUrl = await uploadFile(imageFile, 'posts');
        if (!finalImageUrl) throw new Error("Falha no upload da imagem");
      }

      if (postType === PostType.REEL && reelFile) {
        setStatusText('Enviando Vídeo...');
        finalReelUrl = await uploadFile(reelFile, 'reels');
        if (!finalReelUrl) throw new Error("Falha no upload do vídeo");
      }

      setStatusText('Finalizando...');

      // Construção rigorosa do objeto Reel para evitar undefined
      let reelData = undefined;
      if (postType === PostType.REEL && finalReelUrl) {
          reelData = {
              videoUrl: finalReelUrl,
              description: content || '',
              ...(reelMeta.audioTrackId ? { audioTrackId: reelMeta.audioTrackId } : {}),
              ...(reelMeta.aiPrompt ? { aiEffectPrompt: reelMeta.aiPrompt } : {}),
              ...(reelMeta.filter ? { filter: reelMeta.filter } : {})
          };
      }

      const postData: Post = {
        id: isEditing ? postId! : generateUUID(),
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        type: postType,
        timestamp: Date.now(),
        content: content,
        imageUrl: postType === PostType.IMAGE ? finalImageUrl : undefined,
        groupId: selectedGroup.id || undefined, // CRITICAL FIX: Ensure groupId is not passed if null/undefined
        groupName: selectedGroup.id ? selectedGroup.name : undefined,
        backgroundColor: selectedBg.class,
        textColor: selectedTextColor.class,
        fontFamily: selectedFont.class,
        disableComments: disableComments,
        reel: reelData,
        liveStream: postType === PostType.LIVE ? {
            title: liveTitle,
            description: content,
            isPaid: isLivePaid,
            price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: []
      };

      if (isEditing) await updatePost(postData);
      else await addPost(postData);

      onPostCreated();
      if (!isEditing) resetForm();
      if (onCancel) onCancel();

    } catch (err: any) {
      console.error(err);
      alert('Erro ao salvar postagem: ' + (err.message || 'Verifique sua conexão.'));
    } finally {
      setLoading(false);
      setStatusText('Publicar');
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-4 shadow-sm animate-fade-in">
         <div className="flex items-center gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shadow-sm" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-sm hover:bg-gray-100 dark:hover:bg-white/10 transition-all">
              {isProfessor ? "Anuncie ou ensine algo hoje..." : "No que você está pensando?"}
            </button>
         </div>
         <div className="flex gap-4 px-2 border-t border-gray-50 dark:border-white/5 pt-4">
            <button onClick={() => { setIsExpanded(true); switchToType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <PhotoIcon className="h-5 w-5 text-green-500" /> Foto
            </button>
            <button onClick={() => { setIsExpanded(true); switchToType(PostType.REEL); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <FilmIcon className="h-5 w-5 text-purple-500" /> Reel
            </button>
            <button onClick={() => { setIsExpanded(true); switchToType(PostType.LIVE); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <SignalIcon className="h-5 w-5 text-red-500" /> Ao Vivo
            </button>
            <button onClick={() => { setIsExpanded(true); switchToType(PostType.TEXT); setShowStyleTools(true); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <SwatchIcon className="h-5 w-5 text-blue-500" /> Cor
            </button>
         </div>
      </div>
    );
  }

  const isBgSelected = selectedBg.id !== 'transparent';

  return (
    <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-6 md:p-8 border dark:border-white/5 animate-fade-in relative overflow-visible">
      {/* Header do Modal */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
           <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover" />
           <div className="flex flex-col">
              <h3 className="font-black text-gray-900 dark:text-white text-sm">{currentUser.firstName} {currentUser.lastName}</h3>

              {/* Selector de Destino */}
              <div className="relative">
                 <button 
                   type="button"
                   onClick={() => setShowGroupSelector(!showGroupSelector)}
                   className="flex items-center gap-1.5 bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded-lg text-[9px] font-bold text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/20 transition-all"
                 >
                    {selectedGroup.id ? <UserGroupIcon className="h-3 w-3" /> : <GlobeAmericasIcon className="h-3 w-3" />}
                    <span className="max-w-[100px] truncate">{selectedGroup.name}</span>
                    <ChevronDownIcon className="h-3 w-3" />
                 </button>

                 {showGroupSelector && (
                   <div className="absolute top-full left-0 mt-2 w-56 bg-white dark:bg-[#1a1c23] border border-gray-100 dark:border-white/10 rounded-2xl shadow-2xl z-[150] p-2 animate-fade-in">
                      <button 
                       onClick={() => { setSelectedGroup({ name: 'Feed Geral' }); setShowGroupSelector(false); }}
                       className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                      >
                         <GlobeAmericasIcon className="h-4 w-4 text-gray-400" />
                         <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">Feed Geral</span>
                      </button>
                      {myGroups.map(group => (
                        <button 
                         key={group.id}
                         onClick={() => { setSelectedGroup({ id: group.id, name: group.groupName! }); setShowGroupSelector(false); }}
                         className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                        >
                           <UserGroupIcon className="h-4 w-4 text-blue-600" />
                           <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{group.groupName}</span>
                        </button>
                      ))}
                   </div>
                 )}
              </div>
           </div>
        </div>

        <div className="flex items-center gap-2">
            {/* Professor Control: Disable Comments */}
            {isProfessor && (
                <button 
                    type="button"
                    onClick={() => setDisableComments(!disableComments)}
                    className={`p-2 rounded-full transition-all ${disableComments ? 'bg-red-500 text-white' : 'bg-gray-100 dark:bg-white/10 text-gray-400'}`}
                    title={disableComments ? "Comentários Desativados" : "Permitir Comentários"}
                >
                    {disableComments ? <LockClosedIcon className="h-5 w-5" /> : <LockOpenIcon className="h-5 w-5" />}
                </button>
            )}
            <button onClick={resetForm} className="p-2 bg-gray-100 dark:bg-white/10 rounded-full hover:bg-gray-200 dark:hover:bg-white/20 transition-all">
                <XMarkIcon className="h-5 w-5 text-gray-500" />
            </button>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">

        {/* TEXT AREA COM ESTILOS */}
        {postType === PostType.TEXT && (
          <div className={`relative transition-all duration-500 rounded-[2rem] overflow-hidden flex items-center justify-center ${isBgSelected ? `${selectedBg.class} min-h-[300px]` : 'bg-gray-50 dark:bg-white/5 min-h-[150px]'}`}>
             <textarea 
               value={content} 
               onChange={e => { setContent(e.target.value); }} 
               className={`w-full p-6 bg-transparent outline-none resize-none text-center placeholder:opacity-50 ${isBgSelected ? `${selectedTextColor.class} ${selectedFont.class} text-2xl md:text-3xl leading-tight py-20` : 'text-gray-900 dark:text-white text-lg font-medium'}`}
               placeholder={selectedGroup.id ? `Olá ${selectedGroup.name}...` : (isProfessor ? "Compartilhe seu conhecimento..." : "No que você está pensando?")}
               style={{ height: '100%' }}
             />

             {isBgSelected && (
               <button 
                 type="button" 
                 onClick={() => { setSelectedBg(BG_OPTIONS[0]); setSelectedTextColor(TEXT_COLORS[0]); setShowStyleTools(false); }}
                 className="absolute top-4 right-4 bg-black/20 hover:bg-black/40 text-white p-2 rounded-full backdrop-blur-md transition-all"
               >
                 <XMarkIcon className="h-4 w-4" />
               </button>
             )}
          </div>
        )}

        {/* FERRAMENTAS DE ESTILO DE TEXTO */}
        {postType === PostType.TEXT && showStyleTools && (
           <div className="space-y-4 animate-slide-down bg-gray-50 dark:bg-white/5 p-4 rounded-3xl border border-gray-100 dark:border-white/5">
              <div className="flex gap-2 mb-2 border-b border-gray-200 dark:border-white/10 pb-2 overflow-x-auto no-scrollbar">
                 <button type="button" onClick={() => setActiveStyleTab('bg')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'bg' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Fundo</button>
                 <button type="button" onClick={() => setActiveStyleTab('text')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'text' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Cor Texto</button>
                 <button type="button" onClick={() => setActiveStyleTab('font')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'font' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Fonte</button>
              </div>

              {activeStyleTab === 'bg' && (
                <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                    {BG_OPTIONS.map(bg => (
                       <button
                         key={bg.id}
                         type="button"
                         onClick={() => setSelectedBg(bg)}
                         className={`w-10 h-10 rounded-full border-2 flex-shrink-0 transition-all ${bg.id === 'transparent' ? 'bg-white border-dashed border-gray-400' : bg.class} ${selectedBg.id === bg.id ? 'border-blue-600 scale-110 shadow-lg' : 'border-transparent'}`}
                         title={bg.label}
                       >
                         {bg.id === 'transparent' && <span className="text-[8px] font-black text-gray-400">NONE</span>}
                       </button>
                    ))}
                </div>
              )}

              {activeStyleTab === 'text' && (
                <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                    {TEXT_COLORS.map(color => (
                       <button
                         key={color.id}
                         type="button"
                         onClick={() => setSelectedTextColor(color)}
                         className={`w-10 h-10 rounded-full border-2 flex-shrink-0 transition-all flex items-center justify-center bg-gray-800 ${selectedTextColor.id === color.id ? 'border-blue-600 scale-110 shadow-lg' : 'border-gray-600'}`}
                         title={color.label}
                       >
                         <div className={`w-6 h-6 rounded-full ${color.class.replace('text-', 'bg-')}`}></div>
                       </button>
                    ))}
                </div>
              )}

              {activeStyleTab === 'font' && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                    {FONT_OPTIONS.map(font => (
                       <button
                         key={font.id}
                         type="button"
                         onClick={() => setSelectedFont(font)}
                         className={`px-4 py-2 rounded-xl text-sm border transition-all whitespace-nowrap ${font.class} ${selectedFont.id === font.id ? 'bg-white dark:bg-white/10 border-blue-600 text-blue-600 shadow-md' : 'border-transparent text-gray-500 hover:bg-white/50'}`}
                       >
                          {font.label}
                       </button>
                    ))}
                </div>
              )}
           </div>
        )}

        {/* UPLOAD DE IMAGEM */}
        {postType === PostType.IMAGE && (
          <div className="relative">
             <div onClick={() => imageInputRef.current?.click()} className="w-full h-80 border-4 border-dashed rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 transition-all overflow-hidden bg-gray-50 dark:bg-white/5 group">
               {imageUrl ? (
                 <>
                   <img src={imageUrl} className="w-full h-full object-cover" />
                   <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity backdrop-blur-sm">
                      <span className="text-white font-black text-xs uppercase bg-black/50 px-4 py-2 rounded-xl backdrop-blur-md">Trocar Imagem</span>
                   </div>
                 </>
               ) : (
                 <>
                   <PhotoIcon className="h-12 w-12 text-gray-300 group-hover:text-blue-500 transition-colors" />
                   <p className="text-gray-400 font-black text-xs uppercase mt-2">Clique para carregar</p>
                 </>
               )}
               <input type="file" ref={imageInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
             </div>

             <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full mt-4 p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Adicione uma legenda..." 
               rows={2}
             />
          </div>
        )}

        {/* CONFIGURAÇÃO DE LIVE */}
        {postType === PostType.LIVE && (
           <div className="space-y-6 animate-fade-in bg-red-50/50 dark:bg-red-900/10 p-6 rounded-[2.5rem] border border-red-100 dark:border-red-900/20">
              <div className="flex items-center gap-3 mb-2">
                 <div className="p-2 bg-red-600 rounded-lg text-white shadow-lg shadow-red-200 dark:shadow-none">
                    <SignalIcon className="h-6 w-6" />
                 </div>
                 <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Configurar Transmissão</h3>
              </div>

              <div className="space-y-4">
                 <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-1">Título da Aula</label>
                    <input 
                      type="text" 
                      value={liveTitle}
                      onChange={e => setLiveTitle(e.target.value)}
                      placeholder="Ex: Mentoria de Marketing Digital"
                      className="w-full p-4 bg-white dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-red-500 font-bold text-sm dark:text-white transition-all shadow-sm"
                    />
                 </div>

                 <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-1">Descrição</label>
                    <textarea 
                      value={content}
                      onChange={e => setContent(e.target.value)}
                      placeholder="Sobre o que será sua live?"
                      className="w-full p-4 bg-white dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-red-500 font-medium text-sm dark:text-white transition-all shadow-sm h-24 resize-none"
                    />
                 </div>

                 <div className="flex items-center justify-between bg-white dark:bg-white/5 p-4 rounded-2xl border border-gray-100 dark:border-white/5">
                    <div className="flex items-center gap-3">
                       <div className={`p-2 rounded-xl ${isLivePaid ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>
                          <BanknotesIcon className="h-5 w-5" />
                       </div>
                       <div>
                          <p className="text-sm font-black dark:text-white">Aula Paga?</p>
                          <p className="text-[10px] text-gray-400 font-bold uppercase">Cobrar entrada dos alunos</p>
                       </div>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                       <input type="checkbox" checked={isLivePaid} onChange={e => setIsLivePaid(e.target.checked)} className="sr-only peer" />
                       <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-500"></div>
                    </label>
                 </div>

                 {isLivePaid && (
                    <div className="animate-slide-down">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-1">Valor do Ingresso (USD)</label>
                       <div className="relative">
                          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">$</span>
                          <input 
                            type="number" 
                            value={livePrice}
                            onChange={e => setLivePrice(e.target.value)}
                            className="w-full pl-8 pr-4 py-4 bg-white dark:bg-white/5 rounded-2xl outline-none border-2 border-green-500 font-black text-lg dark:text-white transition-all shadow-sm"
                          />
                       </div>
                    </div>
                 )}
              </div>
           </div>
        )}

        {/* REELS AREA */}
        {postType === PostType.REEL && (
           <div className="space-y-4">
              {!reelUrl ? (
