// --- AUTENTICAÇÃO ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Tenta buscar o perfil no Firestore
      const userDoc = await findUserById(firebaseUser.uid);
      if (userDoc) return userDoc;

      // Se autenticou no Auth mas o documento não existe no Firestore, criamos um agora (Fallback de Sincronia)
      const newUser: User = {
        id: firebaseUser.uid,
        email: firebaseUser.email || email,
        firstName: firebaseUser.displayName?.split(' ')[0] || 'Usuário',
        lastName: firebaseUser.displayName?.split(' ').slice(1).join(' ') || 'CyBer',
        userType: UserType.STANDARD,
        phone: '',
        documentId: '',
        birthDate: Date.now(),
        followers: [],
        followedUsers: [],
        balance: 0,
        profilePicture: firebaseUser.photoURL || DEFAULT_PROFILE_PIC
      };
      await setDoc(doc(db, 'profiles', firebaseUser.uid), cleanData(newUser));
      return newUser;
    } catch (error: any) {
      console.error("Firebase Auth Error:", error);
      throw new Error(error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password' || error.code === 'auth/invalid-credential' 
        ? 'E-mail ou senha incorretos.' 
        : 'Falha na autenticação. Verifique sua conexão.');
    }
  } else {
    // Modo Local
    const users = await getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado localmente.');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      console.error("Firebase Register Error:", error);
      if (error.code === 'auth/email-already-in-use') throw new Error('Este e-mail já está em uso.');
      if (error.code === 'auth/weak-password') throw new Error('A senha é muito fraca.');
      throw new Error(error.message || 'Erro ao criar conta cloud.');
    }
  }

  // Objeto base garantindo que arrays e campos numéricos existam
  const newUser: User = {
    id: uid,
    userType: userData.userType || UserType.STANDARD,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone || '',
    documentId: userData.documentId || '',
    birthDate: typeof userData.birthDate === 'number' ? userData.birthDate : Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.credentials || '',
    bio: userData.bio || '', 
    verificationFileUrl: userData.verificationFileUrl || ''
  };

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));

      // Se for criador, gera a loja automaticamente
      if (newUser.userType === UserType.CREATOR) {
          const storeId = generateUUID();
          const newStore: Store = { 
            id: storeId, 
            professorId: uid, 
            name: `Loja de ${newUser.firstName}`, 
            description: 'Bem-vindo à minha vitrine oficial!', 
            productIds: [] 
          };
          await setDoc(doc(db, 'stores', storeId), cleanData(newStore));
          await updateDoc(doc(db, 'profiles', uid), { storeId: storeId });
          newUser.storeId = storeId;
      }
  } else {
      const users = await getUsers();
      saveUsers([...users, newUser]);
  }
  return newUser;
};

