export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
  if (useFirestore()) {
    try {
      const q = query(collection(db, 'notifications'), where('recipientId', '==', userId));
      const snap = await getDocs(q);
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Notification));
    } catch (e) { return []; }
  }
  const all = JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || '[]');
  return all.filter((n: any) => n.recipientId === userId);
};

export const createNotification = async (data: Omit<Notification, 'id' | 'isRead'>) => {
  if (data.recipientId === data.actorId) return;
  const notif = { ...data, id: generateUUID(), isRead: false };
  if (useFirestore()) await setDoc(doc(db, 'notifications', notif.id), cleanData(notif));
  else {
    const all = JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || '[]');
    localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify([notif, ...all]));
  }
};

export const markNotificationsAsRead = async (userId: string) => {
  if (useFirestore()) {
    try {
      const q = query(collection(db, 'notifications'), where('recipientId', '==', userId), where('isRead', '==', false));
      const snap = await getDocs(q);
      for (const d of snap.docs) await updateDoc(doc(db, 'notifications', d.id), { isRead: true });
    } catch (e) {}
  } else {
    const all = JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || '[]');
    localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(all.map((n: any) => n.recipientId === userId ? { ...n, isRead: true } : n)));
  }
};

