export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
    try {
      const docSnap = await getDoc(doc(db, 'profiles', userId));
      if (docSnap.exists()) {
          const data = docSnap.data();
          // Garante que ID e campos obrigatórios estejam presentes
          return { 
            ...data, 
            id: docSnap.id,
            followedUsers: data.followedUsers || [],
            followers: data.followers || [],
            balance: data.balance || 0
          } as User;
      }
    } catch (e) { 
      console.error("Firestore user fetch error", e); 
    }
  }
  const users = await getUsers();
  return users.find(u => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'profiles'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
};

export const saveUsers = (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users));

export const updateUser = async (user: User) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
  } else {
    const users = await getUsers();
    saveUsers(users.map(u => u.id === user.id ? user : u));
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
    try {
      const q = query(collection(db, 'posts'), orderBy('timestamp', 'desc'));
      const snap = await getDocs(q);
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post));
    } catch (e) { 
      const snap = await getDocs(collection(db, 'posts'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post)).sort((a,b) => b.timestamp - a.timestamp);
    }
  }
  return JSON.parse(localStorage.getItem(POSTS_KEY) || '[]');
};

export const addPost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify([post, ...posts]));
  }
};

export const updatePost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post), { merge: true });
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.map(p => p.id === post.id ? post : p)));
  }
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) {
      await deleteDoc(doc(db, 'posts', postId));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.filter(p => p.id !== postId)));
  }
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await updatePost(post);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && post.comments) {
    post.comments = post.comments.filter(c => c.id !== commentId);
    await updatePost(post);
  }
};

export const pinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  for (const p of posts) {
    if (p.userId === userId) {
      const wasPinned = p.isPinned;
      p.isPinned = p.id === postId;
      if (wasPinned !== p.isPinned) await updatePost(p);
    }
  }
  return true;
};

export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    // FIX: Using 'post' instead of 'p' which was undefined in this scope
    await updatePost(post);
  }
  return true;
};

