export const processProductPurchase = async (items: CartItem[], buyer: string, aff: string | null, addr?: any) => {
  const prods = await getProducts();
  const sales: AffiliateSale[] = [];
  for (const item of items) {
    const p = prods.find(x => x.id === item.productId);
    if (!p) continue;
    const sale: AffiliateSale = { id: generateUUID(), productId: p.id, buyerId: buyer, affiliateUserId: aff || '', storeId: p.storeId, commissionEarned: p.price * p.affiliateCommissionRate, saleAmount: p.price, timestamp: Date.now(), status: OrderStatus.WAITLIST };
    sales.push(sale);
  }
  if (useFirestore()) {
    for (const s of sales) await setDoc(doc(db, 'affiliate_sales', s.id), cleanData(s));
  } else {
    const all = await getAffiliateSales();
    localStorage.setItem(AFFILIATE_SALES_KEY, JSON.stringify([...sales, ...all]));
  }
  clearCart();
  return true;
};

