/**
 * Função Auxiliar: Remove valores 'undefined' e garante campos base para Firestore
 */
const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) {
    return obj.map(item => cleanData(item));
  } else if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      // Firestore não aceita undefined, apenas null ou campos omitidos
      if (val !== undefined) {
        newObj[key] = cleanData(val);
      }
    });
    return newObj;
  }
  return obj;
};

