export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Tenta buscar o perfil detalhado no Firestore
      const userDoc = await findUserById(firebaseUser.uid);
      if (userDoc) return userDoc;

      // Se autenticou mas não tem documento (raro, mas possível), cria um básico
      const newUser: User = {
        id: firebaseUser.uid,
        email: firebaseUser.email || email,
        firstName: 'Usuário',
        lastName: 'CyBer',
        userType: UserType.STANDARD,
        phone: '',
        documentId: '',
        birthDate: Date.now(),
        followers: [],
        followedUsers: [],
        balance: 0,
        profilePicture: DEFAULT_PROFILE_PIC
      };
      await setDoc(doc(db, 'profiles', firebaseUser.uid), cleanData(newUser));
      return newUser;
    } catch (error: any) {
      console.error("Firebase Login Error:", error);
      throw new Error('Email ou senha incorretos.');
    }
  } else {
    const users = await getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado localmente.');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      throw new Error(error.message || 'Erro ao criar conta cloud.');
    }
  }

  const newUser: User = {
    id: uid,
    userType: userData.userType || UserType.STANDARD,
    firstName: userData.firstName || '',
    lastName: userData.lastName || '',
    email: userData.email,
    phone: userData.phone || '',
    documentId: userData.documentId || '',
    birthDate: typeof userData.birthDate === 'number' ? userData.birthDate : Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.credentials || '',
    bio: userData.bio || '', 
    verificationFileUrl: userData.verificationFileUrl || ''
  };

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
      if (newUser.userType === UserType.CREATOR) {
          const storeId = generateUUID();
          const newStore: Store = { id: storeId, professorId: uid, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] };
          await setDoc(doc(db, 'stores', storeId), cleanData(newStore));
          await updateDoc(doc(db, 'profiles', uid), { storeId: storeId });
          newUser.storeId = storeId;
      }
  } else {
      const users = await getUsers();
      saveUsers([...users, newUser]);
  }
  return newUser;
};

// --- ACESSO A DADOS ---

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
    try {
      const docSnap = await getDoc(doc(db, 'profiles', userId));
      if (docSnap.exists()) {
          const data = docSnap.data();
          // GARANTIA DE MAPEAMENTO: Injeta o ID e garante campos padrão para evitar undefined na UI
          return { 
            id: docSnap.id,
            email: data.email || '',
            firstName: data.firstName || '',
            lastName: data.lastName || '',
            userType: data.userType || UserType.STANDARD,
            phone: data.phone || '',
            documentId: data.documentId || '',
            birthDate: data.birthDate || Date.now(),
            profilePicture: data.profilePicture || DEFAULT_PROFILE_PIC,
            followedUsers: data.followedUsers || [],
            followers: data.followers || [],
            balance: data.balance || 0,
            bio: data.bio || '',
            credentials: data.credentials || '',
            storeId: data.storeId || undefined,
            isAdmin: !!data.isAdmin,
            isVerified: !!data.isVerified,
            isOnline: !!data.isOnline,
            lastSeen: data.lastSeen || 0
          } as User;
      }
    } catch (e) { 
      console.error("Erro ao buscar perfil no Firestore:", e); 
    }
  }
  const users = await getUsers();
  return users.find(u => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'profiles'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as User));
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
};

export const saveUsers = (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users));

export const updateUser = async (user: User) => {
  if (useFirestore()) {
      // Usa cleanData para evitar erros de campos undefined no Firestore
      await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
  } else {
    const users = await getUsers();
    saveUsers(users.map(u => u.id === user.id ? user : u));
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
    try {
      const q = query(collection(db, 'posts'), orderBy('timestamp', 'desc'));
      const snap = await getDocs(q);
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post));
    } catch (e) { 
      const snap = await getDocs(collection(db, 'posts'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post)).sort((a,b) => b.timestamp - a.timestamp);
    }
  }
  return JSON.parse(localStorage.getItem(POSTS_KEY) || '[]');
};

export const addPost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify([post, ...posts]));
  }
};

export const updatePost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post), { merge: true });
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.map(p => p.id === post.id ? post : p)));
  }
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) {
      await deleteDoc(doc(db, 'posts', postId));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.filter(p => p.id !== postId)));
  }
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await updatePost(post);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && post.comments) {
    post.comments = post.comments.filter(c => c.id !== commentId);
    await updatePost(post);
  }
};

export const pinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  for (const p of posts) {
    if (p.userId === userId) {
      const wasPinned = p.isPinned;
      p.isPinned = p.id === postId;
      if (wasPinned !== p.isPinned) await updatePost(p);
    }
  }
  return true;
};

export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    await updatePost(post);
  }
  return true;
};

