export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'chats'));
      const all = snap.docs.map(d => ({ ...d.data(), id: d.id } as ChatConversation));
      return userId ? all.filter(c => c.participants.includes(userId)) : all;
    } catch (e) { return []; }
  }
  const all = JSON.parse(localStorage.getItem(CHATS_KEY) || '[]');
  return userId ? all.filter((c: any) => c.participants.includes(userId)) : all;
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), cleanData(msg)] });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages.push(msg);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const deleteMessage = async (chatId: string, messageId: string, hardDelete: boolean = false) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          if (hardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter(m => m !== null) as Message[];
      await updateDoc(doc(db, 'chats', chatId), { messages: updatedMessages });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages = chat.messages.map(m => {
        if (m.id === messageId) {
          if (hardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter(m => m !== null) as Message[];
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      await updateDoc(doc(db, 'chats', chatId), { messages: updatedMessages });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages = chat.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const startPrivateChat = async (u1: string, u2: string) => {
  const chats = await getChats();
  let chat = chats.find(c => c.type === ChatType.PRIVATE && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: generateUUID(), type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    if (useFirestore()) await setDoc(doc(db, 'chats', chat.id), cleanData(chat));
    else localStorage.setItem(CHATS_KEY, JSON.stringify([...chats, chat]));
  }
  return chat.id;
};

export const deleteChat = async (chatId: string) => {
  if (useFirestore()) await deleteDoc(doc(db, 'chats', chatId));
  else {
    const chats = (await getChats()).filter(c => c.id !== chatId);
    localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
  }
};

