export const toggleFollowUser = async (cur: string, target: string) => {
  const u1 = await findUserById(cur);
  const u2 = await findUserById(target);
  if (u1 && u2) {
    if (u1.followedUsers.includes(target)) {
      u1.followedUsers = u1.followedUsers.filter(i => i !== target);
      u2.followers = u2.followers.filter(i => i !== cur);
    } else {
      u1.followedUsers.push(target);
      u2.followers.push(cur);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: target, actorId: cur, timestamp: Date.now() });
    }
    await updateUser(u1);
    await updateUser(u2);
  }
};

export const getCart = (): CartItem[] => JSON.parse(localStorage.getItem(CART_KEY) || '[]');
export const clearCart = () => localStorage.setItem(CART_KEY, '[]');

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
      cart = cart.filter(item => item.productId !== productId);
  } else {
      const item = cart.find(item => item.productId === productId);
      if (item) item.quantity = quantity;
  }
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(item => item.productId !== productId);
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

