/**
 * MAPEADOR ROBUSTO: Garante que independente de como os dados estão no Firestore (camelCase ou snake_case),
 * o sistema consiga ler Nome, Foto, Saldo e Status.
 */
const mapUserData = (id: string, data: any): User => {
    return {
        id: id,
        userType: data.userType || data.user_type || UserType.STANDARD,
        firstName: data.firstName || data.first_name || data.displayName?.split(' ')[0] || 'Usuário',
        lastName: data.lastName || data.last_name || data.displayName?.split(' ').slice(1).join(' ') || 'CyBer',
        email: data.email || '',
        phone: data.phone || data.phone_number || '',
        documentId: data.documentId || data.document_id || '',
        birthDate: data.birthDate || data.birth_date || Date.now(),
        profilePicture: data.profilePicture || data.profile_picture || data.photoURL || DEFAULT_PROFILE_PIC,
        followedUsers: data.followedUsers || data.followed_users || [],
        followers: data.followers || data.followers_list || [],
        balance: data.balance || 0,
        credentials: data.credentials || '',
        bio: data.bio || '',
        storeId: data.storeId || data.store_id || undefined,
        isAdmin: !!(data.isAdmin || data.is_admin),
        isVerified: !!(data.isVerified || data.is_verified),
        isOnline: !!(data.isOnline || data.is_online),
        lastSeen: data.lastSeen || data.last_seen || 0
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) {
    return obj.map(item => cleanData(item));
  } else if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) {
        newObj[key] = cleanData(val);
      }
    });
    return newObj;
  }
  return obj;
};

