export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), cleanData(msg)] });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages.push(msg);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const deleteMessage = async (chatId: string, messageId: string, hardDelete: boolean = false) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          if (hardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter(m => m !== null) as Message[];
      await updateDoc(doc(db, 'chats', chatId), { messages: updatedMessages });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages = chat.messages.map(m => {
        if (m.id === messageId) {
          if (hardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter(m => m !== null) as Message[];
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      await updateDoc(doc(db, 'chats', chatId), { messages: updatedMessages });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages = chat.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

