/**
 * MAPEADOR ULTRA-RESILIENTE: 
 * Tenta encontrar os dados independente de como foram salvos no Firestore.
 */
const mapUserData = (id: string, data: any): User => {
    if (!data) return { id } as User;

    // Log para depuração manual no console do navegador (F12)
    console.log(`[DEBUG] Mapeando usuário ${id}:`, data);

    return {
        id: id,
        // Procura por variações de Tipo de Usuário
        userType: data.userType || data.user_type || data.type || UserType.STANDARD,

        // Procura por variações de Nome
        firstName: data.firstName || data.first_name || data.nome || data.displayName?.split(' ')[0] || 'Usuário',
        lastName: data.lastName || data.last_name || data.sobrenome || data.displayName?.split(' ').slice(1).join(' ') || 'Novo',

        // Dados de Contato e Identificação
        email: data.email || '',
        phone: data.phone || data.phone_number || data.telefone || '',
        documentId: data.documentId || data.document_id || data.cpf || data.nif || '',
        birthDate: data.birthDate || data.birth_date || data.data_nascimento || Date.now(),

        // Foto de Perfil (Suporta chaves do Firebase Auth e chaves personalizadas)
        profilePicture: data.profilePicture || data.profile_picture || data.photoURL || data.foto || DEFAULT_PROFILE_PIC,

        // Listas e Saldo
        followedUsers: data.followedUsers || data.followed_users || data.seguindo || [],
        followers: data.followers || data.followers_list || data.seguidores || [],
        balance: Number(data.balance || data.saldo || 0),

        // Dados Profissionais
        credentials: data.credentials || data.cargo || data.especialidade || '',
        bio: data.bio || data.biografia || '',
        storeId: data.storeId || data.store_id || undefined,

        // Status e Flags
        isAdmin: !!(data.isAdmin || data.is_admin || data.admin),
        isVerified: !!(data.isVerified || data.is_verified || data.verificado),
        isOnline: !!(data.isOnline || data.is_online || data.online),
        lastSeen: data.lastSeen || data.last_seen || 0
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

