// --- AUTENTICAÇÃO ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      console.log("[AUTH] Login efetuado com sucesso. UID:", firebaseUser.uid);

      // Busca o perfil detalhado no Firestore
      const userDoc = await findUserById(firebaseUser.uid);
      if (userDoc && (userDoc.firstName !== 'Usuário' || userDoc.email !== '')) {
          return userDoc;
      }

      // Se autenticou mas o mapeamento falhou ou documento não existe
      throw new Error(`Perfil não encontrado no Firestore para o UID: ${firebaseUser.uid}`);
    } catch (error: any) {
      console.error("Erro no login Firebase:", error);
      throw new Error(error.message || 'Email ou senha incorretos.');
    }
  } else {
    const users = await getUsers();
    const user = users.find(u => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado localmente.');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      throw new Error(error.message || 'Erro ao criar conta cloud.');
    }
  }

  const newUser = mapUserData(uid, userData);

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
      if (newUser.userType === UserType.CREATOR) {
          const storeId = generateUUID();
          const newStore: Store = { id: storeId, professorId: uid, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] };
          await setDoc(doc(db, 'stores', storeId), cleanData(newStore));
          await updateDoc(doc(db, 'profiles', uid), { storeId: storeId });
          newUser.storeId = storeId;
      }
  } else {
      const users = await getUsers();
      saveUsers([...users, newUser]);
  }
  return newUser;
};

