export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
    try {
      console.log(`[DB] Buscando documento na coleção 'profiles' com ID: ${userId}`);
      const docSnap = await getDoc(doc(db, 'profiles', userId));

      if (docSnap.exists()) {
          return mapUserData(docSnap.id, docSnap.data());
      } else {
          console.warn(`[DB] Documento ${userId} não existe na coleção 'profiles'.`);
          // Tentativa desesperada: buscar por campo email se o ID falhou
          const q = query(collection(db, 'profiles'), where('email', '==', auth?.currentUser?.email));
          const querySnap = await getDocs(q);
          if (!querySnap.empty) {
              console.log("[DB] Usuário encontrado via busca por e-mail fallback.");
              return mapUserData(querySnap.docs[0].id, querySnap.docs[0].data());
          }
      }
    } catch (e) { 
      console.error("Erro crítico ao buscar perfil no Firestore:", e); 
    }
  }

  // Apenas busca local se estiver em modo offline proposital
  if (!isFirebaseConfigured) {
    const users = await getUsers();
    return users.find(u => u.id === userId);
  }
  return undefined;
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'profiles'));
      return snap.docs.map(d => mapUserData(d.id, d.data()));
    } catch (e) { return []; }
  }
  const usersJson = localStorage.getItem(USERS_KEY);
  return usersJson ? JSON.parse(usersJson) : [];
};

export const saveUsers = (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users));

export const updateUser = async (user: User) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
  } else {
    const users = await getUsers();
    saveUsers(users.map(u => u.id === user.id ? user : u));
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'posts'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post)).sort((a,b) => b.timestamp - a.timestamp);
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(POSTS_KEY) || '[]');
};

export const addPost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify([post, ...posts]));
  }
};

export const updatePost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post), { merge: true });
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.map(p => p.id === post.id ? post : p)));
  }
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) {
      await deleteDoc(doc(db, 'posts', postId));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.filter(p => p.id !== postId)));
  }
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await updatePost(post);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && post.comments) {
    post.comments = post.comments.filter(c => c.id !== commentId);
    await updatePost(post);
  }
};

export const pinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  for (const p of posts) {
    if (p.userId === userId) {
      const wasPinned = p.isPinned;
      p.isPinned = p.id === postId;
      if (wasPinned !== p.isPinned) await updatePost(p);
    }
  }
  return true;
};

export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    await updatePost(post);
  }
  return true;
};

export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'chats'));
      const all = snap.docs.map(d => ({ ...d.data(), id: d.id } as ChatConversation));
      return userId ? all.filter(c => c.participants.includes(userId)) : all;
    } catch (e) { return []; }
  }
  const all = JSON.parse(localStorage.getItem(CHATS_KEY) || '[]');
  return userId ? all.filter((c: any) => c.participants.includes(userId)) : all;
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), cleanData(msg)] });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages.push(msg);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const deleteMessage = async (chatId: string, messageId: string, hardDelete: boolean = false) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          if (hardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter(m => m !== null) as Message[];
      await updateDoc(doc(db, 'chats', chatId), { messages: updatedMessages });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages = chat.messages.map(m => {
        if (m.id === messageId) {
          if (hardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter(m => m !== null) as Message[];
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      await updateDoc(doc(db, 'chats', chatId), { messages: updatedMessages });
    }
  } else {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      chat.messages = chat.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
    }
  }
};

export const startPrivateChat = async (u1: string, u2: string) => {
  const chats = await getChats();
  let chat = chats.find(c => c.type === ChatType.PRIVATE && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: generateUUID(), type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    if (useFirestore()) await setDoc(doc(db, 'chats', chat.id), cleanData(chat));
    else localStorage.setItem(CHATS_KEY, JSON.stringify([...chats, chat]));
  }
  return chat.id;
};

export const deleteChat = async (chatId: string) => {
  if (useFirestore()) await deleteDoc(doc(db, 'chats', chatId));
  else {
    const chats = (await getChats()).filter(c => c.id !== chatId);
    localStorage.setItem(CHATS_KEY, JSON.stringify(chats));
  }
};

