export const updateUserBalance = async (userId: string, amount: number) => {
  const user = await findUserById(userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    await updateUser(user);
    return true;
  }
  return false;
};

export const handleWalletTransaction = async (userId: string, amount: number, type: 'deposit' | 'withdraw') => {
  const delta = type === 'deposit' ? amount : -amount;
  if (await updateUserBalance(userId, delta)) {
    const tx: Transaction = { id: generateUUID(), userId, amount: delta, type: type === 'deposit' ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL, description: type === 'deposit' ? 'Depósito' : 'Saque', timestamp: Date.now(), status: 'COMPLETED' };
    if (useFirestore()) await setDoc(doc(db, 'transactions', tx.id), cleanData(tx));
    else {
      const txs = JSON.parse(localStorage.getItem(TRANSACTIONS_KEY) || '[]');
      localStorage.setItem(TRANSACTIONS_KEY, JSON.stringify([tx, ...txs]));
    }
    return true;
  }
  return false;
};

export const processAdInvestment = async (userId: string, amount: number, description: string): Promise<boolean> => {
  if (await updateUserBalance(userId, -amount)) {
      const tx: Transaction = { 
          id: generateUUID(), 
          userId, 
          amount: -amount, 
          type: TransactionType.PURCHASE, 
          description: `Ads: ${description}`, 
          timestamp: Date.now(), 
          status: 'COMPLETED' 
      };
      if (useFirestore()) await setDoc(doc(db, 'transactions', tx.id), cleanData(tx));
      else {
          const txs = JSON.parse(localStorage.getItem(TRANSACTIONS_KEY) || '[]');
          localStorage.setItem(TRANSACTIONS_KEY, JSON.stringify([tx, ...txs]));
      }
      return true;
  }
  return false;
};

export const processDonation = async (fromId: string, toId: string, amount: number, message: string): Promise<boolean> => {
  if (await updateUserBalance(fromId, -amount)) {
      await updateUserBalance(toId, amount);
      const txFrom: Transaction = { id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Doação para ${toId}`, timestamp: Date.now(), status: 'COMPLETED' };
      const txTo: Transaction = { id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Doação de ${fromId}`, timestamp: Date.now(), status: 'COMPLETED' };

      if (useFirestore()) {
          await setDoc(doc(db, 'transactions', txFrom.id), cleanData(txFrom));
          await setDoc(doc(db, 'transactions', txTo.id), cleanData(txTo));
      } else {
          const txs = JSON.parse(localStorage.getItem(TRANSACTIONS_KEY) || '[]');
          localStorage.setItem(TRANSACTIONS_KEY, JSON.stringify([txFrom, txTo, ...txs]));
      }
      return true;
  }
  return false;
};

