const CURRENT_USER_KEY = 'cyberphone_current_user_id';
const STORES_KEY = 'cyberphone_stores';
const PRODUCTS_KEY = 'cyberphone_products';
const AFFILIATE_SALES_KEY = 'cyberphone_affiliate_sales';
const AUDIO_TRACKS_KEY = 'cyberphone_audio_tracks';
const NOTIFICATIONS_KEY = 'cyberphone_notifications';
const STORIES_KEY = 'cyberphone_stories';
const EVENTS_KEY = 'cyberphone_events';
const TRANSACTIONS_KEY = 'cyberphone_transactions';
const SETTINGS_KEY = 'cyberphone_settings';

/**
 * MAPEADOR ULTRA-RESILIENTE (Correção Crítica para Perfil)
 * Garante que o sistema leia os dados independente da nomenclatura no Firestore.
 */
const mapUserData = (id: string, data: any): User => {
    if (!data) return { id } as User;

    console.log(`[DEBUG] Mapeando usuário ${id}:`, data);

    return {
        id: id,
        userType: data.userType || data.user_type || data.type || UserType.STANDARD,
        firstName: data.firstName || data.first_name || data.nome || data.displayName?.split(' ')[0] || 'Usuário',
        lastName: data.lastName || data.last_name || data.sobrenome || data.displayName?.split(' ').slice(1).join(' ') || 'Novo',
        email: data.email || '',
        phone: data.phone || data.phone_number || data.telefone || '',
        documentId: data.documentId || data.document_id || data.cpf || data.nif || '',
        birthDate: data.birthDate || data.birth_date || Date.now(),
        profilePicture: data.profilePicture || data.profile_picture || data.photoURL || data.foto || DEFAULT_PROFILE_PIC,
        followedUsers: data.followedUsers || data.followed_users || [],
        followers: data.followers || data.followers_list || [],
        balance: Number(data.balance || data.saldo || 0),
        credentials: data.credentials || data.cargo || data.especialidade || '',
        bio: data.bio || data.biografia || '',
        storeId: data.storeId || data.store_id || undefined,
        isAdmin: !!(data.isAdmin || data.is_admin),
        isVerified: !!(data.isVerified || data.is_verified),
        isOnline: !!(data.isOnline || data.is_online),
        lastSeen: data.lastSeen || data.last_seen || 0
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

export const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const useFirestore = () => isFirebaseConfigured && db;

// --- AUTENTICAÇÃO ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      const userDoc = await findUserById(firebaseUser.uid);
      if (userDoc) return userDoc;

      throw new Error(`Perfil do usuário logado não foi encontrado na coleção 'profiles'.`);
    } catch (error: any) {
      console.error("Erro login:", error);
      throw new Error(error.message || 'Email ou senha incorretos.');
    }
  } else {
    const usersJson = localStorage.getItem(USERS_KEY);
    const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
    const user = users.find((u: any) => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado localmente.');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      throw new Error(error.message || 'Erro ao criar conta no Firebase.');
    }
  }

  const newUser = mapUserData(uid, userData);

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
      if (newUser.userType === UserType.CREATOR) {
          const storeId = generateUUID();
          const newStore: Store = { id: storeId, professorId: uid, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] };
          await setDoc(doc(db, 'stores', storeId), cleanData(newStore));
          await updateDoc(doc(db, 'profiles', uid), { storeId: storeId });
          newUser.storeId = storeId;
      }
  } else {
      const usersJson = localStorage.getItem(USERS_KEY);
      const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
      localStorage.setItem(USERS_KEY, JSON.stringify([...users, newUser]));
  }
  return newUser;
};

// --- ACESSO A DADOS ---

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
    try {
      // 1. Busca Primária pelo Document ID (UID)
      const docSnap = await getDoc(doc(db, 'profiles', userId));

      if (docSnap.exists()) {
          return mapUserData(docSnap.id, docSnap.data());
      } else {
          // 2. Busca Secundária por e-mail se o Auth existir (Fallback de IDs)
          const q = query(collection(db, 'profiles'), where('email', '==', auth?.currentUser?.email));
          const querySnap = await getDocs(q);
          if (!querySnap.empty) {
              return mapUserData(querySnap.docs[0].id, querySnap.docs[0].data());
          }
      }
    } catch (e) { 
      console.error("Erro ao buscar perfil no Firestore:", e); 
    }
  }

  // Fallback LocalStorage
  const usersJson = localStorage.getItem(USERS_KEY);
  const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
  return users.find((u: any) => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'profiles'));
      return snap.docs.map(d => mapUserData(d.id, d.data()));
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
};

export const updateUser = async (user: User) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
  } else {
    const users = await getUsers();
    localStorage.setItem(USERS_KEY, JSON.stringify(users.map(u => u.id === user.id ? user : u)));
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'posts'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post)).sort((a,b) => b.timestamp - a.timestamp);
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(POSTS_KEY) || '[]');
};

export const addPost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify([post, ...posts]));
  }
};

export const updatePost = async (post: Post) => {
  if (useFirestore()) {
      await setDoc(doc(db, 'posts', post.id), cleanData(post), { merge: true });
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.map(p => p.id === post.id ? post : p)));
  }
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) {
      await deleteDoc(doc(db, 'posts', postId));
  } else {
    const posts = await getPosts();
    localStorage.setItem(POSTS_KEY, JSON.stringify(posts.filter(p => p.id !== postId)));
  }
};

// FIX: Added pinPost member
export const pinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = true;
    await updatePost(post);
    return true;
  }
  return false;
};

// FIX: Added unpinPost member
export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    await updatePost(post);
    return true;
  }
  return false;
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await updatePost(post);
  }
};

// FIX: Added deleteComment member
export const deleteComment = async (postId: string, commentId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    post.comments = post.comments.filter(c => c.id !== commentId);
    await updatePost(post);
  }
};

export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'chats'));
      const all = snap.docs.map(d => ({ ...d.data(), id: d.id } as ChatConversation));
      return userId ? all.filter(c => c.participants.includes(userId)) : all;
    } catch (e) { return []; }
  }
  return [];
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), cleanData(msg)] });
    }
  }
};

// FIX: Added deleteMessage member
export const deleteMessage = async (chatId: string, messageId: string, isHardDelete: boolean = false) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          if (isHardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter((m): m is Message => m !== null);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

// FIX: Added editMessage member
export const editMessage = async (chatId: string, messageId: string, newText: string) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          return { ...m, text: newText, isEdited: true };
        }
        return m;
      });
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

// FIX: Added markChatMessagesAsRead member
export const markChatMessagesAsRead = async (chatId: string, userId: string) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.senderId !== userId && !m.isRead) {
          return { ...m, isRead: true };
        }
        return m;
      });
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

