/**
 * MAPEADOR DE DADOS RESILIENTE
 * Converte dados crus do Firestore para o modelo User da aplicação, 
 * aceitando diversas variações de nomes de campos.
 */
const mapUserData = (id: string, data: any): User => {
    if (!data) return { id } as User;

    console.log(`[STORAGE] Mapeando dados do usuário: ${id}`, data);

    return {
        id: id,
        // Prioriza userType ou user_type
        userType: data.userType || data.user_type || data.type || UserType.STANDARD,

        // Mapeamento flexível de nomes
        firstName: data.firstName || data.first_name || data.nome || data.displayName?.split(' ')[0] || 'Usuário',
        lastName: data.lastName || data.last_name || data.sobrenome || data.displayName?.split(' ').slice(1).join(' ') || 'Novo',

        email: data.email || '',
        phone: data.phone || data.phone_number || data.telefone || '',
        documentId: data.documentId || data.document_id || data.cpf || '',
        birthDate: Number(data.birthDate || data.birth_date || Date.now()),

        // Foto de Perfil
        profilePicture: data.profilePicture || data.profile_picture || data.photoURL || data.foto || DEFAULT_PROFILE_PIC,

        // Listas e Saldo (Garante que balance seja número)
        followedUsers: data.followedUsers || data.followed_users || data.seguindo || [],
        followers: data.followers || data.followers_list || data.seguidores || [],
        balance: Number(data.balance || data.saldo || 0),

        // Dados Profissionais
        credentials: data.credentials || data.cargo || data.especialidade || '',
        bio: data.bio || data.biografia || '',
        storeId: data.storeId || data.store_id || undefined,

        // Flags de Status
        isAdmin: !!(data.isAdmin || data.is_admin || data.admin),
        isVerified: !!(data.isVerified || data.is_verified || data.verificado),
        isOnline: !!(data.isOnline || data.is_online || data.online),
        lastSeen: Number(data.lastSeen || data.last_seen || 0)
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

const useFirestore = () => isFirebaseConfigured && db;

// --- BUSCA DE USUÁRIO (CRÍTICO PARA SINCRONIZAÇÃO) ---

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (useFirestore()) {
    try {
      console.log(`[DB] Iniciando busca cloud para UID: ${userId}`);

      // 1. Tentativa Primária: Busca por ID de Documento (Método mais rápido)
      const docSnap = await getDoc(doc(db, 'profiles', userId));

      if (docSnap.exists()) {
          console.log("[DB] Documento de perfil encontrado via ID.");
          return mapUserData(docSnap.id, docSnap.data());
      } 

      // 2. Tentativa Secundária: Busca por campo email (Caso o UID do Auth seja diferente do ID do doc)
      const currentEmail = auth?.currentUser?.email;
      if (currentEmail) {
          console.log(`[DB] UID não encontrado. Tentando busca por e-mail: ${currentEmail}`);
          const q = query(collection(db, 'profiles'), where('email', '==', currentEmail));
          const querySnap = await getDocs(q);

          if (!querySnap.empty) {
              console.log("[DB] Perfil localizado via busca por e-mail.");
              return mapUserData(querySnap.docs[0].id, querySnap.docs[0].data());
          }
      }

      console.warn(`[DB] Perfil ${userId} não existe em 'profiles'.`);
    } catch (e) { 
      console.error("Erro ao acessar Firestore:", e); 
    }
  }

  // Fallback Local (Apenas se Cloud falhar ou não estiver configurado)
  if (!isFirebaseConfigured) {
      const usersJson = localStorage.getItem(USERS_KEY);
      const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
      return users.find((u: any) => u.id === userId);
  }

  return undefined;
};

// --- AUTENTICAÇÃO ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (useFirestore() && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;

      // Imediatamente busca o perfil completo
      const userDoc = await findUserById(firebaseUser.uid);
      if (userDoc) return userDoc;

      throw new Error(`Autenticado, mas o perfil não foi encontrado no banco de dados.`);
    } catch (error: any) {
      throw new Error(error.message || 'Email ou senha incorretos.');
    }
  } else {
    // Modo Local
    const usersJson = localStorage.getItem(USERS_KEY);
    const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
    const user = users.find((u: any) => u.email === email); 
    if (user) return user;
    throw new Error('Usuário não encontrado localmente.');
  }
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();

  if (useFirestore() && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      throw new Error(error.message || 'Erro ao criar conta no Firebase.');
    }
  }

  const newUser = mapUserData(uid, userData);

  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
      if (newUser.userType === UserType.CREATOR) {
          const storeId = generateUUID();
          const newStore: Store = { id: storeId, professorId: uid, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] };
          await setDoc(doc(db, 'stores', storeId), cleanData(newStore));
          await updateDoc(doc(db, 'profiles', uid), { storeId: storeId });
          newUser.storeId = storeId;
      }
  } else {
      const usersJson = localStorage.getItem(USERS_KEY);
      const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
      localStorage.setItem(USERS_KEY, JSON.stringify([...users, newUser]));
  }
  return newUser;
};

