  return false;
};

export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    await updatePost(post);
    return true;
  }
  return false;
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await updatePost(post);
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    post.comments = post.comments.filter(c => c.id !== commentId);
    await updatePost(post);
  }
};

export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'chats'));
      const all = snap.docs.map(d => ({ ...d.data(), id: d.id } as ChatConversation));
      return userId ? all.filter(c => c.participants.includes(userId)) : all;
    } catch (e) { return []; }
  }
  return [];
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), cleanData(msg)] });
    }
  }
};

export const deleteMessage = async (chatId: string, messageId: string, isHardDelete: boolean = false) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          if (isHardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter((m): m is Message => m !== null);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

export const markChatMessagesAsRead = async (chatId: string, userId: string) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => (m.senderId !== userId && !m.isRead) ? { ...m, isRead: true } : m);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

