export const loginUser = async (email: string, password: string): Promise<User> => {
  if (isFirebaseConfigured && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const userDoc = await findUserById(userCredential.user.uid, userCredential.user);
      if (userDoc) return userDoc;
      throw new Error(`Perfil não localizado para o UID: ${userCredential.user.uid}`);
    } catch (error: any) {
      throw new Error(error.message || 'Erro no login.');
    }
  }
  throw new Error('Firebase não configurado.');
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();
  if (isFirebaseConfigured && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) { throw new Error(error.message); }
  }

  const newUser = mapUserData(uid, userData);
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
  }
  return newUser;
};

export const generateUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
});

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

