    useEffect(() => {
        const theme = THEME_MAP[appTheme];
        document.documentElement.style.setProperty('--brand-color', theme.primary);
        document.documentElement.style.setProperty('--brand-hover', theme.hover);
        document.documentElement.style.setProperty('--brand-light', theme.light);
    }, [appTheme]);

    /**
     * SINCRONIZAÇÃO COMPLETA DO PERFIL
     * Esta função garante que os dados vêm do Auth e dos Bancos de Dados (Firebase/Supabase).
     */
    const syncUserProfile = useCallback(async (userId: string, authUserReference?: any) => {
        setSyncMessage('Sincronizando seu perfil real...');
        try {
            // Busca o perfil mesclando Auth + DB (Supabase ou Firestore)
            const user = await findUserById(userId, authUserReference);
            if (user) {
                console.log("[APP] Perfil sincronizado:", user.firstName, "| Saldo:", user.balance);
                setCurrentUser(user);
                updateUserStatus(user.id, true);
                setCartItems(getCart());
                requestNotificationPermission();

                if (currentPage === 'auth') setCurrentPage('feed');
                return true;
            } else {
                console.warn("[APP] Usuário logado mas dados não encontrados nos bancos.");
                return false;
            }
        } catch (error) {
            console.error("[APP] Erro crítico na sincronização:", error);
            return false;
        }
    }, [currentPage]);

    const refreshCurrentUser = useCallback(async () => {
        const userId = auth?.currentUser?.uid || getCurrentUserId();
        if (userId) {
            await syncUserProfile(userId, auth?.currentUser);
        } else {
            setIsLoading(false);
        }
    }, [syncUserProfile]);

    useEffect(() => {
        if (auth) {
            const unsubscribe = auth.onAuthStateChanged(async (firebaseUser: any) => {
                setIsLoading(true);
                if (firebaseUser) {
                    console.log("[AUTH] Sessão ativa:", firebaseUser.uid);
                    saveCurrentUser(firebaseUser.uid);
                    // Passamos o objeto firebaseUser para capturar DisplayName e PhotoURL imediatos
                    await syncUserProfile(firebaseUser.uid, firebaseUser);
                } else {
                    console.log("[AUTH] Nenhuma sessão ativa.");
                    saveCurrentUser(null);
                    setCurrentUser(null);
                    setCurrentPage('auth');
                }
                setIsLoading(false);
            });
            return () => unsubscribe();
        } else {
            setIsLoading(false);
        }
    }, [syncUserProfile]);

    const handleLoginSuccess = useCallback(async (user: User) => {
        setIsLoading(true);
        // Garante que após o login o objeto do Auth seja usado para a sincronização final
        await syncUserProfile(user.id, auth?.currentUser);
        setIsLoading(false);
    }, [syncUserProfile]);

    const handleLogout = useCallback(async () => {
        setIsLoading(true);
        if (auth) await auth.signOut();
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
        setIsLoading(false);
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
