const USERS_KEY = 'cyberphone_users';
const CURRENT_USER_KEY = 'cyberphone_current_user_id';

/**
 * MAPEADOR HÍBRIDO (Firebase Auth + Supabase/Firestore)
 * Prioriza displayName e photoURL do Firebase Auth para evitar "Usuário Novo".
 * Mescla com dados de saldo e seguidores do Supabase.
 */
export const mapUserData = (id: string, dbData: any, authUser?: any): User => {
    // Captura dados do Firebase Auth (displayName e photoURL)
    const nameFromAuth = authUser?.displayName || "";
    const photoFromAuth = authUser?.photoURL || "";

    // Lógica de nome: tenta Auth, depois DB, depois Fallback
    const fullName = nameFromAuth || (dbData?.firstName ? `${dbData.firstName} ${dbData.lastName || ''}` : "");
    const firstName = dbData?.firstName || fullName.split(' ')[0] || 'Membro';
    const lastName = dbData?.lastName || fullName.split(' ').slice(1).join(' ') || 'CyBer';

    return {
        id: id,
        userType: dbData?.userType || dbData?.user_type || UserType.STANDARD,
        firstName: firstName,
        lastName: lastName,
        email: dbData?.email || authUser?.email || '',
        phone: dbData?.phone || dbData?.phone_number || '',
        documentId: dbData?.documentId || dbData?.document_id || '',
        birthDate: Number(dbData?.birthDate || dbData?.birth_date || Date.now()),

        // Prioridade absoluta para a foto do Firebase Auth se disponível
        profilePicture: photoFromAuth || dbData?.profilePicture || dbData?.profile_picture || DEFAULT_PROFILE_PIC,

        // Dados vindos do Banco de Dados (Supabase/Firestore)
        followedUsers: dbData?.followedUsers || dbData?.followed_users || [],
        followers: dbData?.followers || dbData?.followers_list || [],
        balance: Number(dbData?.balance || dbData?.saldo || 0),

        credentials: dbData?.credentials || '',
        bio: dbData?.bio || '',
        storeId: dbData?.storeId || undefined,
        isAdmin: !!(dbData?.isAdmin || dbData?.is_admin),
        isVerified: !!(dbData?.isVerified || dbData?.is_verified),
        isOnline: !!(dbData?.isOnline || dbData?.is_online),
        lastSeen: Number(dbData?.lastSeen || dbData?.last_seen || 0)
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

const useFirestore = () => isFirebaseConfigured && db;

// --- BUSCA DE USUÁRIO COM SUPORTE SUPABASE (Para Saldo e Seguidores) ---

export const findUserById = async (userId: string, authUserReference?: any): Promise<User | undefined> => {
  let finalDbData: any = null;

  // 1. Tentar Supabase (Prioridade para Saldo e Seguidores conforme pedido)
  if (isSupabaseConfigured) {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (data && !error) {
          finalDbData = data;
      }
    } catch (e) { console.error("Erro ao buscar no Supabase:", e); }
  }

  // 2. Tentar Firestore se não achou no Supabase (Coleção profiles)
  if (!finalDbData && useFirestore()) {
    try {
      const docSnap = await getDoc(doc(db, 'profiles', userId));
      if (docSnap.exists()) {
          finalDbData = docSnap.data();
      }
    } catch (e) { console.error("Erro ao buscar no Firestore:", e); }
  }

  // 3. Mesclar com metadados do Auth para garantir Nome e Foto
  // Se não temos nada no DB nem no Auth, usamos fallback local
  if (finalDbData || authUserReference || auth?.currentUser) {
      return mapUserData(userId, finalDbData, authUserReference || auth?.currentUser);
  }

  // Fallback Local Storage
  const usersJson = localStorage.getItem(USERS_KEY);
  const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
  return users.find((u: any) => u.id === userId);
};

// --- RESTO DOS MÉTODOS MANTIDOS ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (isFirebaseConfigured && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const userDoc = await findUserById(userCredential.user.uid, userCredential.user);
      if (userDoc) return userDoc;
      throw new Error(`Perfil não localizado.`);
    } catch (error: any) {
      throw new Error(error.message || 'Erro no login.');
    }
  }
  throw new Error('Firebase não configurado.');
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();
  if (isFirebaseConfigured && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) { throw new Error(error.message); }
  }

  const newUser = mapUserData(uid, userData);
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
  }
  return newUser;
};

export const generateUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
});

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'profiles'));
      return snap.docs.map(d => mapUserData(d.id, d.data()));
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
};

export const updateUser = async (user: User) => {
  if (useFirestore()) await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
  if (isSupabaseConfigured) {
      await supabase.from('profiles').upsert(cleanData(user));
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'posts'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post)).sort((a,b) => b.timestamp - a.timestamp);
    } catch (e) { return []; }
  }
  return [];
};

export const addPost = async (post: Post) => {
  if (useFirestore()) await setDoc(doc(db, 'posts', post.id), cleanData(post));
};

export const updatePost = async (post: Post) => {
  if (useFirestore()) await setDoc(doc(db, 'posts', post.id), cleanData(post), { merge: true });
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) await deleteDoc(doc(db, 'posts', postId));
};

export const pinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = true;
    await updatePost(post);
    return true;
  }
  return false;
};

export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    await updatePost(post);
    return true;
  }
  return false;
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
