import { User, Post, ChatConversation, AdCampaign, UserType, Store, Product, AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, Notification, NotificationType, CartItem, ProductRating, OrderStatus, CyberEvent, Story, Transaction, ContentReport, SystemLog, GlobalSettings, TransactionType, ChatType, GroupTheme, Message, SupportTicket } from '../types';
import { DEFAULT_USERS, DEFAULT_POSTS, DEFAULT_ADS, DEFAULT_STORES, DEFAULT_PRODUCTS, DEFAULT_AFFILIATE_SALES, DEFAULT_PROFILE_PIC, DEFAULT_AUDIO_TRACKS } from '../data/constants';
import { auth, db, isFirebaseConfigured } from './firebaseClient';
import { supabase, isSupabaseConfigured } from './supabaseClient';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { 
  collection, getDocs, doc, getDoc, setDoc, updateDoc, deleteDoc, query, where, orderBy, limit, addDoc 
} from 'firebase/firestore';

const USERS_KEY = 'cyberphone_users';
const CURRENT_USER_KEY = 'cyberphone_current_user_id';

/**
 * MAPEADOR HÍBRIDO DE IDENTIDADE E NEGÓCIO
 * Prioriza o objeto de autenticação do Firebase para Nome e Foto.
 * Prioriza o Supabase/Firestore para Saldo e Seguidores.
 */
export const mapUserData = (id: string, dbData: any, authUser?: any): User => {
    // Captura metadados do Firebase Auth
    const nameFromAuth = authUser?.displayName || "";
    const photoFromAuth = authUser?.photoURL || "";

    // Lógica resiliente para nomes
    let firstName = "Membro";
    let lastName = "CyBer";

    if (dbData?.firstName) {
        firstName = dbData.firstName;
        lastName = dbData.lastName || "";
    } else if (nameFromAuth) {
        const parts = nameFromAuth.split(' ');
        firstName = parts[0];
        lastName = parts.slice(1).join(' ') || "";
    }

    return {
        id: id,
        userType: dbData?.userType || dbData?.user_type || UserType.STANDARD,
        firstName: firstName,
        lastName: lastName,
        email: dbData?.email || authUser?.email || '',
        phone: dbData?.phone || dbData?.phone_number || '',
        documentId: dbData?.documentId || dbData?.document_id || '',
        birthDate: Number(dbData?.birthDate || dbData?.birth_date || Date.now()),

        // Foto: Prioridade para o Auth (Cloudinary / Firebase URL)
        profilePicture: photoFromAuth || dbData?.profilePicture || dbData?.profile_picture || DEFAULT_PROFILE_PIC,

        // Dados de Negócio (Supabase/Firestore)
        followedUsers: dbData?.followedUsers || dbData?.followed_users || [],
        followers: dbData?.followers || dbData?.followers_list || [],
        balance: Number(dbData?.balance || dbData?.saldo || 0),

        credentials: dbData?.credentials || '',
        bio: dbData?.bio || '',
        storeId: dbData?.storeId || undefined,
        isAdmin: !!(dbData?.isAdmin || dbData?.is_admin),
        isVerified: !!(dbData?.isVerified || dbData?.is_verified),
        isOnline: !!(dbData?.isOnline || dbData?.is_online),
        lastSeen: Number(dbData?.lastSeen || dbData?.last_seen || 0)
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

const useFirestore = () => isFirebaseConfigured && db;

/**
 * BUSCA DE USUÁRIO MULTI-FONTE
 * 1. Tenta Supabase (Saldo e Seguidores)
 * 2. Tenta Firestore (Profiles Legado)
 * 3. Mescla com Firebase Auth (Identity)
 */
export const findUserById = async (userId: string, authUserReference?: any): Promise<User | undefined> => {
  let finalDbData: any = null;

  // 1. Tentar Supabase (Prioridade solicitada para Saldo e Seguidores)
  if (isSupabaseConfigured) {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .maybeSingle(); // maybeSingle para não disparar erro no console se não existir

      if (data && !error) {
          finalDbData = data;
          console.log(`[STORAGE] Dados recuperados do Supabase para ${userId}`);
      }
    } catch (e) { console.error("Erro Supabase:", e); }
  }

  // 2. Tentar Firestore se não achou no Supabase
  if (!finalDbData && useFirestore()) {
    try {
      const docSnap = await getDoc(doc(db, 'profiles', userId));
      if (docSnap.exists()) {
          finalDbData = docSnap.data();
          console.log(`[STORAGE] Dados recuperados do Firestore para ${userId}`);
      }
    } catch (e) { console.error("Erro Firestore:", e); }
  }

  // 3. Mesclagem e retorno
  // Se temos um authUserReference (vindo do login ou session listener), usamos ele para garantir Nome e Foto.
  if (finalDbData || authUserReference || auth?.currentUser) {
      return mapUserData(userId, finalDbData, authUserReference || auth?.currentUser);
  }

  // Fallback para dados locais apenas se tudo mais falhar
  const usersJson = localStorage.getItem(USERS_KEY);
  const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
  return users.find((u: any) => u.id === userId);
};

export const loginUser = async (email: string, password: string): Promise<User> => {
  if (isFirebaseConfigured && auth) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      // Imediatamente busca o perfil completo mesclando com o objeto do usuário recém-logado
      const userDoc = await findUserById(userCredential.user.uid, userCredential.user);
      if (userDoc) return userDoc;
      throw new Error(`Perfil não localizado no banco de dados.`);
    } catch (error: any) {
      throw new Error(error.message || 'Erro no login.');
    }
  }
  throw new Error('Firebase não configurado.');
};

export const registerUser = async (userData: any): Promise<User> => {
  let uid = generateUUID();
  if (isFirebaseConfigured && auth) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) { throw new Error(error.message); }
  }

  const newUser = mapUserData(uid, userData);
  if (useFirestore()) {
      await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
  }
  if (isSupabaseConfigured) {
      await supabase.from('profiles').upsert(cleanData(newUser));
  }
  return newUser;
};

export const generateUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
});

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const getUsers = async (): Promise<User[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'profiles'));
      return snap.docs.map(d => mapUserData(d.id, d.data()));
    } catch (e) { return []; }
  }
  return JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
};

export const updateUser = async (user: User) => {
  if (useFirestore()) await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
  if (isSupabaseConfigured) {
      await supabase.from('profiles').upsert(cleanData(user));
  }
};

export const getPosts = async (): Promise<Post[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'posts'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post)).sort((a,b) => b.timestamp - a.timestamp);
    } catch (e) { return []; }
  }
  return [];
};

export const addPost = async (post: Post) => {
  if (useFirestore()) await setDoc(doc(db, 'posts', post.id), cleanData(post));
};

export const updatePost = async (post: Post) => {
  if (useFirestore()) await setDoc(doc(db, 'posts', post.id), cleanData(post), { merge: true });
};

export const deletePost = async (postId: string) => {
  if (useFirestore()) await deleteDoc(doc(db, 'posts', postId));
};

export const pinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = true;
    await updatePost(post);
    return true;
  }
  return false;
};

export const unpinPost = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    await updatePost(post);
    return true;
  }
  return false;
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    await updatePost(post);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.comments) post.comments = [];
    post.comments.push(comment);
    await updatePost(post);
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    post.comments = post.comments.filter(c => c.id !== commentId);
    await updatePost(post);
  }
};

export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'chats'));
      const all = snap.docs.map(d => ({ ...d.data(), id: d.id } as ChatConversation));
      return userId ? all.filter(c => c.participants.includes(userId)) : all;
    } catch (e) { return []; }
  }
  return [];
};

export const sendMessage = async (chatId: string, msg: any) => {
  if (useFirestore()) {
    const chatSnap = await getDoc(doc(db, 'chats', chatId));
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      await updateDoc(doc(db, 'chats', chatId), { messages: [...(data.messages || []), cleanData(msg)] });
    }
  }
};

export const deleteMessage = async (chatId: string, messageId: string, isHardDelete: boolean = false) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => {
        if (m.id === messageId) {
          if (isHardDelete) return null;
          return { ...m, isDeleted: true, text: undefined, fileUrl: undefined, imageUrl: undefined };
        }
        return m;
      }).filter((m): m is Message => m !== null);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

export const markChatMessagesAsRead = async (chatId: string, userId: string) => {
  if (useFirestore()) {
    const chatRef = doc(db, 'chats', chatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      const data = chatSnap.data() as ChatConversation;
      const updatedMessages = data.messages.map(m => (m.senderId !== userId && !m.isRead) ? { ...m, isRead: true } : m);
      await updateDoc(chatRef, { messages: updatedMessages });
    }
  }
};

export const deleteChat = async (chatId: string) => {
  if (useFirestore()) await deleteDoc(doc(db, 'chats', chatId));
};

export const startPrivateChat = async (u1: string, u2: string) => {
  const chats = await getChats();
  let chat = chats.find(c => c.type === ChatType.PRIVATE && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: generateUUID(), type: ChatType.PRIVATE, participants: [u1, u2], messages: [] };
    if (useFirestore()) await setDoc(doc(db, 'chats', chat.id), cleanData(chat));
  }
  return chat.id;
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const user = await findUserById(userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    await updateUser(user);
    return true;
  }
  return false;
};

export const processAdInvestment = async (userId: string, amount: number, description: string): Promise<boolean> => {
  if (await updateUserBalance(userId, -amount)) {
      const tx: Transaction = { id: generateUUID(), userId, amount: -amount, type: TransactionType.PURCHASE, description: `Impulsionamento: ${description}`, timestamp: Date.now(), status: 'COMPLETED' };
      if (useFirestore()) await setDoc(doc(db, 'transactions', tx.id), cleanData(tx));
      return true;
  }
  return false;
};

export const processDonation = async (fromId: string, toId: string, amount: number, message: string): Promise<boolean> => {
  if (await updateUserBalance(fromId, -amount)) {
      await updateUserBalance(toId, amount);
      const txFrom: Transaction = { id: generateUUID(), userId: fromId, type: TransactionType.DONATION, amount: -amount, description: `Apoio enviado`, timestamp: Date.now(), status: 'COMPLETED' };
      const txTo: Transaction = { id: generateUUID(), userId: toId, type: TransactionType.DONATION, amount: amount, description: `Apoio recebido`, timestamp: Date.now(), status: 'COMPLETED' };
      if (useFirestore()) {
          await setDoc(doc(db, 'transactions', txFrom.id), cleanData(txFrom));
          await setDoc(doc(db, 'transactions', txTo.id), cleanData(txTo));
      }
      return true;
  }
  return false;
};

export const handleWalletTransaction = async (userId: string, amount: number, type: 'deposit' | 'withdraw') => {
  const delta = type === 'deposit' ? amount : -amount;
  if (await updateUserBalance(userId, delta)) {
    const tx: Transaction = { id: generateUUID(), userId, amount: delta, type: type === 'deposit' ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL, description: type === 'deposit' ? 'Recarga' : 'Retirada', timestamp: Date.now(), status: 'COMPLETED' };
    if (useFirestore()) await setDoc(doc(db, 'transactions', tx.id), cleanData(tx));
    return true;
  }
  return false;
};

export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
  if (useFirestore()) {
    try {
      const q = query(collection(db, 'notifications'), where('recipientId', '==', userId));
      const snap = await getDocs(q);
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Notification));
    } catch (e) { return []; }
  }
  return [];
};

export const markNotificationsAsRead = async (userId: string) => {
  if (useFirestore()) {
    try {
      const q = query(collection(db, 'notifications'), where('recipientId', '==', userId), where('isRead', '==', false));
      const snap = await getDocs(q);
      for (const d of snap.docs) await updateDoc(doc(db, 'notifications', d.id), { isRead: true });
    } catch (e) {}
  }
};

export const getProducts = async (): Promise<Product[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'products'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Product));
    } catch (e) { return []; }
  }
  return [];
};

export const createProduct = async (p: Product) => {
  if (useFirestore()) await setDoc(doc(db, 'products', p.id), cleanData(p));
};

export const getStores = async (): Promise<Store[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'stores'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Store));
    } catch (e) { return []; }
  }
  return [];
};

export const findStoreById = async (id: string) => (await getStores()).find(s => s.id === id);

export const updateStore = async (s: Store) => {
  if (useFirestore()) await setDoc(doc(db, 'stores', s.id), cleanData(s), { merge: true });
};

export const getAffiliateSales = async (): Promise<AffiliateSale[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'affiliate_sales'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as AffiliateSale));
    } catch (e) { return []; }
  }
  return [];
};

export const getSalesByAffiliateId = async (id: string) => (await getAffiliateSales()).filter(s => s.affiliateUserId === id);
export const getPurchasesByBuyerId = async (id: string) => (await getAffiliateSales()).filter(s => s.buyerId === id);

export const getStories = async (): Promise<Story[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'stories'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as Story));
    } catch (e) { return []; }
  }
  return [];
};

export const addStory = async (uId: string, item: any) => {
  const stories = await getStories();
  const user = await findUserById(uId);
  if (!user) return;
  let s = stories.find(x => x.userId === uId);
  if (!s) s = { id: generateUUID(), userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
  s.items.push({ ...item, id: generateUUID(), timestamp: Date.now() });
  if (useFirestore()) await setDoc(doc(db, 'stories', s.id!), cleanData(s));
};

export const getAds = async (): Promise<AdCampaign[]> => {
  if (useFirestore()) {
    try {
      const snap = await getDocs(collection(db, 'ads'));
      return snap.docs.map(d => ({ ...d.data(), id: d.id } as AdCampaign));
    } catch (e) { return []; }
  }
  return [];
};

export const createAd = async (ad: AdCampaign) => {
