export const updateCartItemQuantity = (id: string, q: number) => {
  let cart = getCart();
  if (q <= 0) cart = cart.filter(i => i.productId !== id);
  else { const item = cart.find(i => i.productId === id); if (item) item.quantity = q; }
  localStorage.setItem('cyberphone_cart', JSON.stringify(cart));
};

