                console.warn("[APP] Perfil real não encontrado nos bancos de dados.");
                return false;
            }
        } catch (error) {
            console.error("[APP] Erro crítico na sincronização:", error);
            return false;
        }
    }, [currentPage]);

    const refreshCurrentUser = useCallback(async () => {
