                    console.log("[AUTH] Sessão real detectada:", firebaseUser.uid);
                    saveCurrentUser(firebaseUser.uid);
                    // Força a sincronização profunda com dados reais
                    await syncUserProfile(firebaseUser.uid, firebaseUser);
                } else {
                    console.log("[AUTH] Nenhuma sessão ativa.");
                    saveCurrentUser(null);
                    setCurrentUser(null);
                    setCurrentPage('auth');
                }
                setIsLoading(false);
            });
            return () => unsubscribe();
        } else {
            setIsLoading(false);
        }
