/**
 * MAPEADOR DE PERFIL REAL
 * - Identidade (Nome/Foto Cloudinary): Vem do Firebase Auth
 * - Negócio (Saldo/Seguidores): Vem do Supabase ou Firestore
 */
export const mapUserData = (id: string, dbData: any, authUser?: any): User => {
    // 1. Extrair identidade do Auth (Prioridade Máxima - Foto Cloudinary)
    const authDisplayName = authUser?.displayName || "";
    const authPhotoURL = authUser?.photoURL || "";

    // 2. Processar nomes de forma inteligente
    let firstName = dbData?.firstName || dbData?.first_name || "";
    let lastName = dbData?.lastName || dbData?.last_name || "";

    if (!firstName && authDisplayName) {
        const parts = authDisplayName.split(' ');
        firstName = parts[0];
        lastName = parts.slice(1).join(' ');
    }

    // Fallbacks finais para evitar "Usuário Novo"
    firstName = firstName || 'Membro';
    lastName = lastName || 'CyBer';

    return {
        id: id,
        userType: dbData?.userType || dbData?.user_type || UserType.STANDARD,
        firstName: firstName,
        lastName: lastName,
        email: dbData?.email || authUser?.email || '',
        phone: dbData?.phone || dbData?.phone_number || '',
        documentId: dbData?.documentId || dbData?.document_id || '',
        birthDate: Number(dbData?.birthDate || dbData?.birth_date || Date.now()),

        // FOTO: Prioridade absoluta para o link Cloudinary do Auth
        profilePicture: authPhotoURL || dbData?.profilePicture || dbData?.profile_picture || DEFAULT_PROFILE_PIC,

        // SOCIAL/FINANCEIRO: Estritamente do Banco de Dados
        followedUsers: dbData?.followedUsers || dbData?.followed_users || [],
        followers: dbData?.followers || dbData?.followers_list || [],
        balance: Number(dbData?.balance || dbData?.saldo || 0),

        credentials: dbData?.credentials || '',
        bio: dbData?.bio || '',
        storeId: dbData?.storeId || undefined,
        isAdmin: !!(dbData?.isAdmin || dbData?.is_admin),
        isVerified: !!(dbData?.isVerified || dbData?.is_verified),
        isOnline: !!(dbData?.isOnline || dbData?.is_online),
        lastSeen: Number(dbData?.lastSeen || dbData?.last_seen || 0)
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

const useFirestore = () => isFirebaseConfigured && db;

/**
 * BUSCA DE USUÁRIO MULTI-FONTE (Real-time)
 * Busca saldo no Supabase e integra com a foto Cloudinary do Auth.
 */
export const findUserById = async (userId: string, authUserReference?: any): Promise<User | undefined> => {
  if (!userId) return undefined;

  let dbData: any = null;

  // 1. Tentar Supabase (Prioridade para Saldo e Seguidores)
  if (isSupabaseConfigured) {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .maybeSingle();

      if (data && !error) {
          dbData = data;
      }
    } catch (e) { console.error("Erro Supabase:", e); }
  }

  // 2. Tentar Firestore se não achou no Supabase
  if (!dbData && useFirestore()) {
    try {
      const docSnap = await getDoc(doc(db, 'profiles', userId));
      if (docSnap.exists()) {
          dbData = docSnap.data();
      }
    } catch (e) { console.error("Erro Firestore:", e); }
  }

  // 3. Mesclar com o Auth (Identity)
  // Usamos o auth.currentUser como referência de última instância para a foto da Cloudinary
  const finalAuthUser = authUserReference || auth?.currentUser;

  if (dbData || finalAuthUser) {
      return mapUserData(userId, dbData, finalAuthUser);
  }

  // Fallback Local Storage (apenas para usuários de teste locais se não houver ID real)
  if (userId.startsWith('user-') || userId.startsWith('pro-')) {
      const usersJson = localStorage.getItem(USERS_KEY);
      const users = usersJson ? JSON.parse(usersJson) : DEFAULT_USERS;
      return users.find((u: any) => u.id === userId);
  }

  return undefined;
};

