/**
 * MAPEADOR DE DADOS (Firestore + Auth)
 * Não usa mais Supabase. Prioriza dados reais da nuvem.
 */
export const mapUserData = (id: string, dbData: any, authUser?: any): User => {
    const authDisplayName = authUser?.displayName || "";
    const authPhotoURL = authUser?.photoURL || "";

    let firstName = dbData?.firstName || authDisplayName.split(' ')[0] || 'Membro';
    let lastName = dbData?.lastName || authDisplayName.split(' ').slice(1).join(' ') || 'CyBer';

    return {
        id: id,
        userType: dbData?.userType || UserType.STANDARD,
        firstName: firstName,
        lastName: lastName,
        email: dbData?.email || authUser?.email || '',
        phone: dbData?.phone || '',
        documentId: dbData?.documentId || '',
        birthDate: Number(dbData?.birthDate || Date.now()),
        profilePicture: authPhotoURL || dbData?.profilePicture || DEFAULT_PROFILE_PIC,
        followedUsers: dbData?.followedUsers || [],
        followers: dbData?.followers || [],
        balance: Number(dbData?.balance || 0),
        credentials: dbData?.credentials || '',
        bio: dbData?.bio || '',
        storeId: dbData?.storeId || undefined,
        isAdmin: !!dbData?.isAdmin,
        isVerified: !!dbData?.isVerified,
        isOnline: !!dbData?.isOnline,
        lastSeen: Number(dbData?.lastSeen || 0)
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

/**
 * BUSCA DE USUÁRIO (Firestore Only)
 */
export const findUserById = async (userId: string, authUserReference?: any): Promise<User | undefined> => {
  if (!userId || !isFirebaseConfigured) return undefined;

  try {
    const docSnap = await getDoc(doc(db, 'profiles', userId));
    if (docSnap.exists()) {
      return mapUserData(userId, docSnap.data(), authUserReference || auth?.currentUser);
    } else if (authUserReference || auth?.currentUser) {
      // Se existe no Auth mas não no Firestore, retorna mapeado do Auth
      return mapUserData(userId, null, authUserReference || auth?.currentUser);
    }
  } catch (e) {
    console.error("Erro ao buscar perfil no Firestore:", e);
  }
  return undefined;
};

// --- AUTENTICAÇÃO ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  const userCredential = await signInWithEmailAndPassword(auth, email, password);
  const userDoc = await findUserById(userCredential.user.uid, userCredential.user);
  if (userDoc) return userDoc;
  throw new Error(`Perfil não localizado no Firestore.`);
};

export const registerUser = async (userData: any): Promise<User> => {
  const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
  const uid = userCredential.user.uid;

  // Atualiza Perfil no Auth (Cloudinary Photo)
  await updateProfile(userCredential.user, {
    displayName: `${userData.firstName} ${userData.lastName}`,
    photoURL: userData.profilePicture
  });

  const newUser = mapUserData(uid, userData, userCredential.user);
  await setDoc(doc(db, 'profiles', uid), cleanData(newUser));
  return newUser;
};

