// --- SOCIAL E CONTEÚDO (FIRESTORE) ---

export const getPosts = async (): Promise<Post[]> => {
  if (!isFirebaseConfigured) return [];
  const snap = await getDocs(query(collection(db, 'posts'), orderBy('timestamp', 'desc')));
  return snap.docs.map(d => ({ ...d.data(), id: d.id } as Post));
};

export const addPost = async (post: Post) => {
  await setDoc(doc(db, 'posts', post.id), cleanData(post));
};

export const updatePost = async (post: Post) => {
  await updateDoc(doc(db, 'posts', post.id), cleanData(post));
};

export const deletePost = async (postId: string) => {
  await deleteDoc(doc(db, 'posts', postId));
};

export const updateUser = async (user: User) => {
  await setDoc(doc(db, 'profiles', user.id), cleanData(user), { merge: true });
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const user = await findUserById(userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    await updateUser(user);
    return true;
  }
  return false;
};

export const toggleFollowUser = async (cur: string, target: string) => {
  const u1 = await findUserById(cur);
  const u2 = await findUserById(target);
  if (u1 && u2) {
    if (u1.followedUsers.includes(target)) {
      u1.followedUsers = u1.followedUsers.filter(i => i !== target);
      u2.followers = u2.followers.filter(i => i !== cur);
    } else {
      u1.followedUsers.push(target);
      u2.followers.push(cur);
    }
    await updateUser(u1);
    await updateUser(u2);
  }
};

// --- CHAT (REAL-TIME FIRESTORE) ---

export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  const snap = await getDocs(collection(db, 'chats'));
  const all = snap.docs.map(d => ({ ...d.data(), id: d.id } as ChatConversation));
  return userId ? all.filter(c => c.participants.includes(userId)) : all;
};

export const sendMessage = async (chatId: string, msg: any) => {
  const chatRef = doc(db, 'chats', chatId);
  const chatSnap = await getDoc(chatRef);
  if (chatSnap.exists()) {
    const data = chatSnap.data() as ChatConversation;
    await updateDoc(chatRef, { messages: [...(data.messages || []), cleanData(msg)] });
  }
};

