import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser, uploadFile } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { COUNTRIES } from '../data/countries';
import { EyeIcon, EyeSlashIcon, CloudArrowUpIcon, DocumentCheckIcon, ArrowPathIcon, CameraIcon, UserCircleIcon } from '@heroicons/react/24/solid';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');

  const [profileImageFile, setProfileImageFile] = useState<File | null>(null);
  const [profileImagePreview, setProfileImagePreview] = useState<string | null>(null);
  const [docFile, setDocFile] = useState<File | null>(null);

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const profileImageInputRef = useRef<HTMLInputElement>(null);

  const handleProfileImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProfileImageFile(file);
      setProfileImagePreview(URL.createObjectURL(file));
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !password) {
        setError("Campos obrigatórios faltando.");
        return;
    }

    setLoading(true);
    try {
      const newUser = await registerUser({
        userType,
        firstName,
        lastName,
        email,
        phone,
        documentId,
        birthDate: new Date(birthDate).getTime(),
        password,
        profileImageFile: profileImageFile, // Passa o arquivo real para o Cloudinary
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio
      });

      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      setError(err.message || 'Erro no cadastro.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError(err.message || 'Erro no login.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-900 via-gray-900 to-black p-4 animate-fade-in">
      <div className="bg-white dark:bg-[#0f1115] w-full max-w-lg rounded-[3rem] shadow-2xl overflow-hidden relative border border-white/10">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>

        <div className="p-8 md:p-12">
           <div className="text-center mb-8">
              <h1 className="text-4xl font-black dark:text-white tracking-tighter mb-2">CyBerPhone</h1>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{isRegister ? 'Crie sua conta mestre ou aluno' : 'Bem-vindo de volta'}</p>
           </div>

           {error && (
             <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-100 rounded-2xl text-center">
                <p className="text-xs font-black text-red-600 dark:text-red-400 uppercase">{error}</p>
             </div>
           )}

           <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
              {isRegister && (
                <>
                    <div className="grid grid-cols-2 gap-3 mb-4">
                        <button type="button" onClick={() => setUserType(UserType.STANDARD)} className={`p-3 rounded-2xl border-2 transition-all flex flex-col items-center gap-1 ${userType === UserType.STANDARD ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-transparent bg-gray-50 text-gray-400'}`}>
                            <UserCircleIcon className="h-5 w-5" />
                            <span className="text-[9px] font-black uppercase">Aluno</span>
                        </button>
                        <button type="button" onClick={() => setUserType(UserType.CREATOR)} className={`p-3 rounded-2xl border-2 transition-all flex flex-col items-center gap-1 ${userType === UserType.CREATOR ? 'border-purple-600 bg-purple-50 text-purple-600' : 'border-transparent bg-gray-50 text-gray-400'}`}>
                            <CloudArrowUpIcon className="h-5 w-5" />
                            <span className="text-[9px] font-black uppercase">Professor</span>
                        </button>
                    </div>

                    <div className="flex justify-center mb-4">
                        <div onClick={() => profileImageInputRef.current?.click()} className="relative w-20 h-20 rounded-full border-4 border-gray-100 cursor-pointer overflow-hidden group bg-gray-50">
                            {profileImagePreview ? <img src={profileImagePreview} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-gray-300"><CameraIcon className="h-8 w-8" /></div>}
                            <input type="file" ref={profileImageInputRef} onChange={handleProfileImageChange} accept="image/*" className="hidden" />
                        </div>
                    </div>

                   <div className="flex gap-3">
                      <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm" />
                      <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm" />
                   </div>
                </>
              )}

              <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm" />

              <div className="relative">
                 <input type={showPassword ? "text" : "password"} placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm" />
                 <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400">
                    {showPassword ? <EyeSlashIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}
                 </button>
              </div>

              <button type="submit" disabled={loading} className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-sm uppercase shadow-xl transition-all flex items-center justify-center gap-2">
                 {loading ? <ArrowPathIcon className="h-5 w-5 animate-spin" /> : (isRegister ? 'Criar Conta' : 'Entrar')}
              </button>
           </form>

           <div className="mt-8 text-center">
              <button onClick={() => setIsRegister(!isRegister)} className="text-xs font-bold text-gray-500 hover:text-blue-600 transition-colors">
                 {isRegister ? 'Já tem conta? Login' : 'Novo por aqui? Criar conta'}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, CartItem, GlobalSettings, GroupTheme } from './types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getCart,
    getAppTheme,
    saveAppTheme,
    updateUserStatus
} from './services/storageService';
import { auth } from './services/firebaseClient';
import Header from './components/Header';
import Footer from './components/Footer';
import AuthPage from './components/AuthPage';
import FeedPage from './components/FeedPage';
import ProfilePage from './components/ProfilePage';
import ChatPage from './components/ChatPage';
import AdCampaignPage from './components/AdCampaignPage';
import LiveStreamViewer from './components/LiveStreamViewer';
import { StorePage } from './components/StorePage';
import StoreManagerPage from './components/StoreManagerPage';
import ReelsPage from './components/ReelsPage';
import SearchResultsPage from './components/SearchResultsPage';
import NotificationsPage from './components/NotificationsPage';
import CartModal from './components/CartModal';
import WalletModal from './components/WalletModal';
import SettingsPage from './components/SettingsPage';
import AdminDashboard from './components/AdminDashboard';
import EventsPage from './components/EventsPage';
import PurchasesPage from './components/PurchasesPage';
import AffiliatesPage from './components/AffiliatesPage';
import CreateGroupPage from './components/CreateGroupPage';
import SupportPage from './components/SupportPage';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'reels-page' | 'search-results' | 'notifications' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates' | 'create-group' | 'support';

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [appTheme, setAppTheme] = useState<GroupTheme>(() => getAppTheme());
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });

    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    const syncUserProfile = useCallback(async (userId: string, authUserReference?: any) => {
        try {
            const user = await findUserById(userId, authUserReference);
            if (user) {
                setCurrentUser(user);
                updateUserStatus(user.id, true);
                setCartItems(getCart());
                if (currentPage === 'auth') setCurrentPage('feed');
                return true;
            }
            return false;
        } catch (error) {
            console.error("[APP] Erro de sincronização:", error);
            return false;
        }
    }, [currentPage]);

    useEffect(() => {
        if (auth) {
            const unsubscribe = auth.onAuthStateChanged(async (firebaseUser: any) => {
                if (firebaseUser) {
                    saveCurrentUser(firebaseUser.uid);
                    await syncUserProfile(firebaseUser.uid, firebaseUser);
                } else {
                    saveCurrentUser(null);
                    setCurrentUser(null);
                    setCurrentPage('auth');
                }
                setIsLoading(false);
            });
            return () => unsubscribe();
        } else {
            setIsLoading(false);
        }
    }, [syncUserProfile]);

    const refreshCurrentUser = useCallback(async () => {
        const userId = auth?.currentUser?.uid || getCurrentUserId();
        if (userId) await syncUserProfile(userId, auth?.currentUser);
    }, [syncUserProfile]);

    const handleLoginSuccess = useCallback(async (user: User) => {
        setIsLoading(true);
        await syncUserProfile(user.id, auth?.currentUser);
        setIsLoading(false);
    }, [syncUserProfile]);

    const handleLogout = useCallback(async () => {
        setIsLoading(true);
        if (auth) await auth.signOut();
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
        setIsLoading(false);
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, []);

    if (isLoading) {
      return (
          <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-600 mb-4"></div>
              <h1 className="text-xl font-black uppercase text-gray-900 dark:text-white">CyBerPhone</h1>
          </div>
      );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'create-group': return <CreateGroupPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={() => setDarkMode(!darkMode)} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} appTheme={appTheme} onThemeChange={setAppTheme} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => {}} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'support': return <SupportPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'ads': return <AdCampaignPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={0} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1 relative">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[80px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''} overflow-x-hidden`}>
                    <div className="max-w-7xl mx-auto min-h-[calc(100vh-140px)]">
                        {renderPage()}
                    </div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

