 */
export const mapUserData = (id: string, dbData: any, authUser?: any): User => {
    // 1. Dados vindos do Firebase Auth (Identidade de Nuvem)
    const authDisplayName = authUser?.displayName || "";
    const authPhotoURL = authUser?.photoURL || "";

    // 2. Prioridade: Firestore Data > Auth Metadata > Fallbacks
    let firstName = dbData?.firstName || dbData?.first_name || authDisplayName.split(' ')[0] || "";
    let lastName = dbData?.lastName || dbData?.last_name || authDisplayName.split(' ').slice(1).join(' ') || "";

    // Se o banco e o display name falharem, usa o e-mail
    if (!firstName && authUser?.email) {
        firstName = authUser.email.split('@')[0];
        firstName = firstName.charAt(0).toUpperCase() + firstName.slice(1);
        lastName = "Membro";
    }

    return {
        id: id,
        userType: dbData?.userType || dbData?.user_type || UserType.STANDARD,
        firstName: firstName || 'Usuário',
        lastName: lastName || 'CyBer',
        email: dbData?.email || authUser?.email || '',
        phone: dbData?.phone || '',
        documentId: dbData?.documentId || '',
        birthDate: Number(dbData?.birthDate || dbData?.birth_date || Date.now()),
        profilePicture: dbData?.profilePicture || authPhotoURL || DEFAULT_PROFILE_PIC,
        followedUsers: dbData?.followedUsers || [],
        followers: dbData?.followers || [],
        balance: Number(dbData?.balance || dbData?.saldo || 0),
        credentials: dbData?.credentials || '',
        bio: dbData?.bio || '',
        storeId: dbData?.storeId || undefined,
        isAdmin: !!dbData?.isAdmin,
        isVerified: !!dbData?.isVerified,
        isOnline: !!dbData?.isOnline,
        lastSeen: Number(dbData?.lastSeen || 0)
    } as User;
};

const cleanData = (obj: any): any => {
  if (Array.isArray(obj)) return obj.map(item => cleanData(item));
  if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    Object.keys(obj).forEach(key => {
      const val = obj[key];
      if (val !== undefined) newObj[key] = cleanData(val);
    });
    return newObj;
  }
  return obj;
};

/**
 * BUSCA DE USUÁRIO (Firestore Only)
 * Se o usuário está logado mas não tem doc no Firestore, cria um.
 */
export const findUserById = async (userId: string, authUserReference?: any): Promise<User | undefined> => {
  if (!userId || !isFirebaseConfigured) return undefined;

  try {
    const docSnap = await getDoc(doc(db, 'profiles', userId));
    const currentAuth = authUserReference || auth?.currentUser;

    if (docSnap.exists()) {
      return mapUserData(userId, docSnap.data(), currentAuth);
    } else if (currentAuth) {
      // AUTO-SYNC: Se logado no Firebase mas sem doc no Firestore, cria o doc
      const newUser = mapUserData(userId, null, currentAuth);
      await setDoc(doc(db, 'profiles', userId), cleanData(newUser));
      return newUser;
    }
  } catch (e) {
    console.error("Erro no Perfil Firestore:", e);
  }
  return undefined;
};

