import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser } from '../services/storageService';
import { AcademicCapIcon, UserIcon, CameraIcon, ArrowPathIcon, EyeIcon, EyeSlashIcon } from '@heroicons/react/24/solid';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');

  const [profileImageFile, setProfileImageFile] = useState<File | null>(null);
  const [profileImagePreview, setProfileImagePreview] = useState<string | null>(null);

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const profileImageInputRef = useRef<HTMLInputElement>(null);

  const handleProfileImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProfileImageFile(file);
      setProfileImagePreview(URL.createObjectURL(file));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password || (isRegister && (!firstName || !lastName))) {
      setError("Preencha todos os campos obrigatórios.");
      return;
    }

    setLoading(true);
    try {
      if (isRegister) {
        const newUser = await registerUser({
          userType,
          firstName,
          lastName,
          email,
          password,
          profileImageFile,
          credentials: userType === UserType.CREATOR ? credentials : ''
        });
        onLoginSuccess(newUser);
      } else {
        const user = await loginUser(email, password);
        onLoginSuccess(user);
      }
    } catch (err: any) {
      setError(err.message || 'Erro na autenticação.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#0a0c10] p-4 font-sans">
      <div className="bg-[#12161f] w-full max-w-lg rounded-[2.5rem] shadow-2xl border border-white/5 overflow-hidden">
        <div className="p-8 md:p-12">
          <div className="text-center mb-10">
            <h1 className="text-4xl font-black text-white tracking-tighter mb-2">EduConnect</h1>
            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Plataforma de Mestres e Alunos</p>
          </div>

          {isRegister && (
            <div className="grid grid-cols-2 gap-4 mb-8">
              <button 
                type="button" 
                onClick={() => setUserType(UserType.STANDARD)}
                className={`p-6 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${userType === UserType.STANDARD ? 'border-blue-600 bg-blue-600/10 text-white' : 'border-white/5 text-gray-500 hover:bg-white/5'}`}
              >
                <UserIcon className="h-8 w-8" />
                <span className="text-xs font-black uppercase">Sou Aluno</span>
              </button>
              <button 
                type="button" 
                onClick={() => setUserType(UserType.CREATOR)}
                className={`p-6 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${userType === UserType.CREATOR ? 'border-purple-600 bg-purple-600/10 text-white' : 'border-white/5 text-gray-500 hover:bg-white/5'}`}
              >
                <AcademicCapIcon className="h-8 w-8" />
                <span className="text-xs font-black uppercase">Sou Mestre</span>
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {isRegister && (
              <>
                <div className="flex justify-center mb-6">
                  <div 
                    onClick={() => profileImageInputRef.current?.click()}
                    className="w-24 h-24 rounded-[2rem] bg-white/5 border-2 border-dashed border-white/10 flex items-center justify-center cursor-pointer overflow-hidden group hover:border-blue-500"
                  >
                    {profileImagePreview ? <img src={profileImagePreview} className="w-full h-full object-cover" /> : <CameraIcon className="h-8 w-8 text-gray-600 group-hover:text-blue-500" />}
                    <input type="file" ref={profileImageInputRef} onChange={handleProfileImageChange} className="hidden" accept="image/*" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className="p-4 bg-white/5 rounded-2xl text-white outline-none border-2 border-transparent focus:border-blue-600 font-bold" />
                  <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className="p-4 bg-white/5 rounded-2xl text-white outline-none border-2 border-transparent focus:border-blue-600 font-bold" />
                </div>
                {userType === UserType.CREATOR && (
                  <input type="text" placeholder="Sua Especialidade (Ex: Prof. de História)" value={credentials} onChange={e => setCredentials(e.target.value)} className="w-full p-4 bg-white/5 rounded-2xl text-white outline-none border-2 border-transparent focus:border-purple-600 font-bold" />
                )}
              </>
            )}

            <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-4 bg-white/5 rounded-2xl text-white outline-none border-2 border-transparent focus:border-blue-600 font-bold" />

            <div className="relative">
              <input type={showPassword ? "text" : "password"} placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-white/5 rounded-2xl text-white outline-none border-2 border-transparent focus:border-blue-600 font-bold" />
              <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-500">
                {showPassword ? <EyeSlashIcon className="h-5 w-5" /> : <EyeIcon className="h-5 w-5" />}
              </button>
            </div>

            {error && <p className="text-red-500 text-[10px] font-bold uppercase text-center">{error}</p>}

            <button type="submit" disabled={loading} className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-3xl font-black uppercase text-sm shadow-xl transition-all flex items-center justify-center gap-2 active:scale-95">
              {loading ? <ArrowPathIcon className="h-6 w-6 animate-spin" /> : (isRegister ? 'Criar minha Conta' : 'Entrar na Rede')}
