          <div className="mt-8 text-center">
            <button onClick={() => setIsRegister(!isRegister)} className="text-xs font-bold text-gray-500 hover:text-blue-500 transition-colors uppercase tracking-widest">
              {isRegister ? 'Já tenho conta? Login' : 'Novo por aqui? Registrar'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

