export const loginUser = async (email: string, password: string): Promise<User> => {
  const userCredential = await signInWithEmailAndPassword(auth, email, password);
  const user = await findUserById(userCredential.user.uid, userCredential.user);
  if (user) return user;
  throw new Error(`Erro ao acessar perfil.`);
};

export const registerUser = async (userData: any): Promise<User> => {
  const userCredential = await createUserWithEmailAndPassword(auth, userData.email, userData.password);
  const uid = userCredential.user.uid;

  let profilePicUrl = userData.profilePicture || DEFAULT_PROFILE_PIC;
  if (userData.profileImageFile) {
     profilePicUrl = await uploadToCloudinary(userData.profileImageFile, 'profiles');
  }

  await updateProfile(userCredential.user, {
    displayName: `${userData.firstName} ${userData.lastName}`,
    photoURL: profilePicUrl
  });

  const newUser = mapUserData(uid, { ...userData, profilePicture: profilePicUrl }, userCredential.user);

  // Se for Mestre (CREATOR), inicializa as ferramentas dele
  if (newUser.userType === UserType.CREATOR) {
      const storeId = crypto.randomUUID();
      newUser.storeId = storeId;
      await setDoc(doc(db, 'stores', storeId), {
          id: storeId,
          professorId: uid,
          name: `Academia de ${newUser.firstName}`,
          description: 'Cursos e mentorias exclusivas.',
          productIds: []
      });
  }

  await setDoc(doc(db, 'profiles', uid), {
      ...newUser,
      balance: 0,
      followedUsers: [],
      followers: [],
      timestamp: Date.now()
  });

  return newUser;
};

