export const createGroup = async (n: string, m: string[], aid: string, d: string, t: any, img: any, p: boolean) => {
    const id = generateUUID();
    let url = '';
    if (img) url = await uploadFile(img, 'groups');
    await setDoc(doc(db, 'chats', id), cleanData({ id, type: 'GROUP', groupName: n, participants: [...m, aid], adminId: aid, description: d, theme: t, groupImage: url, isPublic: p, messages: [] }));
};

