export const handleWalletTransaction = async (uid: string, amt: number, type: string) => {
    const u = await findUserById(uid);
    if(u) {
        const diff = type === 'deposit' ? amt : -amt;
        await updateDoc(doc(db, 'profiles', uid), { balance: (u.balance || 0) + diff });
        return true;
    }
    return false;
};
