export const startPrivateChat = async (uid1: string, uid2: string) => {
    const id = [uid1, uid2].sort().join('_');
    const ref = doc(db, 'chats', id);
    const d = await getDoc(ref);
    if (!d.exists()) {
        await setDoc(ref, { id, type: ChatType.PRIVATE, participants: [uid1, uid2], messages: [] });
    }
    return id;
};
